window.__D("text/maamarei-admur-hazaken/c017",{"p":[[2101920254,"שנאמר ה' חפץ למען צדקו יגדיל כו', וזהו וצדקה תהי' לנו כו' שבחי' צדקה העליונה שהשפיל בעל הרצון א\"ע בתו\"מ תהי' לנו כי נשמור כו' כי כל מצותיו רק צדקה וחסד כו' וד\"ל. ועוד ראי' לזה ממה שנאמר אם<sup data-n=\"1394\">108</sup> צדקת מה תתן לו כו' הרי גם בקיום רצונו במצות מה תתן לו כי הרי בחי' צמצום גדול הוא לגבי בעל הרצון ואין בזה תוס' עילוי לגבי בעל הרצון עצמו מאחר שאין זה הצמצום רק מפני בחי' צדקה וחסד לגבי המקבלי' בלבד אבל לא לגבי עצמותו ממש וזהו מה תתן לו כו' וד\"ל. והיינו בחי' ב' כתרים למעלה א' בחי' ביטול עצמותו שמניח א\"ע כבי' להיות לו רצון בתו\"מ והב' בחי' גילוי רצונו בתו\"מ, והיינו א' כנגד נעשה בחי' ביטול עצמי דכנ\"י מלמטה למעלה והב' כנגד נשמע בחי' ביטול הב' לבחי' רצה\"ע שעי\"ז מתגלה הרצון ממקורו כו' כנ\"ל וד\"ל. וזהו בעטרה שעטרה לו אמו זו היא כנ\"י מלמטה למעלה במ\"ש נעשה לנשמע שעשו לו כבי' ב' כתרים כו' ובעטרה היינו כתר הא' דהקדימו נעשה לנשמע עטרה לו אמו בחי' כתר הב' כי הא בהא תלי' וד\"ל.\n<b>אך</b> הנה מעתה י\"ל מ\"ש בעטרה כו' ביום חתונתו זו מ\"ת דוקא ואם מפני שהקדימו נעשה לנשמע אין זה משום טעם דמ\"ת עצמה רק מה שהקדימו ישראל קודם מ\"ת נעשה לנשמע כנ\"ל. אך הענין הוא דכתיב תען לשוני אמרתך כי כל מצותיך צדק, הרי מה שאמרתך צדק וחסד מבעל הרצון הוא ע\"י שתען לשוני אמרתך דוקא שהוא ע\"י עסק התורה דוקא כנ\"ל שהעטרה שעטרה לו אמו נעשה מאותיות התורה דוקא שנק' אבנים טובות המאירו' כו', ולכאורה אין זה מובן דהלא אורייתא<sup data-n=\"1395\">109</sup> רק מח\"ע נפקת ואיך ביכולתה להמשיך בחי' צדקה וחסד זה דמצות מבעל הרצון כו'. אמנם הנה הגם שנאמר זאת<sup data-n=\"1396\">110</sup> התורה אדם שהתורה בבחי' אדם<sup data-n=\"1397\">111</sup> שם מ\"ה דחכ' היינו רק דאוריי' מח\"ע נפקת כו' אבל<sup data-n=\"1398\">112</sup> שרשה ויסודה היא מבחי' עצמות המאציל שלמעלה מבחי' אדם כמ\"ש כי<sup data-n=\"1399\">113</sup> לא אדם הוא כו' דהיינו שרק בחי' יציאתה מן ההעלם לגילוי הוא מן החכ' אבל שרשה העצמי הרי נאמר ואהי'<sup data-n=\"1400\">114</sup> אצלו אמון כו', והענין הוא דכתיב וממדבר<sup data-n=\"1401\">115</sup> מתנה שהתורה נתנה במתנה מבחי' מדבר דוקא שהוא בחי' ומדריגה עליונה למעלה מבחי' אדם כמו במדבר גשמי דכתיב בי' אשר<sup data-n=\"1402\">116</sup> לא עבר בה איש ולא ישב אדם שם שאין שם ישיבה לאיש ואדם כלל להיותו למעלה מבחי' אדם לפי ששורש בחי' אדם הוא רק מבחי' החכ' ולמטה (שהרי אנו רואים באדם התחתון שעיקר בחי' אדם",[["1394","108","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["1395","109","<b>אורייתא רק מח\"ע נפקת</b>: נסמן לעיל."],["1396","110","<b>זאת התורה אדם</b>: חוקת יט, יד."],["1397","111","<b>אדם שם מ\"ה</b>: ראה ע\"ח שער התיקון (ש\"י) פ\"ג. ובהמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"ב לע' תקסז."],["1398","112","<b>אבל שרשה ויסודה הוא מעצמות המאציל</b>: ראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תסא. וש\"נ."],["1399","113","<b>כי לא אדם הוא</b>: שמואל א טו, כט."],["1400","114","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1401","115","<b>וממדבר מתנה</b>: חוקת כא, יח."],["1402","116","<b>אשר לא עבר בה איש</b>: ע\"פ ירמי' ב, ו. [וכהל' כאן כ\"ה גם בלקו\"ת ד\"ה זה — שה\"ש כב, א]."]]],[2101920255,"שבו הוא בחי' פרצוף פנים שלו שנק' פני אדם והוא המוחין שבראש והחוטם כו' אבל בעצם הגולגולת והמצח הוא למעלה מבחי' אדם עדיין כו') אבל למעלה מבחי' החכ' נק' מדבר שלא ישב אדם שם לפי שאין אור העליון שלמעלה מבחי' החכמה מתיישב שם בבחי' מוחין דאדם רק בבחי' הארה בעלמא כמ\"ש והחכ'<sup data-n=\"1403\">117</sup> מאין תמצא כו'. וכך למעלה בבחי' שורש חכמה דתורה שלוקח מקור שרשה ויסודה מלמעלה מן החכ' שנק' מדבר למעלה שלא עבר בה איש, כי כאשר הקב\"ה נק' איש כמו ה'<sup data-n=\"1404\">118</sup> איש מלחמה היינו כשכבר נמשך בבחי' שם הוי' יו\"ד<sup data-n=\"1405\">119</sup> דחכ' ה\"א בינה כו' שמזה נעשה מלחמה בעמלק כמ\"ש מלחמה<sup data-n=\"1406\">120</sup> להוי' בעמלק לפי שאין<sup data-n=\"1407\">121</sup> שמו שלם וכן ביצי\"מ נאמר ה' איש מלחמה לנצח מדה\"ד והצמצום כידוע וכן כשנק' אדם הוא בבחי' שם מ\"ה גימטרי' אדם (כמ\"ש בזוהר<sup data-n=\"1408\">122</sup> בהפרש שבין אדם לאיש שבאיש אין בו רק מוחין דאבא ואדם<sup data-n=\"1409\">123</sup> א' ד\"ם כלול ממוחין דאו\"א כו') וע\"כ גם כשהתורה בבחי' אדם כמ\"ש זאת התורה אדם כו' אבל שרש יסודה למעלה מבחי' אדם וז\"ש ממדבר מתנה כו' ושרשה בעצמיות אא\"ס שלמעלה מבחי' אדם שלא עבר שם איש ואדם כו' ומשם נמשך דוקא כתר ועטרה על הראש ומוחין דאדם העליון להיותו למעלה מבחי' ראש ומוחין דאדם, וזהו בעטרה שעטרה לו אמו ע\"ג הראש ומוחין במ\"ת דוקא מצד שרשה בעצמות כנ\"ל, ומ\"מ מי הוא הנותן העטרה ע\"ג הראש היא אמו כנ\"י ע\"י שאמרו נעשה ונשמע שהמשיכו נתינת הכתרים למעלה אבל גוף העטרה נעשה מאותיות התורה דוקא עד\"מ עטרה שכבר עשוי' מאבנים טובות והמכתיר נותנה ע\"ג הראש בלבד כו' וד\"ל.\n<b>וזהו</b> צאינה וראינה בנות ציון במלך שלמה דהנה שלמה בה\"א להיות ענין מלך שלמה היינו מלך<sup data-n=\"1410\">124</sup> שהשלום שלו ע\"כ כתיב שלמה בה\"א. והענין הוא להיות ידוע שעצמות אא\"ס ב\"ה כשמו כן הוא בבחי' א\"ס ואין תכלית כו' והוא קדוש ומובדל בערך מהיות בחי' מקור למקור להשתל' העולמות להיות בתכלית האחדות הפשוטה ובחי' ההמשכה להיות השתלשלות העולמות הרי זה בא בבחי' גבו' והתחלקות וריבוי כו' אשר זהו היפך גמור לבחי' אח\"פ כידוע וא\"כ לכאורה איך נמשך מאח\"פ להיות השתלשלות העולמות בע\"ג ותכלית שהרי נאמר כי<sup data-n=\"1411\">125</sup> ממך הכל כו' מאחר שההמשכה הזאת היא מן ההיפוך להיפוך לגמרי. אך הענין",[["1403","117","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["1404","118","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["1405","119","<b>הוי' יו\"ד דחכ' ה' בינה</b>: ראה זח\"ז יז, א. ת\"ז בהקדמה ו, ב. תניא אגה\"ת פ\"ד."],["1406","120","<b>מלחמה לה' בעמלק</b>: בשלח יז, טז."],["1407","121","<b>שאין שמו שלם</b>: ראה רש\"י בשלח שם. תנחומא ס\"פ תצא. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ נ\"ך ע' יב."],["1408","122","<b>בזוהר בהפרש שבין אדם לאיש</b>: ע\"פ זח\"ג מח, א. וראה ס' מאמרי אדה\"ז תקס\"ז ע' קז. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תעד."],["1409","123","<b>ואדם א' ד\"ם</b>: ראה של\"ה כא, א. מאמרי אדהאמ\"צ ויקרא שם ע' תנא ואילך. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תמב."],["1410","124","<b>מלך שהשלום שלו</b>: שבועות לה, ב. שהש\"ר ע\"פ צאינה וראינה (ג, יא). ועוד."],["1411","125","<b>כי ממך הכל</b>: דה\"א כט, יד."]]],[2101920256,"הוא שיש בחי' ומדריגה המחבר את בחי' ההמשכה הזאת מאח\"פ להיות מקור לעולמות וה\"ז כמו בחי' ממוצע המחבר ב' הפכים ממש שנק' שלום כמו כל עושה שלום שמחבר ב' הפכים כידוע, ומי הוא בחי' הממוצע העושה השלום לחבר ב' הפכים הללו הוא ענין ובחי' מלך דהיינו במה שעלה במח' הפשוטה אנא<sup data-n=\"1412\">126</sup> אמלוך שנק' מל' דא\"ס כו'. וביאור הדברים הנה אנו אומרים יחיד<sup data-n=\"1413\">127</sup> חי העולמים מלך פי' יחיד שהוא לבדו ואין עוד זולתו שיהי' לו חיבור כלל ולא כמו ראשון שיש לו שני המחבר אליו כידוע, אך מה שנעשה חי העולמים בחי' מקור להן אין זה מצד שיש להן ערך וחיבור אליו אלא ע\"י בחי' אמצעי ביניהן והוא בחי' מלך שעלה במח' הפשוטה אנא אמלוך, דגם שבודאי גם בחי' מחשבה זו דאנא אמלוך כלולה בעצמותו בבחי' אח\"פ עדיין אך מ\"מ יש בה חיבור להיות מקור לעולמות להיות כי אין<sup data-n=\"1414\">128</sup> מלך בלא עם כידוע (וזהו שבחי'<sup data-n=\"1415\">129</sup> מל' דא\"ס נעשה בחי' כתר דא\"ק כו' כמ\"ש בע\"ח כמו שמבחי' מל' דאצי' נעשה כתר לבריאה שהוא בחי' ממוצע לחבר אצי' בבריאה כו' וד\"ל), וזהו פי' מלך שהשלום שלו שבחי' מלך הוא המחבר ועושה השלום לחבר ב' הפכים מאחדות פשוטה בעולמות ע\"כ נק' מלך שהשלום שלו כו' וד\"ל. וזהו שלמה בה\"א שהוא בחי' ה\"א תתאה דשם הוי' שזהו בחי' התפשטות המלוכה בעולמות כמ\"ש מלכותך<sup data-n=\"1416\">130</sup> מלכות כ\"ע כו' והיינו שבחי' השלום הזה שהוא החיבור דאור א\"ס למטה נמשך עד בחי' ה\"א תתאה להחיות רוח שפלים ממש מאין ליש שהן ד' עולמות דאבי\"ע שבחי' ה\"א זו היא המהווה ומחי' מאין ליש ממש ומוציאה מן ההעלם לגילוי גמור ומן הכח אל הפועל ממש כידוע והיינו שלמ\"ה בה\"א דוקא שזהו תכלית השלו\"ם וד\"ל. אך מי הוא הגורם להיות בחי' שלום והתחברות זו ע\"י בחי' אנא אמלוך הנ\"ל היינו בעטר\"ה שעטר\"ה לו אמו דוקא שהוא בחי' כתר מל' הנעשה ע\"י אתדל\"ת בעסק התורה וע\"י בחי' ביטול דנעשה ונשמע שקודם עסק התורה כנ\"ל וזהו ור\"ב<sup data-n=\"1417\">131</sup> שלום בניך אלו ת\"ח כו' וד\"ל.\n<b>והנה</b> הנשמות שבג\"ע יש בהן ב' מדריגות הא' הנק' בנות ירושלים והב' הנק' בנות ציון, בנות ירושלים הן הנשמות הכלולים בבחי' מל' דאצי' (ונק' נערות אסתר<sup data-n=\"1418\">132</sup> וכיוצא בזה נא' בתולות<sup data-n=\"1419\">133</sup> אחרי' כו') והיינו נשמות שלא נתלבשו",[["1412","126","<b>אנא אמלוך</b>: ראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתצד."],["1413","127","<b>יחיד חי העולמים מלך</b>: בברכת ברוך שאמר."],["1414","128","<b>אין מלך בלא עם כידוע</b>: בחיי וישב לח, ל. וראה בהמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"ב לע' תרלא."],["1415","129","<b>שבחי' מל' דא\"ס נעשה בחי' כתר דא\"ק כו' כמ\"ש בע\"ח</b>: ראה ע\"ח שער סדר אצי' (ש\"ג) פ\"ב. שער העקודים (ש\"ו) פ\"ב. שער דרושי אבי\"ע (שמ\"ב) ספ\"א. ועוד. וראה ס' מאמרי אדה\"ז על ענינים ע' א (ובהמ\"מ שם)."],["1416","130","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."],["1417","131","<b>ורב שלום בניך אלו ת\"ח</b>: ע\"פ ישעי' נד, יג. סוף מס' ברכות."],["1418","132","<b>נערות אסתר</b>: ע\"פ אסתר ד, ד. וראה תו\"א מג\"א קיח, ב. וראה זח\"ב רס, ב."],["1419","133","<b>בתולות אחרי'</b>: תהלים מה, טו."]]],[2101920257,"ובאו בגופי' כלל וע\"כ נק' בנות ירושלים<sup data-n=\"1420\">134</sup> יראה שלם שמקבלים מבחי' הארת אור א\"ס שלימותא דכולא שנק' יראה שלם (להיות עיקר הבריאה יש מאין הוא בבחי' הגוף והחומר לצורה אבל מ\"ש באדה\"ר ויפח באפיו<sup data-n=\"1421\">135</sup> נשמת חיים נשמה זו בבחי' אצי' היתה בלי שינוי המהות, שבאצי' עדיין אין פרגוד ומסך להפסיק הארת הקו משא\"כ נשמות דבריאה שהן לאחר הבדלת המסך כו' וכמ\"ש<sup data-n=\"1422\">136</sup> במ\"א בענין שחורה אני כו') כי מה שהמלאכים אינם מקבלים גילוי אור אלקי רק כפי מדתם בצמצום אבל ביתר מכפי המדה מתבטלים ממציאותם לגמרי כמו הושיט<sup data-n=\"1423\">137</sup> אצבעו קטנה שהוא יתר מכפי הצמצום ושרפם כו' היינו רק מצד בחי' הכלי והחומר שלהם בלבד דידוע שיש לכל מלאך נפש וגוף וגופים שלהם נעשה מיסוד האש והרוח הרוחניי' כו' כמ\"ש עושה<sup data-n=\"1424\">138</sup> מלאכיו רוחות משרתיו אש כו' כמ\"ש הרמב\"ן וכמ\"ש בע\"ח ודוקא מצד בחי' החומר שלהם לא יכלו לקבל יותר מכפי המדה שלהם שלא יתבטל חומר שלהם ויוכלל נפשם באור האלקי כו' אבל הנשמות שבלא חומר וגוף יכולים לקבל הארת אא\"ס כמו שהוא בעצם כמו נשמת אליהו שאמר חי<sup data-n=\"1425\">139</sup> ה' אשר עמדתי לפניו ממש ולא נתבטל ממציאותו כי הנשמות הללו כלולים במאציל והיו לאחדים (כמו רשב\"י שאמר בחד<sup data-n=\"1426\">140</sup> קטירא אתקטרנא בי' אחידא כו').\n<b>ובנות</b> ציון הן הנשמות שבאו בגופי בנ\"א בעוה\"ז ויצאו מגופים שלהם לג\"ע ליהנות מזיו השכינה וע\"כ נק' בנות ציון ל' מצויין כמו שאמרו ת\"ח<sup data-n=\"1427\">141</sup> שבבבל מצויינים בהלכה כו' פי' שמלובשים בלבוש חשוב שהוא ניכר ומסויים (כי ציון ל' אות ההיכר וההבדל על דבר מה כו') והוא ענין ובחי' הלבושים שנעשו לנשמה זו מעסק התו\"מ בעוה\"ז שנק' מצויינים בג\"ע וכמו שאמרו<sup data-n=\"1428\">142</sup> אשרי מי שבא לכאן ותלמודו בידו שנעשה לבוש מסויים וניכר שעל ידו דוקא יוכל להנות ולהסתכל באור האלקי בג\"ע כמו עד\"מ שא\"א להסתכל באור בהיר ביותר כ\"א ע\"י כלי הנק' אספקלריא וכמו כל הנביאים שלא יכלו להסתכל ולהשיג באלקי' במראה הנבואה כ\"א ע\"י אספקלריא אלא שמשה<sup data-n=\"1429\">143</sup> ראה באספקלריא אחת ושאר הנביאים ע\"י ז' אספקלריאות כידוע וד\"ל.",[["1420","134","<b>ירושלים יראה שלם</b>: ראה ב\"ר פנ\"ו, י. ובכ\"מ."],["1421","135","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["1422","136","<b>וכמ\"ש במ\"א בענין שחורה אני</b>: ראה לקו\"ת שה\"ש ה, ג ואילך (ובהמ\"מ שם)."],["1423","137","<b>הושיט אצבעו קטנה</b>: סנהדרין לח, ב. ועוד."],["1424","138","<b>עושה מלאכיו רוחות . . כמ\"ש הרמב\"ן וכמ\"ש בע\"ח</b>: תהלים קד, ד. ראה סידור ערה, ב ־ בשם ”ספר הגמול\" להרמב\"ן. וראה גם תו\"א ד, ב. לקו\"ת ברכה צח, א. לקוטי שיחות ח\"ט ע' 405. ובארוכה בהמ\"מ בס' מאמרי אדהאמ\"צ בראשית ע' קיב."],["1425","139","<b>חי ה' אשר עמדתי לפניו</b>: מלכים א יז, א. ועוד."],["1426","140","<b>בחד קטירא אתקטרנא בי' אחידא</b>: ע\"פ זח\"ג רפח, א. רצב, א."],["1427","141","<b>ת\"ח שבבבל מצויינים בהלכה</b>: שבת קמה, ב."],["1428","142","<b>אשרי מי שבא לכאן ותלמודו בידו</b>: פסחים נ, א. ועוד."],["1429","143","<b>שמשה ראה באספקלריא אחת ושאר הנביאים ע\"י ז' אספקלריאות כידוע</b>: ראה ויק\"ר פ\"א, יד. יל\"ש ויקרא רמז תלב. ובהמ\"מ בסו\"ס הלקו\"ת (שה\"ש כב, ב)."]]],[2101920258,"<b>וזהו</b> שנק' בנות ציון מלובשים בלבושי' דמצות מעשיות שבעוה\"ז כמ\"ש ימים<sup data-n=\"1430\">144</sup> יוצרו ולא אחד בהם שבכל יום ויום נעשה בחי' לבוש ע\"י המצוה שעושה ביום זה ואי חסר מצוה חסר לבוש א' כמ\"ש בזהר<sup data-n=\"1431\">145</sup> ע\"פ ואברהם זקן בא בימים כו' והיינו שימים ניתנו לאדם שיהי' אחד שורה בהן ע\"י המצות שנעשים בדברים גשמי' דנוגה דוקא כמ\"ש במ\"א ומצות<sup data-n=\"1432\">146</sup> ת\"ת כנגד כולן ע\"כ א' ותלמודו בידו דוקא וד\"ל.\n<b>אך</b> הנה כל עיקר תועלת בחי' הלבוש הזה בג\"ע לנשמה אינו רק כדי שתוכל לקבל האור והזיו האלקי שהוא דוקא בבחי' החכמה שנק' אור רק שהוא אור בהיר ונפלא ביותר שא\"א להשיגו כ\"א ע\"י בחי' לבוש וכלי כמו חכמת<sup data-n=\"1433\">147</sup> אדם תאיר פניו וכן באור פניך נתת לנו תורת חיים הרי בחי' הארת פנים זו שמאיר בחכמת אדם העליון הוא שנק' זיו השכינה שא\"א לנשמות לקבל להיותו אור מופלא ביותר אלא ע\"י בחי' לבוש שיש להן ע\"י התו\"מ בעוה\"ז כנ\"ל, כי מבחי' בירורים דתו\"מ בעוה\"ז יוכלו להסתכל בהארת פנים דחכמת אדם העליון שהוא עצמו ענין התו\"מ ברוחני' האלקי' כו' (וה\"ז כמו ענין המסוה על פני משה כו') אבל בבחי' העטרה שעטרה לו אמו שנק' כת\"ר מל' הרי הוא למעלה מעלה מבחי' החכמה דתורה כנ\"ל באריכות שהוא למעלה מבחי' אדם כמ\"ש ממדבר<sup data-n=\"1434\">148</sup> מתנה כו' אשר<sup data-n=\"1435\">149</sup> לא ישב אדם שם כו' שאין לבחי' חכמת אדם השגה שם כלל כי החכמה מאין תמצא רק בבחי' הארה בעלמא כו', ע\"כ אין בחי' עטרה וכתר זה נק' אור המאיר כאור חכמה המאיר שיצטרך אליו בחי' לבוש להסתכל בו כי זהו בחי' עצם רצון העליון שלמעלה מן החכמה שיכולים הכל לקבל כמו שהוא בלי אמצעו' לבוש מאחר שא\"צ השגה וטעם אלא הוא למעלה מן הטעם ע\"כ אדרבה היא הנותנת שבעטרה זו א\"צ לבוש כלל וד\"ל.\n<b>וזהו</b> צאינה וראינה בנות ציון פי' צאינה שתצאנה בנות ציון שהן הנשמות המלובשות בג\"ע בלבושים דתו\"מ שעסקו בעוה\"ז מלבושי' הללו, כי אין מהצורך לבחי' הלבושים הללו רק כדי שיוכלו להסתכל ולהשיג באור חכ' הנפלאה הרבה מהן שהוא בחי' או\"ר פני\"ך שנתת לנו תורת חיים כנ\"ל אבל לראות בעטרה שעטרה לו אמו שהוא למעלה ע\"ג הראש שזהו למעלה מבחי' החכמה דאדם שלא ישב אדם שם להיותה למעלה מן ההשגה והחכמה כנ\"ל ומאחר שאין כח ההשגה והחכמה מגיע לשם כלל ע\"כ אין מהצורך ללבושים להסתכל על ידן אלא בלא לבוש יכולים לראות וע\"כ אמר צאינה וראינה צאינה מן הלבושים שלכם וראינה בעטרה שעטרה כו', ודוקא לבנות ציון הוא אומר שהן",[["1430","144","<b>ימים יוצרו</b>: תהלים קלט, טז."],["1431","145","<b>בזהר ע\"פ ואברהם זקן</b>: ראה זח\"א קכט, א. רכד, א."],["1432","146","<b>ומצות ת\"ת כנגד כולן</b>: פאה רפ\"א."],["1433","147","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["1434","148","<b>ממדבר מתנה</b>:"],["1435","149","<b>אשר לא ישב אדם שם</b>: ירמי' ב, ו."]]],[2101920259,"בבחי' לבושים ולא לבנות ירושלים שא\"צ ללבושים כלל כנ\"ל (ואע\"פ שהלבושים עצמן הרי הן נעשים ממעשה המצות ואותיות התורה שבאו בגשמיות כנ\"ל ומהן עצמן נעשה העטרה ע\"ג הראש כנ\"ל ואיך נעשו לבושים להסתכל בהן באור החכמה מאחר ששרשן הוא בבחי' עטרה שלמעלה מן אור החכמה כו', הענין הוא משום דבחכמה<sup data-n=\"1436\">150</sup> אתברירו דוקא כידוע וכל מה שנברר ברורי נוגה במצות מעשיות הכל הוא ע\"י החכמה שבתורה כו' וע\"כ נעשה בחי' לבוש להסתכל על ידו באור פנימי' ח\"ע שבתורה אבל מה שנעשה בחי' עטרה ע\"ג הראש מן המצות ומאותיות התורה ה\"ז בבחי' הרצון העליון שלמעלה מן החכמה וכמו לעתיד דכתיב לא<sup data-n=\"1437\">151</sup> יכנף עוד כו' והיו עיניך רואות עין בעין כו' דהיינו שבחי' רצון העליון שבכל מצוה יתגלה שמזה נעשה בחי' העטרה, שא\"צ להיות בבחי' לבוש כ\"א בבחי' הבירורים שבחכמה משא\"כ לאחר הבירור דכתיב ולא יכנף עוד כו' וד\"ל. ובזה יתורץ מה שאמר את<sup data-n=\"1438\">152</sup> אשר ישנו פה ואת אשר איננו פה כו' הרי גם בחי' בנות ירושלים הנ\"ל היו במ\"ת לראות בעטרה שעטרה לו כו' אע\"פ שאין להם לבושים כו', כי א\"צ ללבוש לראות בעטרה שזהו לאחר הבירור כו' וד\"ל).",[["1436","150","<b>דבחכמה אתברירו</b>: ראה זח\"ב רנד, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' רצה. ובכ\"מ."],["1437","151","<b>לא יכנף עוד</b>: ישעי' ל, כ."],["1438","152","<b>את אשר ישנו פה ואת אשר איננו פה</b>: נצבים כט, יד. וראה שבת קמו, א. שבועות לט, א. פדר\"א פמ\"א. שמו\"ר פכ\"ח, ו. תנחומא יתרו יא. ובכ\"מ."]]],[2101920260,"<h3>שוש תשיש</h3>\n<b>שוש</b><sup data-n=\"1439\">1</sup> תשיש<sup data-n=\"1440\">2</sup> ותגל העקרה בקיבוץ בניה לתוכה בשמחה, הנה תשיש יש בו ב' פירושים א' פועל יוצא ופירושו תשיש אתה את העקרה בקיבוץ בניה כו', והב' פועל עומד כלומר שאתה תשיש ועי\"ז תגל בקיבוץ בניה כו', ולהבין כ\"ז צריך להבין תחילה מ\"ש תגל העקרה בקיבוץ בניה דלכאורה האי קרא לאו רישי' סיפי' דעקרה היינו שלא ילדה וא\"כ מהו קיבוץ בני' ואם יש לה בנים אינה עקרה כו'.\n<b>הנה</b> ארז\"ל<sup data-n=\"1441\">3</sup> ע\"פ אשה כי תזריע וילדה זכר אשה מזרעת תחילה יולדת זכר איש מזריע תחילה יולדת נקבה פי' דקוב\"ה ובנ\"י הם הנק' חתן וכלה או איש",[["1439","1","<b>שוש תשיש</b>: מאמר זה נאמר ע\"י כ\"ק אדמו\"ר הזקן בשנת תקע\"ב (בסמיכות לפ' תצוה), על חתונת נכדו הרב מנחם נחום בן כ\"ק אדמו\"ר האמצעי. והוא נו\"א ובשינויים מד\"ה זה בלקו\"ת תזריע כ, א. וראה גם ד\"ה זה באריכות בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' שיז.\nהמאמר הובא גם בדרמ\"צ קלז, ב: ע\"פ מה ששמענו בחורף תקע\"ב בחתונת גיסי וב\"ד [ובן דודי] ר' נחום נ\"י ע\"פ מ\"ש שוש תשיש כו'. ובהמשך הוא מביא שם את תוכן המאמר, בתוס' הגהות."],["1440","2","<b>שוש תשיש ותגל העקרה</b>: נוסח ברכות נישואין."],["1441","3","<b>ארז\"ל ע\"פ אשה כי תזריע וילדה זכר אשה מזרעת תחילה יולדת זכר</b>: תזריע יב, ב. ברכות ס, א. נדה לא, א. וראה במ\"מ בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' רכא."]]],[2101920261,"ואשה, ופי' אשה כי תזריע כלומר שזרעה קודם לזרע האיש דהיינו שיש אתעדל\"ת מלמטה ואח\"כ נמשך עי\"ז אתדל\"ע והוא זרע האיש הבא אח\"כ, אזי יולדת זכר פי' שההולדה שהאשה יולדת אח\"כ מטפת האיש הוא זכר, ובנמשל למעלה בכנס\"י היינו שההולדה שנעשה בנשמות ישראל מאתעדל\"ע אשר ה' ית' מערה רוחו עליהם ממרום אחר קדושת אתעדל\"ת שלהם הוא בחי' זכר והוא בחי' אהבה רבה ועצומה לה' ית', שהוא הנק' בשם זכר כמ\"ש זכר<sup data-n=\"1442\">4</sup> חסדו כו', והוא מ\"ש דוד מי<sup data-n=\"1443\">5</sup> לי בשמים ועמך לא חפצתי בארץ שאינו חפץ בשום דבר מה שהוא בחי' עמך כלומר אפי' ג\"ע התחתון וג\"ע העליון שבו<sup data-n=\"1444\">6</sup> יושבין הנשמות ונהנין מזיו כו' בכולם אין לו חפץ להיותם בחי' עמך כלומר שהם רק הארה בלבד מעצמותו ית' כו' הרי מהותו ועצמותו ית' אין לו תחילה ותכלה וא\"א לשום נברא שהוא בע\"ג ומחודש מאין ליש להיות נהנין ממנו כו' כ\"א מבחי' זיו בלבד ממנו ית' שהוא המאיר ומתגלה בהשגות הנשמות שבג\"ע וזהו שאמרז\"ל<sup data-n=\"1445\">7</sup> ע\"פ כי בי\"ה הוי' צור עולמים ביוד נברא העולם הבא שהיוד הוא נקודה א' במדור הנשמות הצדיקים הנהנין מזיו כו'. וזהו הנק' בחי' ועמך וע\"ז אמר דוד הע\"ה ועמך לא חפצתי כ\"א למהותו ועצמותו ית' דווקא, הגם שא\"א להנות ממנו ולתופסו בהשגתו, כי הנאה אינה אלא מדבר המושג דווקא ובאא\"ס ב\"ה לית<sup data-n=\"1446\">8</sup> מחשבה תפיסא בי' כלל מ\"מ הוא חפץ לדבקה בו גם שלא להנות מאומה כ\"א להבטל באור כ\"ח<sup data-n=\"1447\">9</sup> ויותר טוב לו ביטול במקור החיים מהנות מזיו והארה א' בלבד שבג\"ע, ואהבה נפלאה כזו הוא הנק' בשם דכר ונוקבא<sup data-n=\"1448\">10</sup> בעלמא דדכורא כמ\"ש. והנה הולדת אהבה זו בלב איש ישראל אינה באה מלמעלה אלא ע\"י קדימת אתדל\"ת דווקא שבאתדל\"ת נמשך אתעדל\"ע ממקום גבוה מאוד נעלה עד שנתהווה הלידה מזה בחי' זכר, וזהו אשה מזרעת תחילה בהעלאת מ\"נ אזי היא גופא יולדת זכר מטפת דכורא הנמשך ע\"י מ\"נ שלה, אבל אם איש מזריע תחילה שאין אתדל\"ת ובחי' מ\"נ מלמטה כלל אלא שהאיש בעצמו ומאליו מתעורר להשפיע והיינו שה' ית' מצד עצמו כי<sup data-n=\"1449\">11</sup> חפץ חסד הוא, מעורר לב נשמות ישראל בהופע עליהם הארה ממרום כמ\"ש עד<sup data-n=\"1450\">12</sup> יערה עליהם רוח ממרום, וכן א' החזירנו בתשובה שלימה לפניך כו', ואזי האשה יולדת נקבה כו' כלומר שההולדה שנעשה בישראל מהתעוררות זו שה' ית' מעורר",[["1442","4","<b>זכר חסדו</b>: תהלים צח, ג. וראה יהל אור להצ\"צ עה\"פ (ע' שנו ואילך). ובהנסמן במילואים להמ\"מ בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"א ע' שג."],["1443","5","<b>מי לי בשמים</b>: תהלים עג, כה. וראה דרמ\"צ שם קלח, סע\"א. ובמ\"מ וציונים שם."],["1444","6","<b>שבו יושבין הנשמות ונהנין מזיו</b>: ברכות יז, א."],["1445","7","<b>שאמרז\"ל ע\"פ כי בי\"ה הוי' צור עולמים ביוד נברא העולם הבא</b>: ישעי' כו, ד. מנחות כט, ב."],["1446","8","<b>לית מחשבה תפיסא בי' כלל</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["1447","9","<b>כ\"ח</b>: כ\"ה בכת\"י המעתיק. וצ\"ב."],["1448","10","<b>ונוקבא בעלמא דדכורא</b>: אולי חסר כאן כמה תיבות (או שיש כאן טעות מעתיק). ובלקו\"ת תזריע שם: וכמו מעלת הזכר על הנקבה."],["1449","11","<b>כי חפץ חסד הוא</b>: תהלים צח, ג."],["1450","12","<b>עד יערה עליהם רוח ממרום</b>: ישעי' לב, טו."]]],[2101920262,"מעצמו הוא בחי' אהבה זוטא שבעלמא דנוקבא, והיא בחי' אהבה ע\"מ לקבל פרס כלומר שעובד ה' כדי להנות מזיו השכינה בג\"ע שהוא הנק' בשם פרס מלשון פרוסה כי הארה א' בלבד היא המושגת בג\"ע לנשמות הנהנין מזיו אבל א'<sup data-n=\"1451\">13</sup> עכ\"פ מ\"מ בזאת חפץ דווקא כי אהבתו הוא בבחי' לגרמי' שיהי' הוא נהנה ומרגיש תענוג ואין לו חפץ בנסתרות לאשתאבא<sup data-n=\"1452\">14</sup> בגופא דמלכא וליבטל באורו ית' כי מה לו בהתכללות זאת עם היותה במקום רם ונשא מאד אבל ביותר<sup data-n=\"1453\">15</sup> הוא יתבטל לו ממציאותו ולא ירגיש מאומה ומסתפק במועט יותר לקבל רק מהארה א' ובלבד שנהנה הוא כו' ואהבה זו קטנה בערך ולכן נק' בשם נקבה א' שאין לה קיום כי מיד אחר התפילה חולפת ועוברת, ועוד דנשים<sup data-n=\"1454\">16</sup> דעתן קלות ובחי' אהבה זו היא בדעה קלה שמדחה<sup data-n=\"1455\">17</sup> חייי עולם מקור החיים ובוחר לעצמו חיי ג\"ע שהוא רק מהארה א' בשביל לגרמי' שלו כו', וכ\"ז מפני שהאיש מזריע תחילה שההארה מלמעלה היא בלי קדימת אתדל\"ת ואינה ממקום גבוה כ\"כ ואינו פועל רק להיות אשה זו כנ\"י יולדת נקבה בלבד.\n<b>והנה</b> בזמן הזה ובבחי' זאת שאין אתדל\"ת מלמטה רק שה' ית' מעורר מלמעלה ופועל ישועות בהם להיות להם בחי' אהבה כו' אזי נק' כנס\"י שהוא כללות נשמות ישראל בשם עקרה היינו שאינה מולדת מעצמה ואינה מזרעת מצד עצמה אלא האיש מזריע תחילה וע\"י זה יולדת היא אח\"כ ואז יולדת נקבה כו'.\n<b>ואמנם</b> כ\"ז הוא עפ\"י השתלשלות היינו בחי' שנמדד עפ\"י קו המדה שכך וכך ראוי שבאם שאשה כי תזריע ויהי' אתדל\"ת מלמטה אזי יהי' נמשך אתדל\"ע מלמעלה באופן שתהי' יולדת מזה בחי' זכר כנ\"ל, ואם שאין אתדל\"ת מלמטה רק צ\"ל אתדל\"ע מצד עצמו מלמעלה אזי לא יהי' המשכת הארה כ\"א<sup data-n=\"1456\">18</sup> שתיכף לילד נקבה בלבד לפי שבעצמו מעוררם, דים לעוררם בבחי' אהבה זוטא ואינם ראוים יותר, אבל בגילוי הארת עצמותו ית' שלמעלה מהשתל'<sup data-n=\"1457\">19</sup> אזי מתמתקים כל הדינים ואזי יצווה חסדו לעוררם מלמעלה גם כי אין אתדל\"ת כלל באופן היותר יאות והיותר טוב דהיינו בבחי' אהבה רבה הנק' בשם זכר כנ\"ל.\n<b>וזהו</b> שוש תשיש ותגל העקרה בקיבוץ בניה כו' כי הנה מבואר למעלה ענין השמחה שהוא התגלות פנימיות החיות הצפון ונעלם תמיד שבעת שמחתו הוא מתגלה החוצה ולמעלה היינו המשכות והתגלות אא\"ס ב\"ה הסכ\"ע, כנודע שסובב אין פי' שמקיף מלמעלה אלא שהוא בבחי' העלם, ואמנם לפעמים כשנמשך",[["1451","13","<b>א' עכ\"פ</b>: כ\"ה בכת\"י המעתיק. וצ\"ב."],["1452","14","<b>לאשתאבא בגופא דמלכא</b>: זח\"א ריז, ב."],["1453","15","<b>ביותר הוא יתבטל לו</b>: כ\"ה בכת\"י המעתיק: וצ\"ב."],["1454","16","<b>דנשים דעתן קלות</b>: ע\"פ שבת לג, ב."],["1455","17","<b>שמדחה</b>: תיבה זה אינה ברורה בהכת\"י."],["1456","18","<b>כ\"א שתיכף לילד</b>: תיבות אלו אינן ברורות."],["1457","19","<b>מהשתל'</b>: בהכת\"י: מהשם ית'. וניכר שהוא טעות המעתיק."]]],[2101920263,"מהעלם אל הגילוי וכמ\"ש יאר<sup data-n=\"1458\">20</sup> ה' פניו אליך פי' פנימיותו וזהו ענין השמחה והמתקות כל הדינים והגבורות והצמצומים הראוים להיות עפ\"י קו המדה שמגביל כל דבר בגבולים ובצמצומים כנודע כו' בחי' זו הוא למעלה מקו המדה כידוע שהוא ית' א\"ס ואין לו תחילה ואין לו תכלה כו'.\n<b>וזהו</b> שוש תשיש אם כפי' הא' שוש תשיש אתה בשמחתך והוא ענין התגלות פנימיות אלקותו ית' מההעלם אל הגילוי אזי מזה ימשך להיות תגל העקרה זו כנס\"י שנק' עקרה בזמן שאין אתדל\"ת מלמטה ואינה יוכל להזריע תחילה זולת מה שמקבלת מלמעלה מזרע האיש ואז אינה יולדת אלא נקבות שהוא בחי' אהבה זוטא ולכן אינה שמחתה, וכ\"ז אינו אלא כשהנהגה הארה<sup data-n=\"1459\">21</sup> מלמעלה הוא עפ\"י קו המדה אבל בהגלות נגלות הארת עצמותו ית' מלמעלה מקו המדה שזהו וענין שוש תשיש כפי' הא' כנ\"ל אזי יומשך להיות תגל העקרה, ובמה בקיבוץ בניה לתוכה, ופי' בני' היינו זכרים דהיינו תחת אשר מקדם לא היתה אלא נקבות עתה יתהפכו לזכרים דהיינו שמאהבה זוטא שיהי' להם ע\"מ לקבל פרס יתהפך להיות להם אה\"ר כענין מי לי בשמים ועמך לא חפצתי בארץ ולכן תגל העקרה מההולדה חדשה זו הנפלאה ביותר.\n<b>וזהו</b> שמסיים עוד אח\"כ בשמחה כלומר ע\"י מה ולמה נהיותה כן שגם שאין אתדל\"ת מלמטה אעפ\"כ מולדת אה\"ר הלא מהראוי אם איש מזריע תחילה להיות נקבה כו' ולזה אמר בשמחה כלומר כי אין [זה] אלא עפ\"י קו המדה אבל ע\"י השמחה מתמתקים כל הדינים כו'.\n<b>וגם</b> לפי' הב' יתכן דתשיש הוא פועל יוצא ופי' תשיש ותגל העקרה ובמה בקיבוץ בני' כו' וע\"י מה בשמחה ששמח הוא ית' כמ\"ש יאר ה' פניו אליך כו'.",[["1458","20","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["1459","21","<b>הארה</b>: כ\"ה בהכת\"י."]]],[2101920264,"<h3>משמח חתן וכלה</h3>\n<b>בעז\"ה על חתונה תקע\"ב</b>\n<b>משמח</b><sup data-n=\"1460\">1</sup> חתן וכלה, ובברכה אחרונה נאמר משמח חתן עם הכלה. הנה ביום<sup data-n=\"1461\">2</sup> חתונתו זו מ\"ת, וצריך להבין הלא גם בלא\"ה נק'<sup data-n=\"1462\">3</sup> הקב\"ה חתן מל'<sup data-n=\"1463\">4</sup> חות דרגא, ע\"ש השפעתו בעולמות כמ\"ש ואתה<sup data-n=\"1464\">5</sup> מחי' את כולם, וכנס\"י נק' כלה, שהיא בחי' מקבל. ועוד צ\"ל דכאן אומר שכנס\"י נק' כלה, ובמ\"א אומר בהיפך, והוא מארז\"ל<sup data-n=\"1465\">6</sup> ע\"פ תורה ציוה לנו משה מורשה, א\"ת מורשה אלא מאורסה שהתורה היא בחי' כלה לישראל וישראל נק' בשם חתן כו'.\n<b>והענין</b> הוא כי הנה התורה נק' בשם ברית כמ\"ש אלה<sup data-n=\"1466\">7</sup> דברי הברית אשר כרת משה, כי הנה כתיב עין<sup data-n=\"1467\">8</sup> לא ראתה אלקים זולתך יעשה למחכה לו פי' עין לא ראתה זה עדן, כי יש כמה מיני ג\"ע זה למעלה מזה עד אין קץ ותכלית, ובין ג\"ע התחתון לגעה\"ע יש נהר דינור המפסיק שצריך לטבול בו, כדי לשכוח מהות התענוג שבגעה\"ת, שמבלבל לגבי מעלת התענוג שבגעה\"ע שלמעלה מגעה\"ת, וכיוצא בזה יש עוד מדריגות רבות לאין קץ ותכלית בעולם התענוג כי התענוג הוא בבחי' א\"ס ממש, וכל תענוג עוה\"ז הוא רק מהפסולת שנפל בשבה\"כ, וזהו כל עסק הנשמות אחר התפשטותם מהגופים שהם הולכים מחיל אל חיל בעילוי אחר עילוי, ולא שעוסקים מענין לענין בלבד שהרי משה רבינו ע\"ה ידע להשיג כל התורה גם בחיים חיותו, ומה הוא עושה כל זה ימים ושנים רבות אלא בודאי שגם בכל ענין יש עליות רבות לאין קץ בעומק רום וכן אברהם אבינו, וכל נפשות הצדיקים וכמ\"ש וקדושים<sup data-n=\"1468\">9</sup> בכ\"י יהללוך סלה, פי' קדושים הם הנשמות שהם יהללוך סלה, וכל<sup data-n=\"1469\">10</sup> מקום שנא' סלה אין לו הפסק כו', אמנם בחי' תענוג",[["1460","1","<b>משמח חתן וכלה</b>: ראה עניני המאמר בארוכה בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תצט ואילך וע' תקיג ואילך."],["1461","2","<b>ביום חתונתו זו מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["1462","3","<b>נק' הקב\"ה חתן</b>: ראה לקו\"ת ברכה צד, א שמציין בענין זה: בכמה דוכתי משמע ג\"כ דפי' ביום חתונתו היינו שישראל הם הכלה וכדפרש\"י ע\"פ ה' מסיני בא כו' כחתן היוצא להקביל פני כלה והוא מהמכילתא פ' יתרו וכ\"מ ג\"כ ברבות נשא פי\"ב ביום חתונתו זה סיני חיתונין היו כו' וע' זח\"ב נ\"ח א' פ\"ד א' כ\"ב א' ח\"ג ס\"א ב' כו' גם ברבות ס\"פ ואתחנן איתא א\"ר ברכי' בעשר מקומות קרא הקב\"ה לישראל כלה. ע\"כ."],["1463","4","<b>מל' חות דרגא</b>: ראה יבמות סג, א."],["1464","5","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1465","6","<b>מארז\"ל ע\"פ תורה ציוה . . א\"ת מורשה</b>: ברכה לג, ב. ברכות נז, א. וראה בהנסמן בארוכה בלקו\"ת ברכה צג, סע\"ד ואילך בענין שלפעמים מצינו שישראל נק' חתן ותורה כלה ולפעמים מצינו להיפך שתורה נק' חתן וישראל כלה. ועיין עוד ע\"ד ב' אופנים אלו בס' מאמרי אדהאמ\"צ שמות ח\"א ע' א. ויקרא ח\"א ע' שלב. במדבר ח\"ב ע' שכז ואילך וע' עתר ואילך. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' רסז."],["1466","7","<b>אלה דברי הברית</b>: תבוא כח, סט."],["1467","8","<b>עין לא ראתה . . זה עדן</b>: ישעי' סד, ג. ברכות לד, ב."],["1468","9","<b>וקדושים בכ\"י יהללוך סלה</b>: נוסח ברכת אתה קדוש."],["1469","10","<b>וכל מקום שנא' סלה אין לו הפסק</b>: עירובין נה, א."]]],[2101920265,"דא\"ס הזה נתלבש במצות מעשיות דוקא, וכמאמ' אשר קדשנו במצותיו וציונו, פי' אשר הוא בחי' תענוג שהוא קדשנו במצותיו, כי כל מצוה יש בה תענוג, והתענוג הוא המתלבש בבחי' הרצון שבמצוה. וזהו עין לא ראתה אלקים זולתך זה עדן דהיינו בחי' תענוג העליון הנ\"ל, יעשה למחכה לו, ע\"ד מ\"ש באיוב<sup data-n=\"1470\">11</sup> ואליהו חיכה את איוב בדברים, וכדפי'<sup data-n=\"1471\">12</sup> בזהר מאן דדייק מילי דחכמתא, כי בחכ' שבתורה שהוא ההתחכמות באיכות הרצון שבמצות, מלובש אותו התענוג העליון הנ\"ל, שהתענוג מלובש ברצון, והרצון בחכ', נמצא שמחכה לו זה הלומד תורה בעיון שזהו פי' דייק מילי דאורייתא, דייק דוקא דהיינו השגת החכ' דוקא, הוא הגורם ג\"כ התגלות תענוג עליון הנ\"ל הנק' עדן, ולכן יעשה לו אלקים מה שעין לא ראתה, שיתגלה לו התענוג עליון הנק' עדן כי הגילוי הזה הוא שיהי' לע\"ל בתחה\"מ, כי ע\"י גילוי תענוג עליון זה דא\"ס אזי גם הגוף יכול לקום ולחיות.\n<b>וזהו</b> שבברכה אחרונה דמהרה ישמע דקאי על לע\"ל, אומרים משמח חתן עם הכלה, כי הנה ישראל נקראו בשם חתן להיות שהם ממשיכים התענוג עליון, ע\"י עיון התורה וכמו שמתענוג הגשמי, בזווג דו\"נ, נעשה הולדה מטפה המתהוה מזה, כך גם ע\"י המשכת תענוג עליון הנ\"ל נעשה הולדת נשמות כו', והתורה נק' כלה שהיא הכלי להמשכת וגילוי התענוג עליון בתוכה. וז\"ש בתולות<sup data-n=\"1472\">13</sup> אחרי' ריעותיה מובאות לרקמות, וכמארז\"ל ועלמות<sup data-n=\"1473\">14</sup> אלו הלכות כו', וגם הכלה<sup data-n=\"1474\">15</sup> אותיות הלכה ולכן נק' התורה ברית ע\"ש המשכת התענוג בתורה, וע\"ד מארז\"ל אין<sup data-n=\"1475\">16</sup> האשה כורתת ברית כו'. ובבחי' זו נא' משמח חתן עם הכלה, פי' שעם הכלה הוא משמח את החתן, כי הגם שישראל הם ממשיכים התענוג עליון הנ\"ל אבל מאחר שהמשכה הוא ע\"י העיון בתורה דוקא, א\"כ הרי החתן שהוא בחי' הישראל מקבל שמחה זו ותענוג זה, מהכלה דוקא שהיא התורה כנ\"ל. ואמנם יש עוד בחי' שנית בענין לימוד התורה, והוא כענין קורא בתורה, דהיינו שלא בעיון בדקדוק טעמי התורה, והשגת עמקות החכמה, אלא בקריאה בלבד, וכמ\"ש והגית<sup data-n=\"1476\">17</sup> בו יומם ולילה, והוא רק מצות דיבור האותיות, הנה גם עי\"ז ממשיכים גילוי אלקותו ית' שזהו פי' קורא בתורה כמו הקורא את המלך להיות פונה אליו כו', והיינו ע\"י הדיבור דוקא, כי מלכות<sup data-n=\"1477\">18</sup> פה תושבע\"פ קרינן לה",[["1470","11","<b>באיוב ואליהו חיכה את איוב בדברים</b>: איוב לב, ד. וראה רש\"י ומצודות שם שהוא לשון המתנה. וראה גם המשך תרס\"ח ע' עח. ובכ\"מ."],["1471","12","<b>וכדפי' בזהר מאן דדייק מילי דחכמתא</b>: זח\"א קל, ב."],["1472","13","<b>בתולות אחרי'</b>: תהלים מה, טו."],["1473","14","<b>ועלמות אלו הלכות</b>: ראה שהש\"ר עה\"פ ו, ח. במדב\"ר פי\"ח, כא. זח\"ג רטז, א."],["1474","15","<b>הכלה אותיות הלכה</b>: פע\"ח שער הנהגת הלימוד (שי\"ז) ד\"ה גם העוסק בתורה. וראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קיא. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' שטו. וש\"נ."],["1475","16","<b>אין האשה כורתת ברית</b>: סנהדרין כב, ב."],["1476","17","<b>והגית בו יומם ולילה</b>: יהושע א, ח."],["1477","18","<b>מלכות פה תושבע\"פ קרינן לה</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101920266,"שבאותיות הדיבור בקריאה, גם שלא בעיון הוא ממשיך כו'. ובבחי' זו נא' משמח חתן וכלה, שאין החתן מקבל מהכלה אלא אדרבה הוא משפיע בה, וזהו\"ע הוי\"ו דוהכלה, שוא\"ו הוא המשכה מחתן אל הכלה, והיינו כמ\"ש קרוב<sup data-n=\"1478\">19</sup> ה' לכל קוראיו אשר יקראוהו באמת, ואין אמת אלא תורה, שצריך להיות קורא וממשיך א\"ס ב\"ה בהתו' כו'.\n<b>וע\"ז</b> נא' שערך<sup data-n=\"1479\">20</sup> כעדר העיזים שגלשו מהר גלעד, פי' הר גלעד, הוא כענין שנא' עד<sup data-n=\"1480\">21</sup> הגל הזה אם אני לא אעבור אליך כו', כי לבן הוא בחי' לובן העליון, ויש גל והפסק בינו ליעקב יו\"ד<sup data-n=\"1481\">22</sup> עקב, ואינן יכולים להתחבר יחד, רק שערות בלבד הוא שנמשכים מבחי' לובן העליון. וכ\"ז הוא ע\"פ השתל' שבבחי' וסדר ההשתל' התמידיות א\"א להיות משם המשכה רק בבחי' שערות בלבד, והחכ'<sup data-n=\"1482\">23</sup> מאין תמצא, אבל ע\"י המשכה מלמעלה מהשתל' ע\"י לימוד התורה, אז כתיב שערך כעדר העיזים, פי' שנמרטו השערות ונגזזו עד שנשאר הר גלעד קרח עד\"מ, דהיינו שמתגלה בחי' לובן העליון כמו שהוא בעצם ולא בדרך שערות כו'.\n<b>וביאור</b> הענין הוא כי הנה לבן יש ב' פעמים, לבן א' הוא בחי' לובן העליון בחי' כתר שהוא למעלה מן יעקב שהוא בעל עולם האצי', ויש פרסא בינו ליעקב כו', כי יו\"ד עקב חכ' ראשית האצי' הוא בדילוג הערך מהכתר, ולא שנמשך ממנו בהשתל', רק בדרך הפסק פרסא. והב' הוא בחי' לבן שבבי\"ע שלמטה מאצי', שהוא למטה מטה מיעקב, ואינו מקבל ממנו ג\"כ כ\"א ע\"י הפסק שבין האצי' לבריאה. וזהו עד הגל הזה שעשו מאבנים שהם בחי' אותיות שנק' אבנים כמ\"ש בס\"י<sup data-n=\"1483\">24</sup> שתי אבנים בונות שני בתים, ומהשתנות הצירופים נעשה פרסא כנודע, אם אני לא אעבור אליך את הגל הזה, שלא יוכל בחי' לובן העליון להתגלות באצי', וגם אתה לא תעבור אלי, וכמו\"כ יעקב דאצי' לא יתגלה בבי\"ע כ\"א בבחי' שערות בלבד, הוא שנמשך מהכתר באצי' אבא יונק ממזלא כו' וכן מאצילות למטה בבי\"ע. ואמנם כ\"ז הוא רק עפ\"י קו המדה, שנמדד להיות כך וכך סדר הנהגות והשתל', אבל בבוא תוס' הארה חדשה מהמאציל ב\"ה שלמעלה מהצמצומי' דקו המדה, אזי כתיב שערך כעדר העיזים שגלשו מהר גלעד, וכמ\"ש בזהר<sup data-n=\"1484\">25</sup> דגליש למטרוניתא, שבגילוח השערות מתגלה עצמיות הגולגלתא אשר מקדם היתה מוסתרת ונעלמת תחת השערות שהן היו מסתירים אותה.",[["1478","19","<b>קרוב ה' לכל קוראיו . . ואין אמת אלא תורה</b>: תהלים קמה, יח. ראה ברכות ה, ב. ירושלמי ר\"ה פ\"ג ה\"ח. איכ\"ר פתיחתא ב. ת\"ז תכ\"א (נ, א)."],["1479","20","<b>שערך כעדר העיזים</b>: שה\"ש ד, א."],["1480","21","<b>עד הגל הזה</b>: ויצא לא, נב."],["1481","22","<b>יו\"ד עקב</b>: ראה ע\"ח שער סדר אצי' (ש\"ג) פ\"ב. וראה ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמז. וש\"נ."],["1482","23","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["1483","24","<b>בס\"י שתי אבנים בונות שני בתים</b>: ס' יצירה פ\"ד מי\"ב."],["1484","25","<b>בזהר דגליש למטרוניתא</b>: ראה זח\"א ריז, א."]]],[2101920267,"<b>וזה</b> ג\"כ ענין מ\"ש ועמדו<sup data-n=\"1485\">26</sup> רגליו ביום ההוא על הר הזתים כו', ונבקע ההר מחציו קדמה כי שמן זית הוא בחי' חכמה, והר הזתים שהוא המקום שממנו גדלים וצומחים הזתים היינו בחי' כתר שהוא מקור החכ' ושרשה, ועכשיו יש בחי' פרסא בינו לבין החכ', והחכ' מקבלת ממנו בדרך שערות בלבד, וכעין צמיחת זתים מן ההר שהוא רק בחי' צומח, והוא ג\"כ בחי' שערות כו', והפרסא עצמה הוא הנק' הר הגלעד נוטריקון עד הגל, וכ\"ז הוא עפ\"י קו המדה, אמנם לעתיד לבוא בהגלות נגלות עצמותו ית', אזי כתיב ונבקע הר הזתים מחציו שלא יהי' עוד פרסא מפסקת אלא<sup data-n=\"1486\">27</sup> בין כתר לאצי', ובין אצי' לבריאה, אלא שאור הכתר שהוא בחי' סוכ\"ע יתגלה גם למטה באצי' ובבריאה כו', וכמארז\"ל עתידים<sup data-n=\"1487\">28</sup> צדיקים שיאמרו לפניהם קדוש וד\"ל.",[["1485","26","<b>ועמדו רגליו</b>: זכרי' יד, ד ואילך."],["1486","27","<b>אלא</b>: כ\"ה בהכת\"י, ואולי הוא מיותר."],["1487","28","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עה, ב."]]],[2101920268,"<h3>שמח תשמח</h3>\n<b>שמח</b><sup data-n=\"1488\">1</sup> תשמח ריעים האהובים, הנה הקב\"ה וכנס\"י נקראים חתן וכלה כך הם ג\"כ בחי' סובב וממלא, כי כנס\"י הוא בחי' שכינת עוזו המתלבש בעולמות בבחי' פנימיות להחיותם, והקב\"ה הוא סוכ\"ע שלמעלה מעלה מהתלבשות והתפשטות בתוכיות העולמות, אלא שמאיר עליהם בבחי' מקיף. והנה בחי' סוכ\"ע נק' חתן שהוא בחי' משפיע כי הוא מקור הכל, ובחי' ממכ\"ע נק' כלה שהוא בחי' מקבל החיות מהסובב שהוא מקור החיים, והן הנק' ריעים האהובים. כי בחי' ממכ\"ע הנק' כלה חפצה ותשוקתה בתמידות לקבל ההשפעה מאור הסובב (וכמ\"ש למען<sup data-n=\"1489\">2</sup> יזמרך כבוד נהורא תתאה קרי תדיר לנהורא עילאה וכתיב ואל<sup data-n=\"1490\">3</sup> אישך תשוקתך כנ\"ל), ולפי שיותר<sup data-n=\"1491\">4</sup> ממה שהעגל רוצה לינק פרה רוצה להניק, א\"כ גם קוב\"ה שהוא בחי' סוכ\"ע חפץ בהשפעה זאת להאיר ולהשפיע בבחי' ממכ\"ע, והרי הם אהובים זל\"ז. וכמו\"כ הוא גם בנשמות ישראל כפי<sup data-n=\"1492\">*4</sup> הפרטים שבגופים שכאו\"א יש לו אהבה ותשוקה אליו ית' כמו שנצטווינו להיות ואהבת<sup data-n=\"1493\">5</sup> את ה' בכל לבבך ממש, ובכל נפשך כו', וכמים<sup data-n=\"1494\">6</sup> הפנים לפנים נתעורר למעלה ג\"כ בחי' אהבה",[["1488","1","<b>שמח תשמח</b>: ראה עניני המאמר בארוכה בס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' שפז ואילך וע' תפו ואילך. ונת' עניני המאמר בד\"ה שמח תשמח בסה\"מ תרנ\"ז ע' קעג ואילך."],["1489","2","<b>למען יזמרך כבוד נהורא תתאה קרי תדיר</b>: תהלים ל, יג. ראה זח\"ב קמ, א. זח\"א קעח, ב. עז, ב. פו, ב."],["1490","3","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1491","4","<b>שיותר ממה שהעגל רוצה לינק</b>: פסחים קיב, א."],["1492","*4","<b>כפי הפרטים שבגופים</b>: כ\"ה בהכתב-יד."],["1493","5","<b>ואהבת את ה'</b>: ואתחנן ד, ה."],["1494","6","<b>וכמים הפנים לפנים</b>: משלי כז, יט."]]],[2101920269,"לישראל, וכמ\"ש אהבתי<sup data-n=\"1495\">7</sup> אתכם אמר ה', וכן הבוחר בעמו ישראל באהבה, ואדרבה אהבתו ית' אלינו נפלאה יותר על אהבתינו, שהרי ארז\"ל כפה<sup data-n=\"1496\">8</sup> עליהם הר כגיגית, דהיינו שמעוצם אהבתו ית' אלינו גם הוא פועל ישועות בקרב לבנו שיהי' בנו בחי' אהבה אליו ית', שלא נהי' נפרדים ממנו ית' וכמ\"ש וימינו<sup data-n=\"1497\">9</sup> תחבקני, כמו המחבק את חבירו בידים ומחזירו כלפי פניו, ואינו מניחו להפרד ממנו שאהבת המחבק להנחבק גדולה יותר מאהבת הנחבק, שכדי שלא יתפרד הנחבק ויוכל לשכוח על אהבתו הוא מחבקו ואינו מניחו להפרד כו'.\n<b>אך</b> באמת הנה ידוע דגם בחי' סוכ\"ע וממכ\"ע אין ערוך לגבי מהותו ועצמותו ית', וכמאמר מלך משובח ומפואר עדי עד שמו הגדול בעולמות לאין קץ ותכלית גבוה מעל מגבוה הוא רק מבחי' שמו הגדול בלבד, כמשל השם שאינו נוגע להעצם כו', וכן הוא אומר יחיד חי העולמים מלך, פי' שהוא בעצמותו יחיד ומיוחד, ואני<sup data-n=\"1498\">10</sup> הוי' לא שניתי ממש, וחי העולמים כולם מרכ\"ד עד סוכ\"ד הוא רק מבחי' מלך לבד, מה שנק'<sup data-n=\"1499\">11</sup> שמו מלך עליהם, ובחי' מלוכה זו הוא בחי' סובב ובחי' ממלא, ואמת כי גם מדת מלוכה לא יתכן לכנות להארה זו המתפשטת ממנו ית' בבחי' סוכ\"ע וממכ\"ע, כי מדת מלוכה היא תופסת דבר מה גם בעצמות המלך, שהרי העבדים הם נפרדים ממנו, וגם משל כטפה מהים אינו ערוך לזה שלשכך את האוזן דברו חכמים בהוה, ובאמת לית<sup data-n=\"1500\">12</sup> מחשבה תפיסא בי', ולא מחשבת האדם בלבד, אלא שגם רבות המחשבות גבוה מעל גבוה כולם אינם תופסים במהותו ועצמותו ית', כי במחשבה אחת הוא פוקד כל יצורי קדם, וסובב וממלא כל העולמות. אך מ\"מ להיות המשכות והטיית מחשבה א' זו ממהותו ית' הוא ע\"י האתעדל\"ת של הישראל בק\"ש בקיום בכל לבבך ובכל נפשך כו', כי נעוץ<sup data-n=\"1501\">13</sup> תחב\"ס דוקא וסופן בתחלתן כו', ולכן כח המעשה שבישראל בגשמיות גדולה יותר לעורר למעלה מעלה הטיית עצמותו ית' להיות סובב וממלא כו'. אמנם פעמים שאין אתערותא מלמטה כשלא אכשור דרא, ואזי משורת הדין לא היו ראויים שיהי' אתערותא מלמעלה ג\"כ, אלא שאעפי\"כ יוכל להיות שיהי' אתערותא מלמעלה מאליו מעצמו, ושתהי' גם ביתר שאת ויתר עוז מאתעדל\"ע שע\"י אתעדל\"ת, והוא מ\"ש שמח תשמח ריעים האהובים שהשמחה פורץ גדר עד\"מ המלך בתמידות הוא יושב שאנן ושקט בהיכלו, ואין הכל זוכים לראות פניו, כ\"א החשובים שבעם זוכים לזה בהשתדלות רב, אמנם לפעמים בעת שמחת לבו יצא החוצה ויגלה לעין כל, כי מחמת השמחה יוכל לפרוץ גדר כנהוג ע\"פ התמידות, והיינו משום כי השמחה הוא המשכת חיות חדש מההעלם אל הגילוי כידוע.",[["1495","7","<b>אהבתי אתכם אמר ה'</b>: מלאכי א, ב."],["1496","8","<b>כפה עליהם הר כגיגית</b>: שבת פח, א. וראה תו\"א מג\"א צח, ד."],["1497","9","<b>וימינו תחבקני</b>: שה\"ש ב, ו."],["1498","10","<b>ואני הוי' לא שניתי</b>: מלאכי ג, ו."],["1499","11","<b>שנק' שמו מלך עליהם</b>: ע\"פ פיוט אדון עולם."],["1500","12","<b>לית מחשבה תפיסא בי'</b>: ת\"ז ד\"ה פתח אליהו (יז, א)."],["1501","13","<b>נעוץ תחב\"ס</b>: ס' יצירה פ\"א מ\"ז."]]],[2101920270,"<b>וכך</b> אנו מבקשים שמח תשמח ריעים האהובים שהם בחי' סובב וממלא, להיות מתחברים תמיד יחד הגם שאין אתערותא מלמטה, ולא אכשור דרי אבל עכ\"ז ע\"י השמחה יוכל לדלג שלא כסדר ההנהגה התמידית. וז\"ש עוד כשמחך יצירך בג\"ע מקדם, כלומר שמוסיף לחזק הדברים איך שע\"י השמחה יוכל לפרוץ הגדר שיהי' המשכת אלקותו ית' מלמעלה, הגם שאין אתעדל\"ת, ואומר הלא מצינו שכבר הי' לעולמים, והוא כשמחך יצירך בג\"ע, דהיינו אדה\"ר שהי' יציר כפיו של הקב\"ה ששמחו הקב\"ה בג\"ע בהופיע עליו רוח קדשו שנא' וייצר<sup data-n=\"1502\">14</sup> ה' אלקים את האדם כו', ולקח צלע מצלעותיו, ועשה לו אשה ויביאה<sup data-n=\"1503\">15</sup> אל האדם והי' הוא ית' שושבין אצל אדם, וגם עשה להם חופה, שהוא המשכת אור המקיף, וכ\"ז הי' מאליו וממילא ומעצמו שלא ע\"י אתעדל\"ת, שהרי לא הי' עדיין מה שיעורר, וכמ\"ש ואדם<sup data-n=\"1504\">16</sup> אין לעבוד את האדמה, אלא שלאחר בריאת האדם כתיב ויניחהו<sup data-n=\"1505\">17</sup> בג\"ע לעבדה אלו רמ\"ח מ\"ע שיהי' באתעדל\"ת דוקא אתעדל\"ע. אמנם כשאין אתעדל\"ת מלמטה, אנו מבקשים שיזכור ימות עולם, כמו ששמש יציר כפיו בג\"ע באתעדל\"ע שלא ע\"י אתעדל\"ת, והיינו מקדם מקדמונו ש\"ע ששם אין אתעדל\"ת מגעת כלל, כדכתיב אם<sup data-n=\"1506\">18</sup> צדקת מה תתן לו, שע\"י גילוי הארה משם, והוא ענין השמחה, שהוא המשכת רוח חיים מחדש מפנימי' החיות דהיינו מקדם להשכל אזי יוכל להיות פריצת גדר הנהוג בתמידות. וכך גם עתה ישמח ריעים האהובים שהם סובב וממלא, ושיהי' מתחברים יחד, הגם שלא נמצא מלמטה אתעדל\"ת כ\"א ע\"י השמחה וד\"ל. והנה בגילוי הארה זו שלמעלה ע\"י השמחה, אזי נמשך למטה ג\"כ בתוס' רב ביתר שאת ויתר עוז מן ההארה הנמשכת ע\"י אתעדל\"ת, שהוא מבחי' השתל', ונמשכת ע\"י צמצומים והעלמו' רבים כסדר המדריגות, ולהיות שעולם השפל שלנו היותו אחרון בהשתל', אין מגיע לו רק מעט מזעיר, וגם הלא אתעדל\"ת שלנו הוא בחי' גשמיות לבד לגבי אוא\"ס ב\"ה, ומה שראוי להיות עפי\"ז אתעדל\"ע היא הארה מצומצמת בלבד, וגם היא נמשכת ע\"י צמצומים והעלמים ולבושים רבים כראוי ע\"פ השכל לפי ריחוק עולם השפל שלנו מאור פני מלך חיים וד\"ל.",[["1502","14","<b>וייצר ה' אלקים את האדם</b>: בראשית ב, ז."],["1503","15","<b>ויביאה אל האדם</b>: שם, כב."],["1504","16","<b>ואדם אין לעבוד את האדמה</b>: בראשית ב, ה."],["1505","17","<b>ויניחהו בג\"ע לעבדה אלו רמ\"ח מ\"ע</b>: בראשית ב, טו. ראה זח\"א כז, א. זח\"ב קסה, ב. וראה ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' כב."],["1506","18","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."]]],[2101920271,"<h3>יביאו לבוש מלכות</h3>\n<b>יביאו</b><sup data-n=\"1507\">1</sup> לבוש<sup data-n=\"1508\">2</sup> מלכות אשר לבש בו המלך וסוס אשר רכב עליו המלך ואשר נתן כתר מלכות בראשו, הנה לבוש מלכות הוא ענין מ\"ש ה'<sup data-n=\"1509\">3</sup> מלך גאות לבש, וכתר מלכות הוא ענין מ\"ש בעטרה<sup data-n=\"1510\">4</sup> שעטרה לו אמו ביום חתונתו זה מ\"ת שבחי' עטרה זו של המלך שלמה נק' כתר מל', וסוס אשר רכב עליו המלך במ\"ת הוא כמ\"ש בהפטרה דשבועות זמן מ\"ת כי<sup data-n=\"1511\">5</sup> תרכב על סוסיך מרכבותיך ישועה.\n<b>והנה</b> שייכות כל ג' בחי' אלה בפורים הוא משום שבפורים נאמ' וקבל<sup data-n=\"1512\">6</sup> היהודים את אשר החלו לעשות וארז\"ל אשר החלו לעשות במ\"ת שהקדימו נעשה לנשמע הדר קבלוהו בימי אחשורוש ולכן כמו שבמ\"ת הי' ג' בחי' אלה לבוש מל' ע\"י שהקדימו נעשה לנשמע וכתר מל' היא העטרה שעטרה לו כנ\"י אשר לא<sup data-n=\"1513\">7</sup> זז מחבבה עד שקראה אמו כו' וסוס אשר רכב עליו הוא ענין המרכבה<sup data-n=\"1514\">8</sup> מסוסי אש אשר רכב עליהם ונגלה מלכו של עולם כנ\"ל בפסוק כי תרכב על סוסיך כו' כך גם בפורים בשעה שהדר קבלוהו להארה זו שהחלו לעשות במ\"ת הי' ג\"כ כל ג' בחי' אלה.\n<b>וביאור</b> הענין הנה ענין לבוש מלכות וגאות לבש, יובן בהקדים ענין סובב וממלא כי הנה בחי' השתלשלות העולמות שהוא מחכמה ואילך שמחכמ' נמשך בחי' בינה ומבינה במדות כו' הוא בבחי' עילה ועלול שהחכמה מתלבשת בבינה וכן הבינה במדות עד\"מ בנפש שהשכל מתפשט ומתלבש במדות והמדות מתפשטים ומתלבשי' במחשבה וממחשבה לדיבור כו' וכך למעלה מבחי' חכים<sup data-n=\"1515\">9</sup> ולא בחכמ' ידיעא נמשך ומתלבש להיות מבין ולא בבינה ידיעא וכן מחב\"ד במדות אברהם<sup data-n=\"1516\">10</sup> איש החסד הוא אבר<sup data-n=\"1517\">11</sup> מה כי החסד הוא ענף החכמה שהשכל גוזר אומ' שראוי להתחסד ולהטיב לכל עד שגם על ישמעאל בקש אברהם רחמים לו<sup data-n=\"1518\">12</sup> יחיה כו' ויצחק הוא בחי' דין והיינו ג\"כ מחמת התלבשות החכמה בבחי' דיני' וגבורות שכך יאות לפי שכלו עד שגם את יעקב לא רצה לברך כו' וממדות נמשך להיו' התפשטות הארה בדיבור לומר יהי<sup data-n=\"1519\">13</sup> אור יהי",[["1507","1","<b>יביאו לבוש מלכות</b>: נדפס כאן מגוכי\"ק הצ\"צ. והוא נו\"א מד\"ה זה בתו\"א דרושי מג\"א צ, א. ונו\"א נדפס בס' מאמרי אדה\"ז הנחות הר\"פ ע' קכה וע' קכ [שם קטעים מתוך המאמר, ומתחיל: כל הנביאים עתידים ליבטל, המצווה מניח תפילין]. ונמצא ג\"כ המאמר באריכות בס' שערי אורה לאדהאמ\"צ נד, א ואילך. וראה בהנסמן עוד לקמן על הביאורים, ולהלן בסוף הס' ברשימת הכתבי-יד."],["1508","2","<b>יביאו לבוש . . בראשו</b>: אסתר ו, ח."],["1509","3","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["1510","4","<b>בעטרה שעטרה לו אמו ביום חתונתו זה מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["1511","5","<b>כי תרכב על סוסיך</b>: חבקוק ג, ח."],["1512","6","<b>וקבל היהודים . . אשר החלו לעשות במ\"ת</b>: אסתר ט, כג. שבת פח, א."],["1513","7","<b>לא זז מחבבה עד שקראה אמו</b>: ראה שהש\"ר ספ\"ג. פסיקתא דר\"כ פ\"א. ובכ\"מ."],["1514","8","<b>המרכבה מסוסי אש</b>: ראה זכרי' ו, א ואילך. לקו\"ת שה\"ש יב, ג."],["1515","9","<b>חכים ולא בחכ' ידיעא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["1516","10","<b>אברהם איש החסד</b>: ראה זח\"א מז, ב."],["1517","11","<b>אבר מה</b>: ראה זח\"א ד, א."],["1518","12","<b>לו יחיה</b>: לך לך יז, יח."],["1519","13","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."]]],[2101920272,"רקיע כו', וכ\"ז נק' בשם ממכ\"ע לפי שההארה מתפשטת ומתלבשת בתוכיות ובפנימיות העלמין ממש, אמנם כ\"ז הוא רק בהשתלשלות והמשכת החיות רוחני של כל הנבראים אשר מריש כל דרגין עד סוף כל דרגין, שהמשכת חיות זו המתלבשת בפנימיותם הוא בכל א' משלמעלה הימנו ונמשך בדרך עילה ועלול כלומ' שהעלול נלקח מעצמיו' העילה ואותו העילה הוא מקור העלול והיינו לפי ששניהם מסוג א' כי המה חיות רוחניי', אבל להיות התהוות החומר של הנבראים ואפי' בעולמות הרוחניים להיות התהוו' בחי' כלים לאורות דהיינו כמו למטה התהוות גוף לנשמה זה א\"א להיות מהארה זו דממלא שבהשתלשלו' כי אדרב' הרי מטבע העלול להדבק ולהכלל בעילתו ולהיות בטל אליו, ובאמת בחי' האורו' והנשמות של הנבראי' המתהוים בבחי' עו\"ע כל א' משלמעלה הימנו אזי חפצם ותשוקתם מצד עצמם להכלל במקורם אלא שהכלי והחומר שלהם מונע ומעכב אותם, וא\"כ איפה איך יכול להיות התהוות הכלי ג\"כ בבחי' השתלשלו' עו\"ע משלמעלה הימנה, כי הלא אז מהראוי הי' להיות בה ג\"כ בחי' הביטול, וכמו שאנו רואי' בגשמיו' שהמדות לפי שנמשכים מהשכל והשכל הוא שרשם לכן כל זמן שהשכל מאיר במוחי' בשלימותו בהתבוננו בטיבות איזו דבר אף כי יש אז מציא' האהבה לאותו דבר אחר שמאותו השכל וההתבוננות נמשכת האהבה ונולדה אח\"כ א\"כ פשיטא שגם בשכל המצא תמצא מציא' האהב' ואדרבה בודאי היא שם ביתר שאת וביתר עז, אבל מ\"מ אינה נראי' ליש ודבר כלל והיינו מצד ביטולה בשכל מקור שרשה כי כך הוא טבע העלול להיות מתכלל בעילתו, ולכך הי' משה כבד<sup data-n=\"1520\">14</sup> פה וכבד לשון כי מרוב התגברות החכמה לא הי' יכול להיות המשכת הדיבור, כי הי' בטל בהחכמה מקור שרשו, וכמ\"כ לא הי' יכול להיות התהוות הכלי' עד שהם עתה בחי' יש ודבר בפ\"ע כמו שהיא אילו היו נמשכים בהשתלשלו' עו\"ע, אלא לפי שנמשכי' מבחי' סוכ\"ע הכל יכול וכמשי\"ת.\n<b>וביותר</b> יובן זה מהתהוות העולם הגשמי הזה ואשר בו, כי הגם שבדבר ה' נעשו שמים וארץ באמרו יהי אור ויהי רקיע כו' והדיבור הוא מבחי' ממכ\"ע, אבל באמת לא מאותיו' הדבור בלבד נתהוו כי א\"כ הי' הכל רוחניי' שמאותיות יהי אור הי' מתהווה בחי' אור רוחני עד\"מ כמו שהוא מציא' האור הרוחני למעלה המלובש באותיו' יהי אור וכעד\"ז בחי' הרקיע כו' אבל לא הי' אור ורקיע גשמיים, כי הרי כל משכיל על דבר יוכל להבין זאת וכמעט נרא' בעליל שבשום אופן אי אפשר להיות התהוות דבר גשמי מן רוחני כי הרי לא נערוך כלל גשמי' לרוחניות ואינו מערכו וסוגו כלל שיתכן לומר שיוליד זא\"ז כמו שהוא בבחי' עו\"ע כו', עם היות כי נודע דיש ד' חיות במרכבה למעלה והן ארי' שור נשר אדם, מפני אריה נמשכי' כל החיות שבעולם ומפני שור כל הבהמות ומפני נשר כל העופות, היינו הרוחניות שלהם שנפש החי' ונפש הבהמה כו' הן שנמשכות מפני ארי' פני שור רוחניי' שבמרכבה כי גם נפש הבהמה והחי' רוחני' המה אלא שפני ארי' ופני שור",[["1520","14","<b>כבד פה וכבד לשון</b>: שמות ד, י."]]],[2101920273,"שלמעלה הן בחי' מרכבה משא\"כ בנפשות הבהמו' וחיו' גשמיים וע\"ז יתכן ענין השתלשלו' עו\"ע, אבל להיו' התהוות גופות החיות והבהמות וכן גופי' של בנ\"א וצומח ודומם וכיוצא באלו שהם גשמיים ממש זה א\"א להיות כלל ע\"י השתלשלו', כי מרוחני' א\"א להיו' בשום פנים התהוות הגשמיו', אלא שנמשכים דוקא מבחי' סוכ\"ע שהוא הכל יכול ומהוה אותם מאין ממש, פי' מאין המוחלט שלא כמדת ההשתלשלו' עו\"ע שהעלול יש לו מקור שמשם נתהוה מאחר שנלקח מעצמיו' העילה ואין זה מאין, משא\"כ התהוות הגשמיו' שאינו ממהו' הרוחני' אלא רק מחמת סכ\"ע הכל יכול ה\"ז<sup data-n=\"1521\">15</sup> מאין ממש.",[["1521","15","<b>ה\"ז מאין ממש</b>: ע\"כ נרשם בגוכי\"ק, וראה המשך הענין במקומות שנסמנו בתחילת המאמר."]]],[2101920274,"<h3>ביאור על התורה הנ\"ל - איתא במ\"ח</h3>\n<b>ביאור על התורה הנ\"ל</b>\n<b>איתא</b><sup data-n=\"1522\">1</sup> במ\"ח<sup data-n=\"1523\">2</sup> בענין מקיפים ופנימים שהמקיפים הם כגלידי בצלים העליון מכולם הוא המשובח מכולם ובפנימיות הוא בהיפך שהם בבחי' התלבשות זת\"ז פנימי מכולם הוא המשובח מכולם. והנה גלגלתא שהוא חיצונית הכתר הוא מקור מקיפים ומו\"ס מקור הפנימי, והן הן בחי' תורה ומצות, כי המצות שהם רצון העליון נמשכים מגלגלתא, והתורה שהוא ענין ביאור המצות וטעמיהם הוא מו\"ס שהוא פנימיות הכתר פי' הטעם של הרצון ולכן הוא במו\"ס בתוך הגלגלתא שהוא בחי' הרצון עצמו שהוא חיצוניות הכתר כו'. ולפי זה מובן מה שמצינו מארז\"ל הנראים לכאורה כסותרים זא\"ז, פעמים<sup data-n=\"1524\">3</sup> משמע שת\"ת עדיף ממצות מעשיות ופעמים<sup data-n=\"1525\">4</sup> משמע בהיפך וכנז' בתורה, כי באמת שניהם אמת כי לא ראי זה כו', ויש מעלה בתורה שנמשכת ממו\"ס שאינה במצות כי מו\"ס הוא פנימי' הכתר ובזה הוא מעולה יותר מגולגלתא שהוא רק חיצונית הכתר כי החכמה יש בה טוב טעם לטועמי' משא\"כ הרצון אין בו טעם וריח כו', אמנם יש גם מעלה יתירה במצות שנמשכים מגולגלתא מה שאינו בתורה הנמשכת ממו\"ס והוא כי אדרבה",[["1522","1","<b>איתא במ\"ח</b>: ביאור זה נדפס כאן מכת\"י מעתיק (מס' 2319). ונמצא בשינויים בתו\"א דרושי פורים צא, ב. ובקיצור בס' מאמרי אדה\"ז הנחות הר\"פ ע' קמד, בכותרת: ביאור תורה דפורים תקע\"ב. וראה ג\"כ באריכות הביאור בד\"ה יביאו לבוש מלכות בס' שערי אורה לאדהאמ\"צ פ\"ל ואילך (סד, א ואילך). וביאורים וקיצורים כו' באוה\"ת מג\"א (הוצאת תש\"נ) ע' פב ואילך. צד ואילך. צו ואילך."],["1523","2","<b>במ\"ח בענין מקיפים ופנימים שהמקיפים הם כגלידי בצלים</b>: באוה\"ת מג\"א שם (ע' צו) מציין ע\"ז: במסכת כללות עולמות פ\"ג אות ג נמצא שסדר כו' ואות ח לפיכך כו' ובמסכת כללות האצילות ספ\"ג אבל כו'."],["1524","3","<b>פעמים משמע שת\"ת עדיף ממצות</b>: פאה פ\"א מ\"א. ירושלמי פאה שם. קידושין מ, ב. ובכ\"מ."],["1525","4","<b>ופעמים משמע בהיפך</b>: ראה אבות פ\"א מי\"ז. ירושלמי ברכות פ\"א ה\"ב. ובכ\"מ."]]],[2101920275,"היא הנותנת שלפי שגולגלתא הוא בחי' חיצוניות שרשה גבוה מאוד נעלה יותר ממנו<sup data-n=\"1526\">5</sup> ולכן מוחא הוא בחי' פנימיות, והענין כי בחי' החיצוניות יכול לירד ולהתגלות למטה יותר מהפנימי' כי פנימי שממקום גבוה ביותר א\"א לו להתגלות למטה ולכן מו\"ס שהתגלותן הוא בבחי' פנימי' היינו לפני שאינו גבוה כ\"כ אבל בחי' גולגלתא שהוא חיצונית היינו לפי ששרשה ממקום גבוה מאד נעלה שא\"א לו להתגלות כ\"א בבחי' חיצונית, והרי דגם שהיא היותר חיצוני אבל הוא ממקום עליון יותר.\n<b>וביאור</b> הדבר הוא כי הנה א\"ס ב\"ה כשמו כן הוא שאין<sup data-n=\"1527\">6</sup> לו תחלה ואין לו תכלה כו', ולכן א\"א לו להתגלות בבחי' מו\"ס שענינה הוא הגילוי שבפנימיות שהרי תכלית חכמה להשיגה, כי לית<sup data-n=\"1528\">7</sup> מחשבה תפיסא בי' כלל אפילו מחשבה עליונה סתימאה שהוא מו\"ס ואינה תפיסא אלא בהארה א' בלבד משא\"כ בחי' גלגלתא שהוא חיצוניות הנה שם דוקא יכול להיות השראת א\"ס ב\"ה, כי אף שהוא בלתי מוגבל ואינו יכול להתגלות לנמצאים מאתו היינו בבחי' גילוי בפנימיות שיהי' מחשבה הנאצלי' תפיסא בי' משום שהנאצל הוא בע\"ג לגבי א\"ס ב\"ה כנ\"ל, אבל בבחי' חיצונית יכול הוא להתגלות. ויובן ג\"כ עד\"מ למטה שאבוקה גדולה תאיר גם במקום רחוק פרסא וכיוצא משא\"כ אבוקה קטנה אינה מאירה אלא במקומה, ונמצא שההארה שממקום רחוק מאבוקה גדולה אף שבעצמותה אינו מאיר כמו ההארה שבקירוב מאבוקה הקטנה אבל מ\"מ בזאת מעלתה שבאה ממקום כח אבוקה גדולה שאבוקה גדולה הוא דווקא אשר תוכל להאיר למרחוק משא\"כ אבוקה קטנה, וכך בחי' ח\"ס להיותה קטנה בערך כי הלא החכמה מצער לגבי א\"ס ב\"ה שלמעלה מהחכמה ולכן לא תוכל לירד ולהתגלות למטה כ\"א שם נמצאת ושם היא כמוסה במקומה ועלי' נאמר עין<sup data-n=\"1529\">8</sup> לא ראתה אלוקים זולתך כו' כי שם מתוק האור לעינים ויש בה טוב טעם לטועמי', אבל בחי' גלגלתא אף כי בעצמותה הוא בחי' חיצוניות ואין בה טעם כ\"כ כנ\"ל אבל שרשה נעלה יותר בעצמות א\"ס ב\"ה הסוכ\"ע שלהיות רב הכמות ואין לו תחלה כו', לכן יכול לירד ולהשפיל א\"ע גם מטה מטה אשר לא יוכל להגיע שמה הארת האורות שבבחי' השתלשלות דהיינו מחכמה ואילך, והיינו שנמשך בחי' גלגלתא שהוא סוד הרצון שנמשך כמו שהוא ומתלבש גם בעשי' הגשמי שבמעשה המצות שהן הן רצונותיו ית' כידוע אלא שגילוי זה הוא בבחי' חיצוניות דוקא וכנ\"ל במשל.\n<b>וכן</b> יובן גם ממשל חקיקת האותיות באבן טוב בהיר שעם היותם נמצאים שמה אינם ניכרים מראות העין מסיבת תוקף בהירות האבן טוב שאין עין יכולה",[["1526","5","<b>ממנו</b>: כ\"ה בהכת\"י. ואוצ\"ל: ממוח."],["1527","6","<b>שאין לו תחלה ואין לו תכלה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."],["1528","7","<b>לית מחשבה תפיסא בי' כלל</b>: ת\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["1529","8","<b>עין לא ראתה</b>: ישעי' סד, ג. ברכות לד, ב."]]],[2101920276,"לשלוט בו כ\"א בשומו חותם על שעוה שמה יוכרו האותיות, כי כל דבר הגבוה בעצמותו יותר אין הארתו ניכרת אלא למרחוק דוקא. וכן יובן ממ\"ש בשלמה וידבר<sup data-n=\"1530\">9</sup> שלשת אלפים משל, שלכאורה הוא פלא שהלא המשלים המה מדברים זרים גשמיי' כמו לשמרך<sup data-n=\"1531\">10</sup> מאשה זרה כו' וכי זהו מעלת תהלת חכמתו אשר נאמר בו ויחכם<sup data-n=\"1532\">11</sup> מכל האדם, אבל הענין הוא כי כן הוא דוקא כי להמשיל משל לשכל שהוא מדבר זר ורחוק בערך מאד בזה צריך לחכמה עמוקה ונפלא ביותר שתוכל להתפשט כ\"כ למטה בעומק תחת וגם באמת שהוא חכם גדול צריך להמשיל משלים בכדי שיוכלו זולתו לעמוד על עומק כוונת שכלו שזולת המשלים לא היו יכולים לתפסו ולהשיגו לרוב עמקותם עמוק<sup data-n=\"1533\">12</sup> עמוק מי ימצאנו, כ\"א ע\"י משלים דוקא שהם דוגמת מדברים הקרובים אל השכל, וכל שיהי' חכמתו עמוקה ביותר יצטרך יותר להמציא משלים רבים ושיהי' זה משל לזה וזה משל לזה עד שבאמצעות כל המשלים יהי' יכולים ליקח ולתפוס את השכל, וז\"ש בשלמה וידבר שלשת אלפים משל לעמקי סודות התורה שהי' מגלה, וכן בר\"מ נאמר דהווה<sup data-n=\"1534\">13</sup> אמר ג' מאה משלים כנ\"ל.\n<b>וכך</b> הוא הנמשל למעלה בענין ההפרש שבין מו\"ס לגולגלתא, כי בחי' מו\"ס כמו שהוא למעלה הוא בחי' או\"פ פי' שענינו שמאיר במקומו כמו שהוא שלא ע\"י התלבשות והעלמות, והיינו משום כי הלא מצער הוא ואינו מצטרך ללבושים המלבישים ומעלימים כדי שיוכל לסבול, אמנם כ\"ז הוא במקומו למעלה אבל למטה אינו מאיר כלל כי הוא סתימא כי לא יכול להשפיל ולירד כ\"כ למטה, והיינו כנ\"ל במשל החכם הקטן שאינו מצטרך להמשיל משלים לדבריו למי שהוא חכם ומבין מדעתו אמנם לתלמידים קטני השכל לא יכול לכלכל דבריו ולהבינם כ\"כ, או כמשל האבוקה הקטנה שבמקומה היא מאירה בטוב ויפה אבל למרחוק אין אורה יכול להגיע לגמרי, משא\"כ בחי' גלגלתא שהוא בחי' לבוש פי' שגם במקומה למעלה הוא בחי' חיצוניות, וכנראה בעליל גם בגשמיות באדם שהמוח שמחפה<sup data-n=\"1535\">*13</sup> לגלגלתא הוא משובח ומעולה בעצם הרבה והחיות תלוי בו עד שניקב<sup data-n=\"1536\">14</sup> המוח במשהו טריפה משא\"כ הגלגלתא שהוא גרוע הרבה מן המוחין אין האור הפנימי הגופני' תלוי' בה כ\"כ ואינו פוסל עד רובה וכו', והיינו משום כי שרשה ממקום גבוה מאוד נעלה שלא יוכל לגלות אורו כמו שהוא במקומו כ\"א ע\"י התלבשות בלבוש חיצוני דוקא, והיינו כי שרשה מא\"ס ב\"ה הסוכ\"ע דלית מחשבה תפיסא בי' כלל כמו שהוא ית' דאין לו תחלה כו' אלא התגלותו הוא בבחי' חיצוני' דוקא והוא בחי' רצון העליון שמהות הרצון הוא בחי' חיצוני' והוא הכלי להשראת א\"ס ב\"ה ששורה ברצון העליון הנק' רעוא דכל רעוין כו' וגם היא הנותנת כו' להיותו אין סוף שאין לו תחלה כו' לכן הוא שיכול להתלבש בבחי' חיצוני' ולירד למטה ג\"כ כנ\"ל שהרצון העליון",[["1530","9","<b>וידבר שלשת אלפים משל</b>: מלכים א ה, יב."],["1531","10","<b>לשמרך מאשה זרה</b>: משלי ז, ה."],["1532","11","<b>ויחכם מכל האדם</b>: מלכים שם, יא."],["1533","12","<b>עמוק עמוק מי ימצאנו</b>: ע\"פ קהלת ז, כד."],["1534","13","<b>דהווה אמר ג' מאה משלים</b>: סנהדרין לח, ב."],["1535","*13","<b>שמחפה לגלגלתא</b>: כ\"ה בהכת\"י."],["1536","14","<b>שניקב המוח במשהו טריפה</b>: חולין מב, א."]]],[2101920277,"מתלבש גם בעשי' גשמי' כנ\"ל, וה\"ז כנ\"ל במשל חכם הגדול שא\"א לזולתו להבין דבריו כ\"א ע\"י משל דוקא, והוא בלבד לרוב עמקות חכמתו הוא שיכול להמציא משל חיצוני, וכן משל האבוקה הגדולה המאירה למרחוק דוקא כנ\"ל, וזהו הענין הנז' שמו\"ס הוא מקור האורות פנימי' כי הנה כתי' ראשית<sup data-n=\"1537\">15</sup> חכמה שמחכמה ואילך הוא בחי' השתלשלות העולמות עו\"ע וגם החכמה בכלל, ואמנם זהו בחי' חכמה דאצילות המלובש בכלי ונק' מוחא<sup data-n=\"1538\">16</sup> דאתפתח לל\"ב שבילין שענין השביל הוא אורח להמשכה לגילוי כו' וח\"ס נק' מוחא<sup data-n=\"1539\">17</sup> דשכיך ושקיט באתרי' ואינו מתפתח ומתגלה באצי', אבל מ\"מ מקור החכמה הוא והוא בכלל או\"פ והוא בחי' ממלא כ\"ע, אבל גלגלתא מקפת על המוחין כלומר שאינה מתלבשת בבחי' גילוי פנימי ועם היותה בחי' חיצוני' אבל הוא כלי להשראת א\"ס ב\"ה והוא בחי' סוכ\"ע ונק' בשם מקיפים.\n<b>וביאור</b> הענין ממלא (פנימיות ועם היותה בחי' חיצוני) וסובב, הנה יובן ע\"פ מ\"ש בע\"ח<sup data-n=\"1540\">18</sup> ששרש התהוות הכלים הוא מהכאת האורות המקיף עם הפנימי כשפגעו זע\"ז, כי הנה ענין הכלים הוא רק בחי' הגבלת האורות שיהי' נתפסים ליש ודבר מה ולהיות מוגבל בעצמותם ולא להיות בבחי' ביטול והסתלקות למעלה לגמרי, כי הרי כשנאצל האור אזי מצד טבעם הי' מסתלק במאציל לגמרי כמקדם היותו כי ע\"ס בלי מה, ולכן שיהי' האור נתפס ליש ודבר בפ\"ע דהיינו שיהי' מציאות החכמה נראית ליש ודבר מה וזהו הנק' בחי' כלי שמקבלים האורות ועושים אותה ליש ודבר מה והיינו כלי החכמה כלי החסד כנ\"ל, והתהוות זו דווקא מא\"ס ב\"ה הסוכ\"ע כי האורות עצמן להיות נמשכין מבחי' ממכ\"ע שהוא ענין הק\"ו שלאחר הצמצום לכן הם באמת בלי מה דהיינו בחי' ביטול לגמרי כנר כו', כי מהארה זו דממכ\"ע א\"א להיות התהוות היש ודבר נפרד ממנו כ\"א בדרך עו\"ע וכל עלול דבוק בעילתו בטבעו כו', אלא דוקא מא\"ס ב\"ה הסוכ\"ע שהוא כל יכול יוכל להיות גם מציאות נפרד ממנו ממש שלא בדרך השתלשלות עו\"ע דהיינו ע\"י השפעות אור ממנו להתלבש בפנימיות המחייהו לבד, אלא כמ\"ש כי<sup data-n=\"1541\">19</sup> הוא צוה ונבראו צוה בלבד ואין בזה שום התלבשות אור וחיות ממנו בפנימיותם ואעפי\"כ יכול להיות חי וקים כי כל יכול הוא כנ\"ל לכך יוכל להיות בחי' יש ודבר משא\"כ כל עלול המקבל חיות מעילתו בפנימיות טבעו להיות דבוק בעילתו כי הוא עצם מעצמותו ואינו נפרד ממנו כו', ולכן מבואר בע\"ח<sup data-n=\"1542\">20</sup> שהתהוות הכלים הוא דוקא מן האור המקיף שמצחצח את הכלים והוא בחי' סוכ\"ע שהוא דוקא הגורם להיות התהוות היש כו'.",[["1537","15","<b>ראשית חכמה</b>: תהלים קיא, י. ועוד."],["1538","16","<b>מוחא דאתפתח לל\"ב שבילין</b>: ראה זח\"ג קכח, ב. וראה ס' מאמרי אדהאמ\"צ בראשית ע' ג. שמות ח\"א ע' לג. ובהמ\"מ שם."],["1539","17","<b>מוחא דשכיך ושקיט באתרי'</b>: ראה זח\"ג שם."],["1540","18","<b>בע\"ח ששרש התהוות הכלים הוא מהכאת האורות המקיף</b>: ראה ע\"ח שער העקודים (ש\"ו) פ\"א. פ\"ה. שער עתיק (שי\"ב) פ\"ד. וראה מאמרי אדה\"ז אתהלך לאזניא ע' רכב. ובכ\"מ."],["1541","19","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה."],["1542","20","<b>בע\"ח שהתהוות הכלים הוא דוקא מן האור המקיף</b>: ראה בהנסמן לעיל בסמוך."]]],[2101920278,"<b>וביותר</b> מובן זה בהתהוות עולם השפל דעשי' שלנו וכל אשר בו כי הגם שבע\"מ נברא העולם יהי<sup data-n=\"1543\">21</sup> אור ויהי אור כו' היינו להחיות רוחני' של הנבראים אבל להיות התהוות גשמיות הנבראים וחומרם זהו דבר שלא אפשר להיות מהמאמרות עצמן שהם המשכות החיות רוחני מבחי' ממכ\"ע כי אין ערוך כלל בין גשמיות לרוחניות ואין להם שייכות זא\"ז, ושיהי' גשמיות מתהווה מן הרוחני' כו' אין זה דוקא אלא מא\"ס ב\"ה הסוכ\"ע שהוא ית' כל יכול, פי' כי הרי באמת הוא מובדל ומרומם בערך גם מבחי' ח\"ע ראשית השתלשלות, והחכמה עם העשי' הגשמיות שוין אצלו ית' כידוע בפי' אין ערוך, שאלו החכמה יש לה שייכות קצת למהותו ית' יותר מהעשי' הגשמיי' א\"כ הרי יש לה ערך אליו כו' אלא בוודאי שהן שווין בערך קמי' ית' וא\"כ כמו שיכול להיות התהוות החכמה מעצמותו ית' כך יכול להיות העפר גשמי דעשי', כי הגם שהחכמה היא רוחניות והעפר הוא גשמי ואין להם ערך זא\"ז היינו לבינם ולבין עצמם, אבל לגבי עצמותו ית' שניהם שוין בדילוג הערך מאתו ית' והתהוותם שלא ע\"י התלבשות החיות והשתלשלות עו\"ע אלא כמ\"ש כי הוא צוה ונבראו כו' שיכול להיות ממנו התהוות גם דבר יש בדילוג הערך וזהו הענין כל יכול כו'.\n<b>והנה</b> בחי' סוכ\"ע הוא הנק' לבוש מל', פי' כי הארת מל' דא\"ס המתלבש בקו\"ח שנמשך אחר הצמצום ומק\"פ הוא הנק' בשם ממכ\"ע בכללות ההשתלשלות פי' שמתלבש בפנימיות העולמות ומתחלקת בכל עולם ועולם לפי ערכו ותכונתו ובכלל הוא בחי' ציור אדם, מראשית חב\"ד הם מוחין ובהם החיות הגדול יותר ואח\"כ חו\"ג זרועות ת\"ת גופא כו' וכן בכלל נק' אצי' חכמה ובינה בריאה כו', ואמנם לבוש מל' הוא עד\"מ הלבוש כמו טלית שהאדם מתעטף בו ועטופו ממעל לראשו ומעטפו מכל צד ופינה, כמ\"כ למעלה הוא ענין לבוש מל' הוא בחי' א\"ס ב\"ה מלמעלה מהקו\"ח והוא העיגול הגדול שמקיף לחללו ומק\"פ שבו הקו\"ח וסובב לכל הד' עולמות בשוה כי קמי' כולם שוים כנ\"ל והוא ממעל לראשו דהיינו ממעל לבחי' גלגלתא שהוא בחי' כתר דאצי' שעם היותו נק' בשם מקיף היינו בדרך פרט לגבי מו\"ס שהוא מבחי' פנימיות ממש להיות בחי' חכמה כנ\"ל אבל לגבי עצמותו ית' הרי הוא עדיין בחי' תחתונה שבמאציל כידוע<sup data-n=\"1544\">22</sup> שהכתר הוא ממוצע בין מאציל לנאצלים ויש בו מבחי' תחתונה שבמאציל והוא בחי' גלגלתא דא\"א ששם השראת א\"ס ב\"ה הסוכ\"ע ששורה בו בחי' הרצון כו' כנ\"ל.\n<b>וזהו</b> ענין יביאו לבוש מל' דהיינו להיות המשכת א\"ס ב\"ה הסוכ\"ע ע\"י אתעדל\"ת בעשי' וגשמיות כענין שהקדימו<sup data-n=\"1545\">23</sup> נעשה כו' כי שרש העשי' נלקח משם דוקא כו', ואח\"כ ואשר ניתן כתר מל' בראשו הוא בחי' המצות כי תרי\"ג<sup data-n=\"1546\">24</sup> מצות דאורייתא וז' מצות דרבנן הם בגימ' תר\"ך שהם תר\"ך עמודי אור הנמשכים מכתר",[["1543","21","<b>יהי אור ויהי אור</b>: בראשית א, ג."],["1544","22","<b>כידוע שהכתר הוא ממוצע</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. ובכ\"מ."],["1545","23","<b>שהקדימו נעשה</b>: שבת פח, א."],["1546","24","<b>תרי\"ג מצות דאורייתא וז' מצות דרבנן הם בגימ' תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שטז, א. מאו\"א מע' תר\"ך סנ\"ו. ובהמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"א לע' שלח."]]],[2101920279,"עליון, והמשכה זו הוא ע\"י מעשה המצות וכמ\"ש בעטרה<sup data-n=\"1547\">25</sup> שעטרה לו אמו והיינו ע\"י שהקדימו נעשה כו'.\n<b>ובחי'</b> עוד וסוס אשר רכב עליו המלך ענין הסוס שהוא ע\"ד שארז\"ל<sup data-n=\"1548\">26</sup> בלילה מאי קעביד רוכב על כרוב קל שלו ושט בח\"י אלף עלמין שנאמר רכב אלקים רבותיים אלפי שנאן א\"ת שנאן אלא שאינן שחסר ב' אלפים משני רבותיים כו', ופי' כי ח\"י אלף עולמות הן בבי\"ע ושרשן באצי' הוא בחי' ח\"י חוליות והן ח\"י ברכאן דצלותא שהן המשכות ברוך אתה כו' מלשון ברכה והמשכה להיות הוי' אלוקינו והמשכות הן מבחי' חכים<sup data-n=\"1549\">27</sup> ולא בחכמה ידיעא מבין ולא בבינה כו' עד בחי' נו\"ה שהן כלי השפעה והן ג' ברכות אחרונות רצה ומודים כו' ונשפעים ונמשכים מאצי' לבי\"ע אזי נעשה מהם ח\"י אלף עולמות כי בי\"ע הם בעלי גבולים לגבי אצי' כי הגם שהמלאכים גדולים מאד סנד\"ל ת\"ק<sup data-n=\"1550\">28</sup> שנה כו', מ\"מ בחי' גבול הוא ואינן יכולין לקבל האור וההמשכה כמו שהוא באצי' וכענין שארז\"ל הושיט<sup data-n=\"1551\">29</sup> אצבעו הקטנה ביניהם כו' אלא ע\"י שבכאו\"א מתחלקת לאלף.\n<b>והנה</b> ההמשכה מאצי' לבי\"ע הוא ע\"י כרוב פי' כרוב הוא האדם הקטן כידוע בדרז\"ל כתוב<sup data-n=\"1552\">30</sup> אחד אומר ופני הא' פני הכרוב וכתיב כמראה אדם כו' כאן באנפי רברבי וכאן באנפי זוטרי, והענין כי<sup data-n=\"1553\">31</sup> האדם בגימ' מ\"ה וידוע ענין שם מ\"ה שהוא במילוי אלפי\"ן וצורת הא' הוא שני יודין ח\"ע וח\"ת וביניהם וי\"ו והוא בחי' התכללות והתחברות ב' יודי\"ן הוא ע\"י הוא\"ו שביניהם המחברם, ועיקר התחברות הוא ע\"י ביטול כידוע<sup data-n=\"1554\">32</sup> בענין עושה שלום במרומיו בין שר של מים ושר של אש שאין מכבין זא\"ז שהוא מחמת תוס' גילוי א\"ס ב\"ה עליהם ביותר מכפי מזג התמידי שלכך מתבטלים ממציאותם וממילא נעשה שלום גם בין שני הפכים כמים ואש לפי שאין כ\"א מרגיש א\"ע ליש כו', וכך הוא ג\"כ ענין שם<sup data-n=\"1555\">33</sup> מ\"ה אורח אצי' שהוא בחי' התכללות הספי' זע\"ז ע\"י גילוי א\"ס ב\"ה.\n<b>והנה</b> עיקר השראת והתגלות א\"ס ב\"ה בבחי' המוחין חב\"ד כידוע וע\"י המוחין נמשך ונתפשט הארה גם במדות כו' וזהו ענין אדם שבחי' אדם הוא פרצוף",[["1547","25","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."],["1548","26","<b>שארז\"ל בלילה מאי קעביד . . רכב אלקים</b>: ע\"ז ג, ב. תהלים סח, יח."],["1549","27","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["1550","28","<b>ת\"ק שנה</b>: חגיגה יג, א ואילך."],["1551","29","<b>הושיט אצבעו הקטנה ביניהם</b>: יומא כא, ב. סנהדרין לח, ב."],["1552","30","<b>כתוב אחד אומר ופני הא' . . כמראה אדם</b>: ראה חגיגה יג, ב. יחזקאל א, יד. שם א, כו."],["1553","31","<b>כי האדם בגימ' מ\"ה</b>: ע\"ח שער התיקון (ש\"י) פ\"ג. ובכ\"מ."],["1554","32","<b>כידוע בענין עושה שלום במרומיו</b>: איוב כה, ב. במדב\"ר פי\"ב, ח. וראה לעיל בהביאור על ד\"ה ביום השמע\"צ. וש\"נ."],["1555","33","<b>שם מ\"ה אורח אצי'</b>: ת\"ז בהקדמה שם. וראה בהמ\"מ בס' שערי אורה לדף עא, א."]]],[2101920280,"שלם ממוחין ומדות, אך יש ב' בחי' אדם והוא בחי' אדם הגדול ובחי' אדם הקטן והוא הנק' ג\"כ כרוב, כי הנה יש מוחין דקטנות ומוחין דגדלות וכשהמוחין הם דגדלות אזי התלבשות א\"ס ב\"ה ביתר שאת ויתר עז משהם מוחין דקטנות ואזי ממילא גם ההתכללות במדות המסתעף על ידם הוא יתר מע\"י המוחין דקטנות, ולכך באצילות נק' אדם הגדול כי שם הוא מוחין דגדלות וממילא שא\"ס ב\"ה מאיר שם בגילוי יותר ועי\"ז הוא שם בחי' התכללות יותר מבבי\"ע ששם הוא בחי' מוחין דקטנות ואין שם גילוי א\"ס ב\"ה וממילא שהוא בחי' התחלקות יותר מבאצי' וכנ\"ל שמח\"י ברכאן דאצי' כשנמשכים לבי\"ע יתחלק לח\"י אלף עלמין כו' והיינו שלפי שמקבלים מבחי' כרוב והוא בחי' מט\"ט<sup data-n=\"1556\">34</sup> דשמו כשם רבו וגם הוא בחי' אדם שהוא בחי' מה אבל הוא אדם הקטן כי הוא בחי' מוחין דקטנות וז\"ש כי<sup data-n=\"1557\">35</sup> נער הייתי וגם זקנתי כו', וממנו מקבלים המלאכים אור וחיות ולכן הוא בלילה דוקא ע\"ד מ\"ש ותקם<sup data-n=\"1558\">36</sup> בעוד לילה ותתן טרף כו' בלילה דוקא אז מקבלים המלאכים מזונם. אמנם כ\"ז הוא בבי\"ע שהם בחי' רוחניות עדיין ושם ההשפעה נמשכת ע\"י כרוב שהוא מט\"ט כנ\"ל, אבל להיות המשכה בעולם השפל הגשמי שלנו א\"א להיות ע\"י הכרוב שהוא מט\"ט כי אינו יכול להשפיל עצמו למטה כ\"כ אלא ע\"י בחי' סוס דוקא והוא מ\"ש וסוס אשר רכב עליו המלך עד\"מ בגשמיות שהסוס גדול כוחו יותר מהאדם ויוכל לישא את האדם עליו גם למקום שלא יוכל להגיע שמה בעצמו כמ\"כ בחי' סוס העליון יוכל להוריד החיות למטה כ\"כ מאצי' עד עולם העשי' שלנו במרוצה גדולה מה שאין ביכולת בחי' הכרוב שהוא נער מט\"ט כנ\"ל שאינו יכול להמשיך ולהוליך השפע כ\"א מאצי' לבי\"ע הרוחני' אבל לא בעשי' גשמי' כנ\"ל.\n<b>והענין</b> הוא שהכרוב שהוא אדם הקטן הוא בחי' שם מ\"ה ובחי' סוס הוא בחי' שם ס\"ג כי<sup data-n=\"1559\">37</sup> ב' פעמים ס\"ג הוא בגימ' סוס ונודע שבחי' שם ס\"ג הוא למעלה מבחי' שם מ\"ה ולכן יכול להשפיל עצמו ולירד למטה יותר משם מ\"ה כנ\"ל באריכות שכל הגבוה גבוה יותר יותר יוכל לירד ולהשפיל עצמו למרחוק יותר וכמשל האבוקה הגדולה מתפשט אורה גם למרחוק כו'. והנה כתיב ויקח<sup data-n=\"1560\">38</sup> המן את הלבוש ואת הסוס ולא נזכר כתר מל', והענין כי המן הוא מזרע עמלק חוצפה מל'<sup data-n=\"1561\">39</sup> בלא תגא שמדתו הוא בחי' הגסות, ובאמת ארז\"ל ת\"ח<sup data-n=\"1562\">40</sup> צ\"ל בו שמיני' שבשמיני' שנאמר כולו ס\"ג וכנז' לעיל הטעם שהרי א\"א להיות שום",[["1556","34","<b>מט\"ט דשמו כשם רבו</b>: סנהדרין לח, ב. ובכ\"מ."],["1557","35","<b>כי נער הייתי</b>: תהלים לו, כב."],["1558","36","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["1559","37","<b>כי ב' פעמים ס\"ג הוא בגימ' סוס</b>: ראה גם במ\"מ בס' שערי אורה שם סב, ב."],["1560","38","<b>ויקח המן את הלבוש</b>: אסתר ו, יא."],["1561","39","<b>מל' בלא תגא</b>: ראה סנהדרין צט, ב. קה, א. ס' מאמרי אדה\"ז תקס\"ג ח\"א ע' ר."],["1562","40","<b>ת\"ח צ\"ל בו שמיני' שבשמיני'</b>: ראה סוטה ה, א. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תעז. ס' מאמרי אדהאמ\"צ קונטרסים ע' שפח. ובלקוטי שיחות חכ\"ב ע' 162. וב”רשימות\" חוב' טו ע' 6 ואילך. תורת מנחם ח\"ג ע' 151."]]],[2101920281,"התחלת עבודת ה' אפילו בכלות הנפש אליו ית' אם לא יהי' בו שמץ גאות להיות נחשב קצת בעיניו שיהי' עכ\"פ מי שיכלה נפשו שאל\"כ הרי איך יתהווה בכלות הנפש מי הוא זה ואי זה הוא ראוי לזה כו', וע\"ד דוד<sup data-n=\"1563\">41</sup> דגבה לבו בדרכי ה' וכן רשב\"י<sup data-n=\"1564\">42</sup> אמר אנא סימנא בעלמא, ולכן גם מהמן יכול להיות בירורי ניצוצות הקדושה דהיינו שמהגדלות הגמורה יוכל להתברר מקצת גיאות דקדושה הראוי' לעבודת ה' כו' ולכן יכול הוא ליקח את הלבוש ואת הסוס כי הסוס הוא בחי' לבוש מל' שנאמר ה'<sup data-n=\"1565\">43</sup> מלך גאות לבש כו' והוא גיאות אלקות שהוא ית' מתנשא ומלך עלינו כו' וע\"י בירורי ניצוצי הקדושה שבהמן יוכל להתהוות בחי' זו, וכן בחי' הסוס שהוא בחי' שם ס\"ג בהיפך אתוון ג\"ס אלא שהוא יש שבקדושה יכול ג\"כ להיות מתהווה מבירורי הניצוצות שבהמן, משא\"כ בחי' כתר מל' שהוא סוד תרי\"ג מצות דאורייתא וז' מצות דרבנן שנמשכין מגלגלתא ונק' תר\"ך עמודי אור ופנימיותם הוא החכמה שמשם מקור התורה שהוא ביאור ופירושי המצות זה אינו שייך אלא לישראל בלבד שלהם נתנה התורה, וז\"ש בעטרה שעטרה לו אמו, אמו דוקא הוא כנ\"י שלא<sup data-n=\"1566\">44</sup> זז הקב\"ה מחבבה עד שקראה אמי הוא דוקא שיכול לעטרה בעטרה הלזו דכתר מל' אפס זולתה.\n<b>והנה</b> כתי' וילבש<sup data-n=\"1567\">45</sup> המן את מרדכי כי מרדכי<sup data-n=\"1568\">46</sup> מן התורה מנין שנאמר מר דרור ותרגומו מירא דכיא והענין כי יש ב' בחי' מרדכי א' בחי' יסוד אבא כמו שהוא עדיין למעלה באצי' והוא הנק' מר דרור פי' דרור כענין מ\"ש וקראתם<sup data-n=\"1569\">47</sup> דרור עלמא דחירו שבאצי' הוא משומר ממגע הקליפות ולא<sup data-n=\"1570\">48</sup> יגורך רע כתי', והב' בחי' יסוד אבא כמו שנשפל למטה בתורה להיות כשר פסול טמא וטהור שהם סוד הבירורים שבבי\"ע ואזי נק' מירא דכיא כי התלבשותו בענינים גשמיי' דכיין ומסאבין כו', ובאמת שבחי' זו יותר גבוה כי יכולת הירידה והתלבשות למטה מטה כ\"כ הוא ממקום גבוה ביותר כנ\"ל, וכן הוא בחי' אסתר שנאמר בה ואנכי<sup data-n=\"1571\">49</sup> הסתר אסתיר פני ביום ההוא פי' יום ההוא הוא בחי' בינה ואימא<sup data-n=\"1572\">50</sup> עילאה מקננת בכורסייא הוא עולם הבריאה, ומ\"ש באסתר ואנכי אסתיר פני ביום ההוא",[["1563","41","<b>דוד דגבה לבו בדרכי ה'</b>: בדברי הימים ב יז, ג-ו: ויהי ה' עם יהושפט כי הלך בדרכי דוד אביו גו' ויגבה לבו בדרכי ה'. וראה תו\"א צב, א. שערי אורה עג, א. ס' פירוש המלות לאדהאמ\"צ צח, א. תורת מנחם ח\"ז ע' 209."],["1564","42","<b>רשב\"י אמר אנא סימנא בעלמא</b>: זח\"א רכה, א. וראה גם ס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תקלח. וש\"נ."],["1565","43","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["1566","44","<b>שלא זז הקב\"ה מחבבה</b>: ראה שהש\"ר ספ\"ג. פסיקתא דר\"כ פ\"א. ובכ\"מ."],["1567","45","<b>וילבש המן את מרדכי</b>: אסתר ו, יא."],["1568","46","<b>מרדכי מן התורה מנין שנאמר מר דרור</b>: חולין קלט, ב. תשא ל, כג. וראה בהמ\"מ בס' שערי אורה לדף נז, א."],["1569","47","<b>וקראתם דרור</b>: בהר כה, י."],["1570","48","<b>ולא יגורך רע כתי'</b>: תהלים ה, ה."],["1571","49","<b>ואנכי הסתר אסתיר</b>: וילך לא, יח. חולין שם."],["1572","50","<b>ואימא עילאה מקננת בכורסייא</b>: ת\"ז ת\"ו (כג, א)."]]],[2101920282,"שמסתתרת<sup data-n=\"1573\">51</sup> בראש הבריאה כי מל'<sup data-n=\"1574\">52</sup> דאצי' נעשה עתיק שהוא העלם וסובב ומקיף לבריאה, ופי' אסתיר פני שכן נק' מל' דאצי' לפי שמקבלת מכל הי\"ס דאצי' ממל' שבכתר דאצי' נעשה כתר שבמל' ומל' שבחכמה נעשה חכמה שבמל', ולע\"ל כתיב ואמר<sup data-n=\"1575\">53</sup> ביום ההוא הנה אלקינו זה שבחי' בינה שהוא עלמא דאתכסייא יתגלה אז עד שתהי' בבחי' זה, אמנם בחי' אסתר שהוא עתיק דבריאה ששרשו בעתיק דאצילות הרי גם לע\"ל תהי' למעלה מהשגה. וז\"ש כל<sup data-n=\"1576\">54</sup> הנביאים שהם מנו\"ה בטלים לפי שלע\"ל<sup data-n=\"1577\">55</sup> יהי' זו\"נ שווין בקומתן ולא תצטרך לקבל מנו\"ה אבל ימי הפורים ששרשה בכ\"ע לא יעברו וכן ההלכות ששרשם ג\"כ מנימין דמו\"ס כנ\"ל, ולכן נאמר וילבש המן את מרדכי שהי' הלבוש מל' נצרך להלביש את מרדכי כדי שתוכל לירד למטה כ\"כ כו' וד\"ל.",[["1573","51","<b>שמסתתרת בראש הבריאה</b>: ראה ע\"ח שער כסה\"כ (שמ\"ו) פ\"ו. וראה בהמ\"מ בתו\"א צב, א."],["1574","52","<b>מל' דאצי' נעשה עתיק</b>: ראה ע\"ח שער העקודים (ש\"ו) פ\"ב."],["1575","53","<b>ואמר ביום ההוא הנה אלקינו זה</b>: ישעי' כה, ט."],["1576","54","<b>כל הנביאים כו' בטלים</b>: ראה ירושלמי מגילה פ\"א ה\"ה."],["1577","55","<b>שלע\"ל יהי' זו\"נ שווין בקומתן</b>: ראה ע\"ח שער הזווגים (שט\"ו) פ\"א. שער מיעוט הירח (של\"ו) פ\"א. שער סדר אבי\"ע (שמ\"ז) פ\"ד ופ\"ה."]]],[2101920283,"<h3>בגמרא ר\"ה גבי כורש</h3>\n<b>בגמרא</b><sup data-n=\"1578\">1</sup> ר\"ה דף ד' גבי כורש כאן קודם שהחמיץ כו' די להון מקרבין ניחוחין לאלה שמיא ומצלין לחיי מלכא ובנוהי, והקשה הש\"ס ומאן דעביד הכי לאו מעליותא היא והתניא האומר סלע זו לצדקה בשביל שיחי' בני ובשביל שאזכה בה לחיי העה\"ב ה\"ז צדיק גמור, ומשני ל\"ק כאן בישראל כאן באומות. והקשה<sup data-n=\"1579\">2</sup> התוס' מהא דתנן פ\"ק דאבות אל תהיו כעבדים המשמשין את הרב ע\"מ לקבל פרס, ותי' דהיינו באומות העולם שתוהין על הראשונות, ותירוץ זה אין לו הבנה דאם באומות העולם שתוהין על הצדקה אם לא הטיבו לו בגללה כו' איסור גמור בדבר כמ\"ש כאן בכורש דקרי לי' החמיץ כו' ולא שייך ע\"ז ל' אל תהיו כעבדים כו' שאמר אנטיגנוס דמשמע שהוא רק עצה טובה שמצוה כן לתלמידיו כו'.\n<b>לכן</b> הנלע\"ד לתרץ הגמרות בע\"א, והוא בהקדים ענין הנהוג בימי חכמי התלמוד כנודע ומפורסם בש\"ס שהיו כופין וממשכנין על הצדקה כדין דקופה של",[["1578","1","<b>בגמרא ר\"ה</b>: נדפס כאן מגוכי\"ק אדמו\"ר הצ\"צ בס' ההנחות של תקע\"ב 1116 [כז, ב]. ונדפס ג\"כ בקובץ יגדיל תורה (ניו-יורק) סיון-תמוז ה'תש\"מ (חוב' ל\"ו סי' קל\"ח). ובמאמרי אדה\"ז על מארז\"ל ע' פז."],["1579","2","<b>והקשה התוס'</b>: ראה תוס' פסחים ח, ב ד\"ה שיזכה. ע\"ז יט, א ד\"ה ע\"מ. ומפרשי המשנה אבות פ\"א מ\"ג."]]],[2101920284,"צדקה נגבית בשנים שהם שמין כאו\"א כמה ראוי לגבות ממנו ואם אינו רוצה כופין אותו כו' וכמ\"ש<sup data-n=\"1580\">3</sup> בגמ' רבא אכפיי' לר\"נ בר אמי כו' ומתחלקת בשלשה. אך מזה לא היו עושי' ונותנים רק דברים ההכרחיים לעניים לחם לאכול ובגד ללבוש בצמצום די סיפוק חיותן ולא היו נותנים להם בריוח כ\"כ כסעודת ההרחבה בבשר כו' וכן בלבושי' חשובי' רק די סיפוקו בלבד בצמצום כי על ההרחבה לעניים אין מצוין ע\"ז כ\"כ כמ\"ש להחיותו, להחיותו בלבד ולא לענגו ולכן אין כופין וממשכנין ע\"ז כלל כי קיים זה מ\"ש בתורה מצות צדקה במה שנתן לצורך די סיפוקו שכך הוא המצוה שמוכרח לקיימה ושע\"ז כופין וממשכנין כו', הא על יותר מזה אינו מחוייב לקיים, עם היות כי גם זו מצוה היא באמת ורצון ה' היא עכ\"ז היא כתוספת על העיקר ואין מוכרח לקיימה ואין כופין אותו ע\"ז אם אינו רוצה, אבל עיקר המצוה שהוא להחיותו מוכרח לקיים ובאם אינו רוצה כופין וכו'.\n<b>והנה</b> ענין האומר סלע זו לצדקה ע\"כ שהוא על צורך ההרחבה של העניים יותר מכפי צורכן, כי מה שמחוייב ליתן לצורך להחיותם הנ\"ל בודאי כבר נתן כי היו כופין ע\"ז ומה זה אומר סלע זו לצדקה בשביל כו' הלא מוכרח הי' ליתן, רק שפירושו שנותן סלע לצדקה בתוספת על מה שנתן די חיובו, ומוותר זאת משלו לצורך הרחבת העניים כנ\"ל כי גם זו מצוה היא, ואומר בשביל שיחי' בני או שאזכה בה לחיי העוה\"ב ה\"ז צדיק גמור, אחר שמה שהי' צריך ליתן לקיים עיקר המצוה מתרי\"ג מצות שנצטוה בהם כבר קיים ונתן לגבאי צדקה, לא ע\"מ תנאי זה רק לקיים רצון ה' מבלי שום פני' כלל, וא\"כ צדיק גמור הוא, ומה שמקיים מצוה בנתינת סלע זו לצדקה עם היותה בשביל פני' שיחיו בניו ושיזכה בהם לחיי העוה\"ב מ\"מ אין בזה שום מדה לא טובה ח\"ו, ואדרבה מקרי צדיק גמור בקיומה כי הרי סלע זו הוא תוספת על העיקר כנ\"ל ומותר לכתחלה ליתנו בשביל טובת דבר עצמו הן בגשמיות בעוה\"ז והן ברוחניות לעוה\"ב.\n<b>ולא</b> אמרו אל תהיו כעבדים המשמשים את הרב ע\"מ לקבל פרס כו' דמשמע שאינו צריך לקיים מצוה בשביל קבלת פרס כנ\"ל ואם עשה כן לא מקרי צדיק גמור, אלא על עיקרי המצות שמחוייב לקיימן כל הבא בדת יהודי' לשמוע בקול ה' ולשמור מצותיו ותורותיו, שאותן המצות צריך לקיימן רק מצד כי רצון ה' הוא ונח\"ר לפניו כו' ולא בשביל קבלת פרס עצמו כי אם עושם בשביל קבלת פרס עצמו נמצא עובד את עצמו ולא את רבו, אלא צריך לקיימם ולעשותם רק בשביל קיום רצון הבורא ית' שיש נח\"ר לפניו כשנעשה רצונו כו' וסוף<sup data-n=\"1581\">4</sup> הטובה לבא בכללה, וכל זה לא שייך רק בעיקרי המצות שמחוייב לקיימן למלאות רצון הבורא ית' וכנ\"ל בענין עיקר המצוה די להחיות העני שע\"ז כופין וכו', משא\"כ",[["1580","3","<b>וכמ\"ש בגמ' אכפיי' לר\"נ</b>: ב\"ב ח, ב."],["1581","4","<b>וסוף הטובה לבא בכללה</b>: ראה רמב\"ם הל' תשובה פ\"י ה\"ב."]]],[2101920285,"על התוספת מה שגם אם לא הי' עושו<sup data-n=\"1582\">5</sup> הי' יוצא ידי חובתו והי' מקיים רצון הבורא ית' שנח\"ר לפניו כשנעשה רצונו בעיקר המצוה כנ\"ל, הנה גם אם עושה זה ע\"מ לקבל פרס צדיק גמור יחשב.\n<b>ולזה</b> ניחא ל' אל תהיו כעבדים המשמשין כו', כי כמו העבד שמוכרח לעשות לרבו דברי' המצטרכי' לו וכך ישראל מחוייבים לשמור ולעשות תרי\"ג מצוה שצוה להם הבורא ית', ועל מצות אלו אומר אל תהיו כעבדים המשמשין את הרב גם בעיקרי הדברים שמחוייב לעשות לצורך רבו ע\"מ לקבל פרס כנ\"ל כי א\"כ אינו עובד את רבו כלל, אכל על תוספי המצות שעושה אין כוונתו כלל, כי גם אם עושה ע\"מ לקבל פרס מקרי צ\"ג שהרי המוטל עליו חובה לשמש את רבו כהצטרכותו כבר קיים שלא בשביל שום תשלום גמול כנ\"ל, וזה התוספת גם אם עושה ע\"מ לקבל פרס מקרי צ\"ג כנ\"ל.\n<b>ולזה</b> יתכן גם מה שאמר בלשון אל תהיו לשון עצה בלבד אל תהיו כו' ולא כמ\"ש כאן בגמ' ר\"ה בכורש דקרו לי' החמיץ כו' לפי שאו\"ה תוהין על הראשונות משא\"כ ישראל ולכן אף גם על עיקר המצוה כשעשה ע\"מ לקבל פרס לא שייך לומר החמיץ בל' איסור רק על תהיו כו' אבל על התוספ' מותר לכתחלה וכברייתא דהאומר סלע זו לצדקה ה\"ז צ\"ג וד\"ל, משא\"כ באו\"ה שתוהין גם על תוס' מצוה אם עושה ע\"מ כו' נק' החמיץ כי אין נפקותא מאחר שתוהה אם לא הטיבו לו כו' וד\"ל.\n<b>ונמצא</b> עכ\"פ מובן מכ\"ז שבכל המצות, אם עושה התוספת שלהן גם ע\"מ לקבל פרס מקרי צ\"ג ובלבד שיקיים גם העיקר בלי שום תשלום גמול, וכמו בת\"ת ללמוד כדי שישיג אח\"כ פנימי' התורה כמ\"ש אשרי<sup data-n=\"1583\">6</sup> מי שבא לכאן ותלמודו בידו כו' הוי צ\"ג ובלבד שילמוד פרק א' שחרית וערבית בלי שום על מנת שבזה יוצא י\"ח מצות ת\"ת.\n<b>ואגב</b> נתרץ קושיות התוספת בב\"ב ד\"ח ע\"ב ד\"ה אכפי' לר\"נ, וא\"ת והא בפ' כ\"ה אמר כל מ\"ע שמתן שכרה בצדה אין ב\"ד של מטה מוזהרים עליה וגבי צדקה כתי' כי פתוח תפתח את ידך לו וכתי' כי בגלל הדבר הזה יברכך כו', וא\"ל<sup data-n=\"1584\">7</sup> דמעיקרא לא קשי' כלל דכך כתי' בפ' ראה פתוח תפתח כו' נתן תתן ולא ירע לבבך בתתך לו כי בגלל הדבר הזה יברכך כו' והיינו בגלל מה שלא ירע לבבך בתתך לו ומכיון שב\"ד כופין אותו א\"כ לא קיים מ\"ש ולא ירע לבבך כו' ולא הוה מתן שכרה בצדה ולכן ב\"ד מוזהרים עלי' לכופו וד\"ל.",[["1582","5","<b>עושו</b>: כ\"ה בהכת\"י."],["1583","6","<b>אשרי מי שבא לכאן</b>: פסחים נ, א."],["1584","7","<b>וא\"ל</b>: ואפשר לומר."]]],[2101920286,"<h3>ויקרא אלף זעירא</h3>\n<b>ויקרא</b><sup data-n=\"1585\">1</sup> אלף זעירא כו', אדם<sup data-n=\"1586\">2</sup> כי יקריב מכם קרבן לה' מן הבהמה ומן הבקר ומן הצאן תקריבו את קרבנכם. ויש להבין בזה למה תחלה דבר ל' יחיד, אדם כי יקריב, ואח\"כ אמר ל' רבים תקריבו, הל\"ל יקריב ל' יחיד כמו ברישא. וגם יש להבין מהו אדם כי יקריב ולא אמר איש, כמו שבכל הפרשיות נאמר איש כו'. ועוד מכם זה מיותר הוא, הל\"ל אדם כי יקריב קרבן, מהו מכם כו'. אך הנה כתיב וזרעתי<sup data-n=\"1587\">3</sup> את בנ\"י זרע אדם וזרע בהמה, שהן בחי' ב' נפשות נפש האלקי' שנק' אדם, ונפש הבהמית נק' בהמה, וכמארז\"ל אתם<sup data-n=\"1588\">4</sup> קרוים אדם והוא בחי' אדם תתאה שבמרכבה ופני<sup data-n=\"1589\">5</sup> אדם לארבעתן, וידוע דשורש כל הנשמות דאדם זה נמשך מבחי' אדם העליון דאצי' שע\"ג הכסא שהוא בחי' ז\"א שנק' אדם<sup data-n=\"1590\">6</sup> הגדול כו', וזהו כללו' ענין זה דאדם כי יקריב מכם דוקא, דהיינו בחי' אדם העליון שע\"ג הכסא הוא המקריב בחי' נשמה דאדם התחתון, וזהו מכם שהן בחי' נשמות ישראל שנק' אדם תתאה וכמ\"ש כמים<sup data-n=\"1591\">7</sup> הפנים לפנים כן לב האדם לאדם כו', אז מן הבהמה ומן הבקר כו', שהוא שרש הנפש הבהמי' תקריבו אתם קרבנכם וזהו קרבן שאתם מקריבים, אבל מכם אד\"ם העליון הוא המקריב, וע\"כ אמר ברישא כי יקריב ל' יחיד דקאי על בחי' אדם העליון, ובסיפא אמר תקריבו ל' רבים, דהיינו קרבן אחר שמקריבים לנפש הבהמית כו', כך הוא כללו' ענין פסוק הזה וד\"ל.\n<b>ולהבין</b> כל זה הנה יש להקדים תחלה שיש<sup data-n=\"1592\">8</sup> ב' מדריגות באתעדל\"ע, הא' אתעדל\"ע הבאה מצד אתעדל\"ת דוקא (כמ\"ש<sup data-n=\"1593\">9</sup> בע\"ח דמתחלה הי' חפץ חסד ואח\"כ תלוי במעשה התחתונים), והב' בחי' אתעדל\"ע מצד עצמו שלא ע\"י אתעדל\"ת כלל, ובכאן מדבר במדריגה זו שאין אתעדל\"ת מעורר אתעדל\"ע, אלא אתעדל\"ע מצד עצמו, שהרי אמר אד\"ם כי יקריב שהוא אתעדל\"ע דבחי' אד\"ם שע\"ג הכסא כו' מצד עצמו שמקריב ומעלה לנשמות שלמטה בימין<sup data-n=\"1594\">10</sup> מקרבת, גם שאין בהן אתעדל\"ת מעצמם כלל. וראי' לזה ממה שאמר כי יקריב, כי זה משמע ענין מקרה לפרקים, כמו כאשר יקריב, ולא שזהו חיוב והכרחי תמיד, ואם כפשוטו",[["1585","1","<b>ויקרא אלף זעירא</b>: מאמר זה הוא הנחת כ\"ק אדהאמ\"צ. ונמצא בשינויים בלקו\"ת ר\"פ ויקרא (ד\"ה ויקרא אל משה וד\"ה אדם כי יקריב). ונו\"א לקמן ד\"ה אדם כי יקריב וד\"ה סוד ויקרא אל משה. ובשינויים ואריכות ד\"ה ויקרא אל משה בס' מאמרי אדהאמ\"צ ויקרא ע' א ואילך. ובאוה\"ת ויקרא כרך ג' ע' תשנא. וראה גם ביאור לעניני המאמר בלקו\"ש חי\"ז ע' 233 ואילך."],["1586","2","<b>ויקרא אלף זעירא כו' אדם כי יקריב</b>: ויקרא א, א-ב. ראה זח\"א רלט, א (ולעיל בד\"ה זוהר תרומה) זח\"ג נג, ב. פענח רזא ובעה\"ט ר\"פ ויקרא כאן."],["1587","3","<b>וזרעתי את בנ\"י</b>: ע\"פ ירמי' לא, כו: וזרעתי את בית ישראל ואת בית יהודה זרע אדם וזרע בהמה. [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ע' ב]."],["1588","4","<b>אתם קרוים אדם</b>: יבמות סא, א."],["1589","5","<b>ופני אדם לארבעתן</b>: ע\"פ יחזקאל א, י. [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ע' ג]."],["1590","6","<b>אדם הגדול</b>: יהושע יד, טו."],["1591","7","<b>כמים הפנים לפנים</b>: משלי כז, יט."],["1592","8","<b>שיש ב' מדריגות באתעדל\"ע</b>: ראה גם ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' ד. וש\"נ."],["1593","9","<b>כמ\"ש בע\"ח דמתחלה הי' חפץ חסד</b>: שער דרושי הנקודות (ש\"ח) ספ\"ו."],["1594","10","<b>בימין מקרבת</b>: ע\"פ סוטה מז, א."]]],[2101920287,"הלא מצות הקרבת הקרבן באדם למטה חובה היא ולא רשות לפרקים כאשר ירצה כו'. אך מזה הוראה גמורה דכי יקריב זה קאי באדם העליון כשמתעורר מצד עצמו דהיינו כאשר אין אתעדל\"ת כלל, שאז מתעורר מעצמו להיות כי המתין על אתעדל\"ת ואין איש מתעורר כמ\"ש אין<sup data-n=\"1595\">11</sup> קורא בשמך כו', אז יתעורר מעצמו. ודוגמא לדבר זה מה שאמרו אש\"ה<sup data-n=\"1596\">12</sup> מזרע\"ת תחלה יולדת זכר, שזהו כאשר אתעדל\"ת דכנ\"י שנק' אשה מעורר אתעדל\"ע, אבל אי\"ש מזריע תחלה היינו כשאין אתעדל\"ת כלל שאז אתעדל\"ע דבחי' דכר לנוק' שלא ע\"י העלאת מ\"ן כלל והיינו אד\"ם כי יקרי\"ב כו' וד\"ל.\n<b>ויובן</b> זה בעבודת ה' בנשמות ישראל שבגופים למטה בעוה\"ז, דהנה אנו רואים שיש ב' מדריגות בעבודת ה', הא' בחי' אתעדל\"ת ביגיעת הנפש בהתבוננות והעמקת הדעת והכנת טהרת הלב בלב נשבר כו', שעי\"ז יבא בנפשו גילוי אור קרבת אלקים כו', שזהו בחי' אתעדל\"ע שע\"י אתעדל\"ת, ומדריגה הב' היינו כאשר<sup data-n=\"1597\">13</sup> יערה עלינו רוח ממרום באתעדל\"ע שמעורר לנפש האלקית להתפעל בהתבוננות ודו\"ר שכליים שלא ע\"י הכנה ויגיעת הנפש כלל רק מפני שעת רצון הוא למעלה לעורר לנשמות שבגופים גם שאין להם התעוררות עצמם כלל וכלל, וכמו שאנו רואים שיש הרבה אנשים שיתעוררו פתאום ויתלהב לבם ומוחם בתפלה בכל יום משך זמן מה בלי נודע להם הסיבה מאין באה אליהם התעוררות זאת, ובמעט זמן מה יכלה כח התעוררות זאת כאלו לא היתה, ונופל מעבודתו לגמרי, מפני שאין לו התעוררות עצמו כלום, והיינו מפני שיערה עלינו רוח ממרום לעורר את האהבה בכנ\"י לפרקים וע\"כ אינו מתארך רק זמן מה שזה רק כפי זמן של אתעדל\"ע למעלה לעורר לנשמות כו' וד\"ל. והיינו ענין הנ\"ל בבחי' אדם כי יקריב מכם, שהוא בחי' אתעדל\"ע דאדם העליון לעורר לנש\"י למטה, וזהו כי יקריב מכ\"ם דוקא שהוא בחי' ניצוץ האלקי כו', דהנה ידוע ששרש נשמות ישראל נמשכו מבחי' אדם<sup data-n=\"1598\">14</sup> העליון שע\"ג הכסא כו' שכולל ג' קוין חסד דין רחמים, והאבות<sup data-n=\"1599\">15</sup> הן המרכבה לבחי' חג\"ת ומהם מסתעפים ס\"ר נשמות ישראל למטה בעולם הבריאה, והוא כללות בחי' אדם שבמרכבה כו' כידוע, ע\"כ באתעדל\"ע דאד\"ם שבאצי' ממילא מתעורר כל ניצוץ האלקי ששרשו באדם שבמרכבה כהמשכת הניצוץ אחר השלהבת כו', וז\"ש כמים הפנים כו' כן לב האדם לאדם כו', וכמ\"ש יעקב<sup data-n=\"1600\">16</sup> חבל נחלתו כו', וזהו שיערה עלינו רוח ממרום ומתעוררים כנ\"י מגדול עד קטן, כמו בעי\"ת שאז זמן ההתעוררות מלמעלה כידוע<sup data-n=\"1601\">17</sup> בענין דרשו ה'",[["1595","11","<b>אין קורא בשמך</b>: ישעי' סד, ו."],["1596","12","<b>אשה מזרעת תחלה</b>: ברכות ס, א. ועוד."],["1597","13","<b>כאשר יערה עלינו רוח ממרום</b>: ע\"פ ישעי' לב, טו."],["1598","14","<b>אדם העליון שע\"ג הכסא שכולל ג' קוין</b>: ראה תו\"א יתרו עא, ב-ג. עב, ד. ובכ\"מ."],["1599","15","<b>והאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["1600","16","<b>יעקב חבל נחלתו</b>: האזינו לב, ט."],["1601","17","<b>כידוע בענין דרשו ה' בהמצאו</b>: ראה ישעי' נה, ו. ר\"ה יח, א."]]],[2101920288,"בהמצאו, וגם בכל<sup data-n=\"1602\">18</sup> יום ב\"ק מכרזת שובו בנים, ומזלי'<sup data-n=\"1603\">19</sup> חזי ופועל<sup data-n=\"1604\">20</sup> התפעלות ההתעוררות של הנשמה אשר בגוף כמ\"ש במ\"א וד\"ל.\n<b>אמנם</b> אין אתעדל\"ע זו רק לנשמות דוקא מפני שנר<sup data-n=\"1605\">21</sup> ה' נשמת אדם, ע\"כ תאיר אור ע\"י אתעדל\"ע במקור חוצבה בבחי' אדם, וזהו אדם כי יקריב כאשר יקריב כשמתעורר לפעמים תחלה מפני שאין אתעדל\"ת, שאז איש מזריע תחלה כו' כנ\"ל וד\"ל. (וענין הקרבה זו הוא כמו קרבן ע\"ג המזבח שנכלל באש של מעלה כך מיכאל<sup data-n=\"1606\">22</sup> כה\"ג מקריב נשמות ע\"ג המזבח לאשתאבא<sup data-n=\"1607\">23</sup> בגופא דמלכא כו', והמקריב לנשמה זו ע\"ג המזבח הוא בחי' אדם העליון, ונק' נשמה הזאת קרבן להוי' דוקא כו' וד\"ל).\n<b>אך</b> כדי שתתקיים בחי' אתעדל\"ע זאת שאדם מקריב מכם ולא תסתלק ותתבטל בזמן מה כנ\"ל, הוא אשר אמר אח\"כ מן הבהמה והבקר כו' תקריבו את קרבנכם, דהיינו מיד שאדם העליון יקריב את נשמת האדם שנק' אדם, אז תיכף צריך אדם שלמטה להקריב קרבנו שהוא הקרבת נפש הבהמית ששרשה מבחי' פני שור כו' בחי' בהמה שהן מדות הבהמי' כמו תאוה וכעס וגסות כו', שיהפכו מרע לטוב מחשוכא לנהורא ממרירו למיתקא כמ\"ש<sup data-n=\"1608\">24</sup> בשער הקדושה לרח\"ו שקודם שהנשמה האלקי' עולה בסוד ה' בהשגות אלקי' הפנימיי' צריך להיות תחלה בירור הרוח הבהמה מכל מדה רעה כתאוות רעות וכעס וכה\"ג, ואם לא נזדכך חומר הנפש הבהמיו' מז' המדות לא תעלה הנשמה האלקי' וכמ\"ש מי<sup data-n=\"1609\">25</sup> יעלה בהר ה' כו' נקי כפים ובר לבב אשר לא נשא לשוא נפשו הוא ישא ברכה מאת ה' כו', שכאשר המדות רעות מתהפכים אז יוכל להתקיים בנפשו בחי' ברכת ה' שהוא בחי' גילוי אור האלקי בנפשו שיערה עליו תמיד רוח ממרום בבחי' אתעדל\"ע הנ\"ל זמן רב ולא יסתלק, וכמו שא' רשב\"י בחד<sup data-n=\"1610\">26</sup> קטירא אתקטרנא כו', וכמ\"ש צרורה<sup data-n=\"1611\">27</sup> בצרור החיים כו', וכמו הקרבן שלא יוכשר כשהוא בעל מום בעין או ברגל כו', כך כשלא נתברר מדות הרעות של הנפש הבהמי' שנק' גופא לגבי נשמה הרי הנשמה נק'<sup data-n=\"1612\">28</sup> חגר\"ת או סומא, ואין מיכאל כה\"ג מקריבה ע\"ג המזבח",[["1602","18","<b>בכל יום ב\"ק מכרזת שובו בנים</b>: ע\"פ חגיגה טו, א. זח\"ג קכו, א. איכ\"ר בפתיחתא פי' כב."],["1603","19","<b>ומזלי' חזי</b>: מגילה ג, א."],["1604","20","<b>ופועל התפעלות ההתעוררות של הנשמה אשר בגוף כמ\"ש במ\"א</b>: ראה לקו\"ת תצא לו, ד. ובהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' ט. דברים ח\"ב ע' תלו. ח\"ד ע' א'קעא."],["1605","21","<b>שנר ה' נשמת אדם</b>: משלי כ, כז."],["1606","22","<b>מיכאל כה\"ג מקריב נשמות</b>: ע\"פ חגיגה יב, ב. זבחים סב, א. תוד\"ה ומיכאל — מנחות קי, א. זח\"א פ, א. פא, א. זח\"ב רלא, א. וראה עוד בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ע' ב."],["1607","23","<b>לאשתאבא בגופא דמלכא</b>: זח\"א ריז, ב."],["1608","24","<b>כמ\"ש בשער הקדושה לרח\"ו שקודם שהנשמה האלקי' עולה</b>: ח\"ג שער ג'."],["1609","25","<b>מי יעלה בהר ה'</b>: תהלים כד, ג-ה."],["1610","26","<b>בחד קטירא אתקטרנא</b>: ראה זח\"ג רפח, א. רצב, א. [וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ע' יב]."],["1611","27","<b>צרורה בצרור החיים</b>: שמואל א כה, כט."],["1612","28","<b>נק' חגרת או סומא</b>: ע\"פ כתובות יז, א. וראה לקו\"ת במדבר ח, ג ואילך. אוה\"ת תולדות קמז, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ע' יא."]]],[2101920289,"העליון כו', שאין אד\"ם העליון מקריבה כלל, והיינו אם עולה קרבנו זכר תמים יקריבנו כו', שבעל מום פסול להקרבה וכמו ואת<sup data-n=\"1613\">29</sup> הקדוש והקריב אליו, כך אדם העליון יקריב נשמות קרבן להוי', מן נשמות הקדושים שאין בהן כל מום כו'),\nוזהו מן הבהמה ומן הבקר כו' תקריבו אתם, כי קרבן זה מנפש הבהמי' אין זה קרבן אדם העליון כלל, כי אדם העליון הוא שמקריב נשמות דוקא דהיינו מכם דוקא כנ\"ל, אך קרבנכם הוא אשר תקריבו מן הבהמה בחי' נפש הבהמי' ששרשה בבחי' פני שור כו', ויש בזה מדריגות רבות, בקר הוא מבחי' הגבורות כי שור נגחן הוא כו', והוא בחי' מדת הכעס גבורות קשות דשור, ובקר ובהמה<sup data-n=\"1614\">30</sup> בחי' אהבת התאוות ברשפי אש שהבהמה נק' בער כמו ושלח את בעירו כו', וצאן הוא הממוצע בין בהמה ובקר, ולמעלה היינו ג' מדות חג\"ת שבנוגה שמקבלים מפני ארי' פני שור פני נשר כו', ופני אדם הוא המבררם, וזהו תקריבו את קרבנכם שאדם התחתון מברר ומעלה לבחי' בהמה (דאדם<sup data-n=\"1615\">31</sup> גי' מ\"ה ובהמה<sup data-n=\"1616\">32</sup> גי' ב\"ן, ומ\"ה מברר לב\"ן כידוע<sup data-n=\"1617\">33</sup> שבחכ' אתברירו, אך מבחי' אד\"ם העליון א\"א להשפיל האור כ\"כ לברר בירורי נוגה מן הבהמה והבקר כו' רק ע\"י אמצעות נשמות ישראל שנק' אדם תתאה כו'. וזהו אדם כי יקריב לנשמות קרבן להוי' תחלה אז תוכלו להקריב קרבנכם מן הבהמה כו' וד\"ל).\n<b>וזהו</b> ויקרא אלף זעיר\"א, כי בחי' אלף רבת\"א הוא אאלפך<sup data-n=\"1618\">34</sup> בחי' מקור החכ' בבחי' חכ' שבכתר שנק' אדם הגדול בחי' א\"א, ושם א' חכמת<sup data-n=\"1619\">35</sup> אדם כו', ובחי' אלף רבתא זה הוא בא'<sup data-n=\"1620\">36</sup> דאד\"ם שבד\"ה, שמדבר באדה\"ר קודם החטא, שהוא בחי' אד\"ם קדמאה האדם הגדול בענקים כו', ואמנם בשביל העלאת והקרבת נשמות דאדם תתאה אנפי זוטרי הוקטן א' רבתא זה ונתצמצם ונעשה א' זעירא והוא א' דאדם בתראה בחי' ז\"א שהוא שם מ\"ה במלוי אלפי\"ן ג\"כ, אבל הוא בחי' ז\"א וכמ\"ש מ\"ה<sup data-n=\"1621\">37</sup> שמו מ\"ה שם בנו כו' וד\"ל.\n<b>וזהו</b> ויקרא אל משה, קריאה זו הוא בחי' המשכה והתכללות, דהנה בסוף פ' פקודי א' ולא<sup data-n=\"1622\">38</sup> יכול משה לבא כו' כשכבוד ה' מלא את המשכן, והיינו",[["1613","29","<b>ואת הקדוש והקריב אליו</b>: קרח טז, ה."],["1614","30","<b>ובהמה</b>: כ\"ה בכת\"י המעתיק."],["1615","31","<b>דאדם גי' מ\"ה</b>: ראה ע\"ח שער התיקון פ\"ג. ועוד. פרדס שער ערכי הכינויים בערכו. ובכ\"מ."],["1616","32","<b>ובהמה גי' ב\"ן</b>: ראה ס' הליקוטים להאריז\"ל שמיני יא, ב. שער המצות וטהעמ\"צ להאריז\"ל ר\"פ שמיני לקו\"ת להאריז\"ל תהלים סל\"ו. ועוד. [וראה בהמ\"מ בלקו\"ת ויקרא ג, ב. ובס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' ד]."],["1617","33","<b>כידוע שבחכ' אתברירו</b>: ראה זח\"ב רנד, ב. תניא אגה\"ק סכ\"ח (קמח, א). ובכ\"מ."],["1618","34","<b>אאלפך</b>: איוב לג, לג."],["1619","35","<b>חכמת אדם</b>: קהלת ח, א."],["1620","36","<b>בא' דאדם שבד\"ה</b>: דברי הימים א בתחילתו."],["1621","37","<b>מ\"ה שמו מ\"ה שם בנו</b>: משלי ל, ד."],["1622","38","<b>ולא יכול משה</b>: פקודי מ, לה."]]],[2101920290,"הענן שנק'<sup data-n=\"1623\">39</sup> ענן ה' שבו שורה בחי' א\"ס שבכתר ששורה על הכפרת שבארון כו', והי' נשמת משה מתבטל במציאות בבואו אל תוך הענן הזה, והוצרך הענן הזה לצמצם א\"ע כדי שיוכל ליכנס ולשמוע הקול שמדבר אליו מבין ב' הכרובים כו', אנפי<sup data-n=\"1624\">40</sup> זוטרי דכר ונוק' דאצי' כו', והענין הוא כמו וקרא<sup data-n=\"1625\">41</sup> זא\"ז שמקבלי' דין מן דין כו', להיות כי גם כל א' אומר ג\"פ קדוש אע\"פ שמיכאל בחי' חסד או' בחי' קדוש שאו' גבריאל כו' מפני שמתכללים זע\"ז ויש בכל א' ממדריגת חבירו לכך כל א' אומר ג\"פ קדוש כו', וזהו מפני שקרא זא\"ז שממשיך כל א' ממדריגתו לחבירו וכל א' מקבל מזולתו ומ\"ש ומקבלי' דין מן דין היינו לקבל המשכת זולתו בו, ולפי התרגום [פי'] וקרא זה כמו הקורא בשם חבירו שקוראו וממשיכו אליו כך כל א' קורא וממשיך מדריגת חבירו אליו כו' וד\"ל. וכך גם כאן ויקרא אל משה שקוראו וממשיכו אליו להיות כי א' זעירא הוא בחי' שם מ\"ה דז\"א בבחי' קטנות והמשיך וקרא למשה ששרשו בבחי' ח\"ע כמ\"ש מה<sup data-n=\"1626\">42</sup> שמו אותיות משה, ומשה הקים<sup data-n=\"1627\">43</sup> הארת שם מ\"ה שבמדות דז\"א ונתכללו זע\"ז ואז וידבר אליו מבין הכרובים כו' מפני שנתצמצם הענן והי' יכול משה לבא לשם ובלתי קריאה והמשכה זאת לא הי' יכול משה לבא אל הענן כו' וד\"ל.",[["1623","39","<b>שנק' ענן ה'</b>: שם לח."],["1624","40","<b>אנפי זוטרי</b>: ע\"פ חגיגה יג, ב. וראה תו\"א תרומה פא, א. לקו\"ת צו י, ב. ובכ\"מ."],["1625","41","<b>וקרא זא\"ז שמקבלין דין מן דין</b>: ישעי' ו, ג ותרגום יונתן שם. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' טז."],["1626","42","<b>מה שמו אותיות משה</b>: ראה שער הפסוקים להאריז\"ל יתרו כ, ה. סידור עם דא\"ח קי, א. תו\"ח בראשית יד, ב. ובכ\"מ."],["1627","43","<b>הקים</b>: כ\"ה בכת\"י המעתיק, ואוצ\"ל: קיבל."]]],[2101920291,"<h3>אדם כי יקריב</h3>\n<b>אדם</b><sup data-n=\"1628\">1</sup> כי<sup data-n=\"1629\">2</sup> יקריב מכם קרבן לה' מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם. ולפי פשוטו מקרא זה אין לו הבנה דלאו רישי' סיפי' דתחלת דבריו הוא בלשון נסתר באומרו אדם כי יקריב ואינו אומר תקריב דמשמע כמדבר לנכח אלא יקריב המקריב, ואח\"כ סיום דבריו תקריבו את קרבנכם היינו לנוכח שאתם תקריבו. גם מלת מכם אינו מובן לכאורה. אך הענין כי פי' אדם כי יקריב היינו אותו אדם הידוע והוא מה שנאמר ועל<sup data-n=\"1630\">3</sup> הכסא דמות כמראה אדם מלמעלה הוא מראה<sup data-n=\"1631\">4</sup> דמות כבוד הוי', שאותו אדם פעמים יקריב מכם קרבן כו'. והענין כי",[["1628","1","<b>אדם כי יקריב</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. מאמר זה הוא נו\"א מד\"ה זה הנדפס לעיל וע\"ש בהמ\"מ. ונמצא ג\"כ בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תקה."],["1629","2","<b>אדם כי יקריב מכם קרבן לה'</b>: ויקרא א, ב. וראה גם סה\"מ קונטרסים ח\"ב תנ, א. סה\"מ אידיש ע' 141. סה\"מ מלוקט ח\"א ע' יט. וש\"נ."],["1630","3","<b>ועל הכסא דמות כמראה אדם</b>: ע\"פ יחזקאל א, כו."],["1631","4","<b>מראה דמות כבוד ה'</b>: שם, כח."]]],[2101920292,"הנה נודע שבאתערותא<sup data-n=\"1632\">5</sup> דלתתא אתערותא דלעילא, אכן פעמים שאין אתעדל\"ת מלמטה כלל אזי יצוה<sup data-n=\"1633\">6</sup> ה' חסדו באתעדל\"ע מצד עצמו כי<sup data-n=\"1634\">7</sup> חפץ חסד הוא ואזי באתעדל\"ע אתעדל\"ת דהיינו שנתעורר לבות בני אדם לקרבת<sup data-n=\"1635\">8</sup> אלקים יחפצון ולא מצד עצמן כ\"א מהערה שמעוררים מלמעלה כו'.\n<b>אך</b> זאת הוא הנפקותא בין מה שבאתעדל\"ת אתעדל\"ע כראוי, לבין האתעדל\"ת הבאה מאתעדל\"ע בתחלה, שכאשר יש אתעדל\"ת מלמטה מצד עצמן אזי הוא דבר שיכול להתקיים לעד ולעולמי עולמים, כי באתעדל\"ת נתעורר בודאי אתעדל\"ע ומאתעדל\"ע זו הבאה מאתעדל\"ת מתעורר עוד שנית ממעלה למטה אתעדל\"ת בטוב ויפה, וחוזר חלילה, משא\"כ בזמן שאין אתעדל\"ת מלמטה רק שמעוררים מלמעלה מצד עצמן שחפץ להטיב עם בריותיו ושיהי' להן אתעדל\"ת להיות בקרבת אלקים יחפצון, אזי אינו דבר המתקיים דהיינו שיהי' פועל ישועות בהם רק על משך זמן מועט שבאותו זמן הוא שיהי' דורשי' ומבקשים את ה' ואח\"כ יחלוף ויעבור רוח טהרה זאת ויחזרו לאיתנם הראשון, אחר שרוח טהרה זאת לא מאתם היתה רק ממה שעוררם מלמעלה לכן יוכל להיו' שאח\"כ תפסוק התעוררות זו וממילא גם יתבטל התעוררות לבותם, כי הרי משורת הדין אינו מהראוי רק שיהי' אתעדל\"ע לעורר אתעדל\"ת רק אחרי קדימת אתעדל\"ת הראשונה תחלה ואזי הוא דבר המתקיים כי כך ראוי שבאתעדל\"ת אתעדל\"ע ובאתעדל\"ע אתעדל\"ת וחוזר חלילה עוד ועוד מלמטה למעלה וממעלה למטה ויתקיים כן בל תמוט לעולם, משא\"כ מה שמתעורר אתעדל\"ע מצד עצמו גם בלא אתעדל\"ת ושבאתעדל\"ע זו אתעדל\"ת נהפוך הוא מסדר ההנהגה התמידי', ולפנים משה\"ד הוא ולאו<sup data-n=\"1636\">9</sup> בכל עידנא מתרחיש ניסא כ\"א על משך זמן מועט בלבד כשממתינים כמה וכמה למעלה על אתעדל\"ת, והנה אין דורש ואין מבקש מלמטה ואדם אין העובד ה' כו' אזי יצוה חסדו ויעורר מלמעלה, אבל דבר זה וטובה גדולה זו אין לה קיום רק על זמן מועט כנ\"ל מטעם הנ\"ל. וזהו הסיבה שמתאוננים העם על היות בהם רוח טהרה והתעוררו' לעבודת ה' רק על כמה שבועות ואח\"כ פוסקת לגמרי כאילו להד\"מ הגם שבאותו הזמן מועט הי' לבו בוער בשלהבת עזה כו', והסיבה לזה הוא לפי שהתעוררו' זו הית' מלמעלה בלבד אבל מצד עצמן שלימים הם בגופם לכן אחר הפסקת כח האתעדל\"ע נשאר שקוע בגופו רוח<sup data-n=\"1637\">10</sup> הבהמה היורדת למטה כאבן דומם בלי הזזה כ\"ש למעלה.\n<b>וזהו</b> כונת הכתוב אדם כי יקריב מכם כו', כי הנה הוא ית' אין לו גוף ולא דמות הגוף וכמ\"ש כי<sup data-n=\"1638\">11</sup> לא אדם הוא והיינו א\"ס ב\"ה כמו שהוא בעצמותו פשוט",[["1632","5","<b>שבאתערותא דלתתא אתערותא דלעילא</b>: זח\"א פח, א. קסד, א. רלה, א. רמד, א. ועוד."],["1633","6","<b>יצוה ה' חסדו</b>: ע\"פ תהלים מב, ט."],["1634","7","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["1635","8","<b>לקרבת אלקים יחפצון</b>: ע\"פ ישעי' נח, ב."],["1636","9","<b>ולאו בכל עידנא מתרחיש ניסא</b>: ע\"פ פסחים נ, ב. מגילה ז, ב. זח\"א קיא, ב."],["1637","10","<b>רוח הבהמה היורדת למטה</b>: ע\"פ קהלת ג, כא."],["1638","11","<b>כי לא אדם הוא</b>: שמואל א טו, כט."]]],[2101920293,"בתכלי' הפשיטות למעלה מעלה מהתלבשות בכלים ולית<sup data-n=\"1639\">12</sup> מחשבה תפיסא בי' כלל, אכן כשיורד להיות מאיר לנשמות הצדיקים אזי מתלבשת בדמות אדם כביכול, וז\"ס מ\"ש במרכבת יחזקאל ועל הכסא דמות כמראה אדם עליו מלמעלה הוא מראה דמות כבוד הוי', והיינו כי בכדי שיוכלו הנשמו' שהם בע\"ג להיות תופסים אורו ית' שלזאת צריך להתצמצם בבחי' גבולים והוא ענין אדם רמ\"ח איברים רמ\"ח כלים כו', ועל אדם זה הוא שאומר אדם כי יקריב כו', כי הוא לשון אקראי, כלומר שלאו בכל עידנא מתרחש כן אלא לעתים יארע שאותו אדם יקריב מכם קרבן לה', דהיינו כאשר לא ימצא אתעדל\"ת מלמטה אזי יצוה חסדו ויעורר באתעדל\"ע אתעדל\"ת וזהו כי יקריב מכם קרבן לה' שיקריב לבותיכם להוי', ולכן אמר מלת מכם אחר אומרו כי יקריב ולא אמר כפשוטו אדם מכם כי יקריב, לפי שאין הכונה שאדם מבנ\"י יקריב אלא שאדם העליון יקריב מכם כלומר מבנ\"י כו', ואח\"כ אומר מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם תקריבו אתם בנ\"י שגם המה קרוים אדם.\n<b>וזאת</b> הוא עצה טובה היעוצה ממנו ית' אל משה שידבר ככה לישראל, שמיד בשעה טובה זו שיארע לפעמים שיקריב אותו אדם העליון קרבן מכם להוי', אזי תיכף ומיד תקריבו אתם את קרבנכם מן הבהמה כו', כלומר שלא יהי' לכם בטחון על האתעדל\"ע זו בלבד המעוררת אתעדל\"ת בכם ומקרבת נשמותיכם להוי', ותאמרו מעתה מה לנו לעשות עוד כי גם כי נחשה בעצמינו הלא ה'<sup data-n=\"1640\">13</sup> לי בעוזרי מלמעלה והוא מעורר אהבתי אליו ית', לזה אומר אל תאמר כן אלא אדרבה מיד תקריבו אתם כו', כי הלא מה שמעוררים מלמעלה הוא דבר שאין לו קיום רק על זמן מועט כנ\"ל מאחר שכ\"ז הוא לפנים משה\"ד ולאו בכל עידנא מתרחיש ניסא, וא\"כ כאשר יהי' הם נרפים בעצמם רק שיקבלו מה שנותנים מלמעלה בלבד אזי אח\"כ בכלות כח הערה זו שמלמעלה ישארו על איתנם הראשון שקועים בגויתם החומרית היורדת למטה משתוקקת לתאות העוה\"ז ושוב יהי' קשה להוציאו מתאות העוה\"ז ולצאת מגדרי הגוף ע\"י התחלתן בלבד בלי עזר תחלה מלמעלה, אבל כאשר מיד כאשר אותו האדם יקריב מכם קרבן להוי' דהיינו כשיהי' אתעדל\"ע לעורר אתעדל\"ת אזי תומ\"י תתחילו גם אתם להקריב את קרבנכם מן הבהמה כו' כלומר שאתם ג\"כ תתחילו להיות כופה גופותיכם כמ\"ש<sup data-n=\"1641\">14</sup> בזהר אתכפי' ממרירו כו' אזי יהי' דבר המתקיים לעד כי באתעדל\"ת אתעדל\"ע וחוזר חלילה כנ\"ל.\n<b>והנה</b> בכ\"ז יובן ג\"כ מ\"ש באדם כי יקריב ל' מכם וכאן בתקריבו אתם נאמר מן הבהמה מן הבקר כו', כי הנה מה שהוא ית' מעורר לבות בני אדם לקרבת אלקים אינו אלא הנפש אלקית שבהם בלבד שהיא חלק<sup data-n=\"1642\">15</sup> אלוה ממעל וע\"י גילוי",[["1639","12","<b>ולית מחשבה תפיסא בי' כלל</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["1640","13","<b>ה' לי בעוזרי</b>: תהלים קיח, ז."],["1641","14","<b>כמ\"ש בזהר אתכפי' ממרירו</b>: ראה זח\"א ד, א."],["1642","15","<b>חלק אלוה ממעל</b>: ראה תניא רפ\"ב."]]],[2101920294,"הארה מלמעלה מתעוררות ליכלל באורו ית' כנר המתכללת באבוקה המתקרבת אליה יען היותה מקורה אבל לנפשות הבהמיות שבהם ולגופם החומרי אין זה שייכות כלל כלומר שאעפ\"כ הם ישארו נצבים על מעמדם, ועם היות כי רוח אלקים שהיא הנק' רוח האדם<sup data-n=\"1643\">16</sup> כי<sup data-n=\"1644\">17</sup> אתם דוקא קרוים אדם היא העולה למעלה להתכלל באורו ית', עכ\"ז רוח הבהמה היא הנפש הבהמית היורדת למטה וכן הגוף ואינן מתפעלים ומשתנים כלל מהתעוררות זו שלמעלה, ובפירוש ארז\"ל במלאך<sup data-n=\"1645\">18</sup> הממונה על ההריון ששואל מלפני הקב\"ה טפה זו מה תהא עליה כו' ואילו צדיק או רשע לא קאמר, כי כך מסר הבורא ית' הבחירה להיות ביד האדם להרע או להטיב מצד נפשו הבהמית וגופו החומרי, ולכן הנפש הבהמי' והגוף אינן מתפעלי' מהערה זו שמעוררים מלמעלה רק הנפש אלקי' שבתוכם בלבד היא העולה למעלה ע\"י אתעדל\"ע שמלמעלה ולהתכלל כנר בפני האבוקה.\n<b>(ואפשר</b><sup data-n=\"1646\">19</sup> לתרץ עפי\"ז קושית הרמב\"ם בפ\"ו מהל' תשובה באמרו פסוקים הרבה יש בתורה שנראין כסותרי' עיקר זה (כלומר מ\"ש שהבחירה היא חפשית ביד האדם) ויעלה מהם על הדעת שהקב\"ה הוא גוזר על האדם לעשות רעה או טובה ושאין לבו של אדם מסור לו להטותו כו', ותירוצו דחוק ע\"ש, ולפי הנ\"ל א\"ש כי בודאי אמת שהקב\"ה יוכל להטות את האדם לטוב אם ירצה וכמ\"ש ורוח<sup data-n=\"1647\">20</sup> נדיבה תסמכני וכנ\"ל שבאתעדל\"ע אתעדל\"ת וכמאמר והחזירנו<sup data-n=\"1648\">21</sup> בתשובה כו', אלא שאין זה רק לנפש אלקי' שבו בלבד שאותה הוא שמעורר ועדיין אין זה פעולה שלימה כי מ\"מ הנפש הבהמית והגוף מעכבי' והמה מסורים ביד האדם ולא נתן הבורא ית' שיהי' מתפעלי' מהערה עליונה, וא\"כ הקב\"ה הוא רק עוזר בלבד להאדם שכשבא<sup data-n=\"1649\">22</sup> לטהר מסייעין לו אבל לא שיטהו מהרע לטוב לגמרי כי הגוף ביד האדם מסור וד\"ל. ובזה יתכן דשני המאמרי' והחזירנו בתשובה כו' וכן עד<sup data-n=\"1650\">23</sup> יערה עליהם רוחו ממרום כו' ופסוקי' כהנה רבות עם מארז\"ל אילו צדיק ורשע לא קאמר, שניהם עולים בקנה א' ולא סתרי אהדדי וד\"ל).\n<b>וז\"ש</b> כי יקריב מכם כלומר ל' מכם היינו מקצת ממה שבכם ולא כל עצמיכם דהיינו הנפש אלקי' בלבד יקריב להוי' מתוך הנפש הבהמי' והגוף המלבישות אותה אבל הן נשארי' על עמדן, אבל אתם תקריבו את קרבנכם מן הבהמה מן הבקר כו' להיות בבחי' אתכפי' להפך הגוף והנפש הבהמית לעבודתו ית\"ש, והנה מאתכפיא יבא אח\"כ לבחי' אתהפכא ואזי הוא דבר המתקיים כנ\"ל.",[["1643","16","<b>רוח האדם . . היא העולה למעלה</b>: קהלת שם."],["1644","17","<b>כי אתם דוקא קרוים אדם</b>: יבמות סא, א."],["1645","18","<b>במלאך הממונה על ההריון</b>: נדה טז, ב."],["1646","19","<b>ואפשר לתרץ עפי\"ז קושית הרמב\"ם</b>: ראה גם שמונה פרקים להרמב\"ם פ\"ח. לקו\"ש חכ\"ז ע' 153. ובכ\"מ."],["1647","20","<b>ורוח נדיבה תסמכני</b>: תהלים נא, יד."],["1648","21","<b>והחזירנו בתשובה</b>: נוסח תפילת שמו\"ע."],["1649","22","<b>שכשבא לטהר מסייעין לו</b>: שבת קד, א."],["1650","23","<b>עד יערה עליהם רוחו ממרום</b>: ע\"פ ישעי' לב, טו."]]],[2101920295,"<b>ופי'</b><sup data-n=\"1651\">24</sup> מ\"ש מן הבהמה מן הבקר ומן הצאן, ג' אלה שמנה הם ג' מדרגות חלוקות שיש בנפש הבהמית שבישראל, יש מי שהוא מבחי' בקר כי<sup data-n=\"1652\">25</sup> שור נגח הוא בחי' גבורות קשות והיינו מי שהוא כעסן בטבעו שמדה רעה זו היא בו בתגבורת יותר ויכונה בשם בקר ע\"ש הרתחנות כו', ויש מי שאינו רתחן בטבעו וחלק הרע שבו הוא היותו בעל תאוה והוא שנפשו הבהמי' היא מבחי' צאן שאינן נגחני' אדרבה קולם ברחמנות אלא שהם בעלי תאות כו', והנה כל אלה צריך לאכפיא וז\"ש מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם כל א' לפי מה דידע בנפשי' מהותו וטבעו כך יראה לאכפי' מדה זו באותו שעה שהאדם עליון יקריב מכם קרבן את הנפש אלקי' שבתוכם הוא מלמעלה ואתה מלמטה את הנפש הבהמית והגוף ואזי יהי' דבר המתקיים כנ\"ל.",[["1651","24","<b>ופי' מ\"ש מן הבהמה מן הבקר ומן הצאן</b>: ראה גם קונטרס התפילה פ\"ח."],["1652","25","<b>כי שור נגח הוא</b>: משפטים כא, לו."]]],[2101920296,"<h3>סוד ויקרא אל משה</h3>\n<b>סוד</b><sup data-n=\"1653\">1</sup> ויקרא<sup data-n=\"1654\">2</sup> אל משה באלף זעירא. כי הנה מה כתי' לעיל מיני' ולא<sup data-n=\"1655\">3</sup> יכול משה לבא אל המשכן כי שכן עליו הענן לכן עתה ויקרא אל משה. והענין כי השראת הענן הוא המשכת והשראת א\"ס ב\"ה ממקום עליון ונורא מאד שנאמ' בו ישת<sup data-n=\"1656\">4</sup> חשך סתרו והוא בחי' כתר עליון ולכן לא יכול משה לבא אל המשכן כי לא הי' ביכולתו לקבל אור מופלא זה, ולכן<sup data-n=\"1657\">5</sup> ויקרא אל משה כלומ' שהשפיע והוריד אליו הארה מאותו האור עליון כדי שעי\"ז יוכל להתקרב אח\"כ ולבא אל המשכן, כי ויקרא הוא מלשון וקרא<sup data-n=\"1658\">6</sup> זא\"ז ואמר קק\"ק ותרגומו ומקבלין דין מן דין שתרגם מלת קריאה בלשון קבלה שהוא ענין המשכה והשפעה שמקבלי' זמ\"ז, והדין עמו כי לפי פשוטו שהקריאה היינו שקוראי' זה לזה אין לדבר הבנה כלל למה מצטרך מיכאל לקרוא את גבריאל בשעה שיאמר קדוש וכן גבריאל למיכאל. אלא הענין כי פי' קריאה זו לשון קבלה היא שמקבלי' השפעה זה מזה כדי שיוכלו לומר ג\"פ קדוש, שהרי כל א' מצד עצמו לא הי' אומר רק פ\"א קדוש באיזו בחי' באשר הוא",[["1653","1","<b>סוד ויקרא אל משה</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. ונמצא בשינויים בלקו\"ת ויקרא א, א. תוכן המאמר נמצא גם בשינויים לעיל בד\"ה אדם כי יקריב (הראשון), וע\"ש בהמ\"מ. המאמר נמצא ג\"כ בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תקה."],["1654","2","<b>ויקרא אל משה באלף זעירא</b>: ראה זח\"א רלט, א. זח\"ג נג, ב. אוה\"ת ויקרא ע' תשכד."],["1655","3","<b>ולא יכול משה לבא אל המשכן</b>: ע\"פ פקודי מ, לה."],["1656","4","<b>ישת חשך סתרו</b>: תהלים יח, יב. וראה זח\"ג רכה, א. אוה\"ת ויקרא ע' ריז."],["1657","5","<b>ולכן ויקרא אל משה כלומ' שהשפיע</b>: ראה גם ס' עשרה מאמרות מאמר אם כל חי י\"ב סל\"ו (קצד, ב)."],["1658","6","<b>וקרא זא\"ז ואמר קק\"ק</b>: ישעי' ו, ג ותרגום יונתן שם."]]],[2101920297,"שם באיכו' כלות נפשו, ושיאמר ג\"פ קדוש שהוא ג' בחי' כלות הנפש מחולקות היינו לפי שמקבל השפעה עוד מב' מלאכים זולתו, כי כללות כל המלאכים שלש המה מיכאל גבריאל רפאל וכל א' אומר קדוש מצד עצמו באיזו בחי' שהוא, וכדי שכל א' יאמר ג\"פ הוא קורא ומקבל משנים זולתו מיכאל מגבריאל ורפאל, גבריאל ממיכאל ורפאל כו', וכמ\"כ פי' וענין ויקרא אל משה שהשפיע לו מהארתו ית' כדי שעי\"ז יהי' בו כח עוז לבא אל המשכן.\n<b>ולכן</b> ויקרא הוא באלף זעירא, כי סוד<sup data-n=\"1659\">7</sup> האלף הוא בכתר מלשון אאלפך<sup data-n=\"1660\">8</sup> חכמה כלומר שהוא מקור החכמה שממנו תמצא החכמה, אך יש<sup data-n=\"1661\">9</sup> א' מאתוון רברבן וא' מאתוון זעירין, א' שבאתוון רברבין היינו בחי' הכתר כמו שהוא במהותו ועצמותו ושמה לא יכול משה לבא, וא' מאתוון זעירין היינו הארת הכתר כמו שנמשך למטה ע\"י צמצום ומבחי' זו הוא שויקרא אל משה ונמשך לו הארה כדי שיוכל לבא כו'. ובד\"ה<sup data-n=\"1662\">10</sup> נאמר אדם באלף מאתוון רברבין והוא בחי'<sup data-n=\"1663\">11</sup> אדה\"ר כמו שהי' לפני החטא שהי' במדרגה גבוה מאד נעלה כידוע לי\"ח.\n[הגהות מכ\"ק אדמו\"ר הצ\"צ]\nויקרא<sup data-n=\"1664\">1</sup> זהר ח\"א ק\"ב סע\"ב קל\"ח א' קע\"ג ב', ח\"ב קל\"ח א' קנ\"ז א' ח\"ג נ\"ג ב' וע\"ש דרוש על א' זעירא י\"ל כענין אזוב ע\"ש א' אאלפך זהו שכינה ע\"י הענן כו' אך זעירא ע\"י דבריאה כו'.\n<b>עיין</b> זהר בלק דף ריש ע\"ב, ואתחנן דף רס\"ד ב' ונז' מענין ההוא בתרומה קל\"ט ב' ועמק\"מ שם, וילך דרפ\"ה א' משמע ויקרא מלמטלמ\"ע אח\"כ וידבר מלמעלמ\"ט וכענין שאמר משה כי<sup data-n=\"1665\">2</sup> ש' אקרא וכו', ע' זהר הרקיע דכ\"ח ב' מענין קורא לקול וכו'.\n<b>בזוהר</b><sup data-n=\"1666\">3</sup> ויקרא אוקיר, זהב יקר מכסף לפי שאינו מצוי ודבר<sup data-n=\"1667\">4</sup> ה' הי' יקר וכו' לפי",[["1659","7","<b>סוד האלף הוא בכתר</b>: ראה תקו\"ז תמ\"ט. פרדס שער האותיות (שכ\"ז) פ\"ד. ע\"ח שער טנת\"א (ש\"ה) פ\"ז. אמת ליעקב מע' א' סרס\"א. ובכ\"מ."],["1660","8","<b>אאלפך חכמה</b>: איוב לג, לג."],["1661","9","<b>יש א' מאתוון רברבן וא' מאתוון זעירין</b>: ראה זח\"א ג, ב."],["1662","10","<b>ובד\"ה נאמר אדם</b>: דברי הימים א בתחילתו. וראה מנחת שי שם."],["1663","11","<b>בחי' אדה\"ר כמו שהי' לפני החטא</b>: בלקו\"ת שם מציין לס' הגלגולים פי\"ט."],["1664","1","<b>ויקרא</b>: הגהות אלו, נרשמו בגוכי\"ק הצ\"צ בס' תקע\"ב [1116] בצידי הגליון של המאמר."],["1665","2","<b>כי ש' אקרא</b>: ע\"פ האזינו לב, ג."],["1666","3","<b>בזוהר ויקרא אוקיר</b>: זח\"ג ג, א: אוקיר אנוש מפז ואדם מכתם אופיר (ישעי' יג, יב), זכאה חולקי' דמשה דחזי כל דא, אבל צרופא דא לא אתחמי לעינוי דמשה אלא צרופא קדמאה דאיהו ויקרא דא הוה חמי משה."],["1667","4","<b>ודבר ה' הי' יקר</b>: שמואל א ג, א."]]],[2101920298,"שאין חזון וכו' ועיקר היוקר אתה<sup data-n=\"1668\">5</sup> הוא לבדך כי הוא לבדו הקדמון ונצחי וזולת זה הכל מחודש כו' והוא<sup data-n=\"1669\">6</sup> לבדו שבכחו לברוא יש מאין כו' א\"כ פי' אוקיר אנוש שממשיך בו מבחי' לבדך ע\"ד בדד<sup data-n=\"1670\">7</sup> ינחנו וכמ\"ש<sup data-n=\"1671\">8</sup> בענין בגדי בד, ויקר<sup data-n=\"1672\">9</sup> מפז כי כסף וזהב חו\"ג דע\"י והתורה שרשה מדע' עתיק כו' י\"ל כסף מ\"ע זהב ל\"ת ותורה<sup data-n=\"1673\">10</sup> עצמ' משל הקדמוני לבדך כו' וזהו א' דאוקיר לפמ\"ש במב\"ש ש\"ג ח\"ב פד\"ה א' ב' יודין אוירא ומו\"ס וקרומא כו' זהו גבוה מפז מו\"ס כו'.\n<b>בענין</b> וקרא להעיר מפסוק תהום<sup data-n=\"1674\">11</sup> אל תהום קורא וכו' ע' בזהר בראשי' דנ\"א ובזהר הרקיע שם אריכות גדול בזה וע' בפרדס שער הצנורו'.\nמענין וידבר אליו מאהל כו' זהר ח\"ב קל\"ט ב' ע\"ש במק\"מ.\n<b>א'</b><sup data-n=\"1675\">12</sup> עי' בת\"א יתרו בביאור דזכור מענין א' וע\"ש<sup data-n=\"1676\">13</sup> מענין לאלפים דנוצר חסד כו' ועמ\"ש<sup data-n=\"1677\">14</sup> על הזהר ויחי דרל\"ט מענין א' זעירא ועמ\"ש בביאור<sup data-n=\"1678\">15</sup> דשתי הלחם מענין הבאת שלום בין אדם לחבירו ובביאור<sup data-n=\"1679\">16</sup> לויתן, ואדם<sup data-n=\"1680\">17</sup> א' מאלף זה משה כו', וצ\"ע להעיר מהזהר<sup data-n=\"1681\">18</sup> שלח מאן דאיהו זעיר איהו רב.",[["1668","5","<b>אתה הוא לבדך</b>: ע\"פ נחמי' ט, ו. ועוד."],["1669","6","<b>והוא לבדו שבכחו לברוא יש מאין</b>: ראה תניא אגה\"ק ס\"כ (קל, סע\"א ואילך)."],["1670","7","<b>בדד ינחנו</b>: האזינו לב, יב."],["1671","8","<b>וכמ\"ש בענין בגדי בד</b>: ראה לקו\"ת אחרי כח, ג. ובמ\"מ שם."],["1672","9","<b>ויקר מפז</b>: ראה רמ\"ז לזהר ר\"פ קרח."],["1673","10","<b>ותורה עצמ' משל הקדמוני</b>: ע\"פ שמואל א כד, יג ופירש\"י שם. פירש\"י משפטים כא, יג. מכות י, ב (ד\"ה והאלקים)."],["1674","11","<b>תהום אל תהום קורא</b>: תהלים מב, ח."],["1675","12","<b>א' </b> [ בענין אות אל\"ף]<b> עי' בת\"א יתרו בביאור דזכור</b>: דף עב, ד."],["1676","13","<b>וע\"ש מענין לאלפים דנוצר חסד</b>: תשא לד, ז. תו\"א שם סט, ג."],["1677","14","<b>ועמ\"ש על הזהר ויחי דרל\"ט מענין א' זעירא</b>: סה\"מ תקס\"ח ח\"ב ע' תרסח וע' תרעז. ובביאוה\"ז להצ\"צ ח\"א ע' קעז."],["1678","15","<b>בביאור דשתי הלחם</b>: ראה לקו\"ת אמור לה, א."],["1679","16","<b>ובביאור לויתן</b>: ראה לקו\"ת שמיני יח, ד ואילך. אוה\"ת ויקרא כרך ב ע' תפה ואילך."],["1680","17","<b>ואדם א' מאלף זה משה</b>: קהלת ז, כח. ויק\"ר רפ\"ב."],["1681","18","<b>מהזהר שלח</b>: קסח, א."]]],[2101920299,"<h3>ביום ההוא יגלח</h3>\n<b>ביום</b><sup data-n=\"1682\">1</sup> ההוא<sup data-n=\"1683\">2</sup> יגלח אדנ' בתער השכירה כו' במלך אשור את הראש ושער הרגלים וגם את הזקן תספה. הנה ידוע מארז\"ל (בסנהדרין<sup data-n=\"1684\">3</sup> בפ' חלק) דאתא קוב\"ה וגזי' לרישי' ודיקני' כו' עד והיינו דכתי' וגם את הזקן תספה. ולהבין כ\"ז הנה באמת זהו דבר פלא מה שהוצרך הקב\"ה לגלח שער ראש מלך אשור וגם את הזקן כו' אשר לא עשה כן לכל שר משרי אוה\"ע כי גם פרעה מלך מצרים שהכביד עולו על ישראל ומרד בה' ואמר מי<sup data-n=\"1685\">4</sup> ה' אשר אשמע בקולו כו' הנה הכהו ה' בי' מכות והאביד כל חילו בים סוף, אבל לא עשה דבר זה לגלח ראשו וזקנו כו'. אך הנה סנחרב מלך אשור הי' מורד באלקים חיים יותר מכל שאר אומה\"ע, כי כל אוה\"ע יודעים את רבונם שהרי קרו<sup data-n=\"1686\">5</sup> לי' אלקא דאלקי', דהיינו שמודים בבחי' אחדות פשוטה שהוא קדמון כו' רק שהשגחתו סילק מן הארץ באמרם עזב ה' את הארץ להיות מתנהג הכל ע\"פ וכוכבים ומזלות המושלים בדרכי הטבע האנושי' כו'. אשר לזאת נושאים את נפשם לעבוד לכו\"מ ולכל צבא השמים, כדי לקבל שפע וחיות על ידם כידוע, אבל אעפי\"כ כולם מודים שהוא ית' אלקא דאלקי' כו', וכמ\"ש מי<sup data-n=\"1687\">6</sup> לא יראך מלך הגוים, וכן כתי' ושמי<sup data-n=\"1688\">7</sup> נורא בגוים, וכן הללו<sup data-n=\"1689\">8</sup> את ה' כל גוים כו', מלך<sup data-n=\"1690\">9</sup> אלקי' על גוים, וכה\"ג רבות בכתובים, וגם פרעה לא אמר רק מי ה' אשר אשמע כו', שם הוי' דוקא הוא שלא הכיר והשיג אבל שם אלקי' ידע והכיר, וכמ\"ש מלך אלקי' על גוים כו', והיינו דקרו לי' אלקא דאלקי' כו' וד\"ל. אך סנחרב מלך אשור הוא אשר מרד יותר ברום לבבו באמרו אני<sup data-n=\"1691\">10</sup> ברוב רכבי עליתי מרום הרים כו', ע\"כ אמר מי<sup data-n=\"1692\">11</sup> בכל אלקי הארצות אשר הצילו כו', שהשווה אלקי' חיים לכל אלקי הארצות עץ ואבן כו' שזהו חירוף וגידוף ביותר להכחיש באלקי' חיים שאינו אלקא דאלקיא כו', ובחי' קליפה קשה כזו עדיין לא הייתה בכל מלכי ושרי אוה\"ע כמו סנחרב כו', אשר ע\"כ לא הי' לזה תיקון רק שלא יהי' לו יניקה ושרש למעלה, להיותו בבחי' פירוד גמור כ\"כ. וזהו דוקא ע\"י הגילוח שגילחו שם אדנ' גם את הזקן כו', כידוע<sup data-n=\"1693\">12</sup> דסט\"א נק' מלך זקן וכסיל כו' וד\"ל.\n<b>אך</b> להבין זה יש להקדים תחילה בשרש ענין ובחי' השערות למעלה בסט' דקדושה. דהנה מצינו בכתובים שיש ג' מדריגות בבחי' השערות בסט'",[["1682","1","<b>ביום ההוא</b>: מאמר זה הוא הנחת כ\"ק אדהאמ\"צ משנת תקע\"ב, וראה להלן נוסח שני של המאמר (רשימת כ\"ק אדמו\"ר הצ\"צ). ונמצא ג\"כ בס' מאמרי אדה\"ז נביאים ע' מז. וראה ד\"ה זה בשינויים והגהות באוה\"ת נ\"ך ח\"ב ע' תשסז (שם מיוסד ותוס' הגהות מאדמו\"ר הצ\"צ על נוסח המאמר הנחת כ\"ק אדהאמ\"צ כאן)."],["1683","2","<b>ביום ההוא יגלח</b>: ישעי' ז, כ."],["1684","3","<b>בסנהדרין בפ' חלק</b>: צה, ב."],["1685","4","<b>מי ה' אשר אשמע בקולו</b>: שמות ה, ב."],["1686","5","<b>קרו לי' אלקא דאלקי'</b>: סוף מנחות."],["1687","6","<b>מי לא יראך</b>: ירמי' י, ז."],["1688","7","<b>ושמי נורא בגוים</b>: מלאכי א, יד."],["1689","8","<b>הללו את ה' כל גוים</b>: תהלים קיז, א."],["1690","9","<b>מלך אלקי' על גוים</b>: שם מז, ט."],["1691","10","<b>אני ברוב רכבי עליתי מרום הרים</b>: ע\"פ מלכים ב יט, כג. ישעי' לז, כד."],["1692","11","<b>מי בכל אלקי הארצות אשר הצילו</b>: מלכים ב יח, לה. ישעי' לו, כ."],["1693","12","<b>כידוע דסט\"א נק' מלך זקן וכסיל כו'</b>: קה\"ר ד, ג. זח\"א קעט, א. ובכ\"מ."]]],[2101920300,"דקדושה האלקית, והוא הא' מ\"ש בבחי' ע\"י ושער<sup data-n=\"1694\">13</sup> רישא כעמר נקי, בחי' שערות לבנות דוקא כשערות הזקן שהן לבנות כו', והב' מ\"ש קווצותיו<sup data-n=\"1695\">14</sup> תלתלים שחורות כעורב כו', והוא בבחי' שערות הדיקנא דז\"א כו' כמ\"ש באד\"ר, והג' מ\"ש בכנס\"י שהוא בחי' המל' ודלת<sup data-n=\"1696\">15</sup> ראשך כארגמן שהן בחי' שערות אדומות דווקא כמו הארגמן שהוא אדום כידוע.\n<b>ולהבין</b> כ\"ז ילהק\"ת בשרש ענין ובחי' השערות מהו למעלה, להיות ידוע בבחי' עצמיות אוא\"ס ממש שהוא בבחי' אח\"פ בתכלית הפשיטות, ואיך יוכל להיות הסתעפות המשכות אורות עליונים שהן בבחי' השתלשלות עו\"ע שאין ערוך כלל וכלל לגבי' מב' טעמים, הא' מפני שהן בחי' אורות מוגבלים בערך לגבי בחי' אוא\"ס עצמו שהוא בלתי בע\"ג בעצם, ועוד שהן באין בבחי' התחלקות וריבוי כו', ואיך יסתעף בחי' ההתחלקות והריבוי מבחי' אחדות הפשוטה כידוע. אך א\"א להיות ההמשכה מבחי' עצמיות אוא\"ס גם להיות בחי' מקור למקור להשתלשלות אלא ע\"י בחי' צמצום והעלם אור עצמותו תחילה לגמרי, והוא ענין צמצום<sup data-n=\"1697\">16</sup> הראשון הנק' מק\"פ וחלל כו' כמ\"ש בע\"ח, וזהו בחי' הקו\"ח שנמשך אחר צמצום הראשון שנמשל לצורת אות הוי\"ו שקצר ביותר ומצומצם המשכתו, כך בחי' המשכה זו אחר הצמצום הנ\"ל היא מצומצמת ביותר, וכלא ממש חשיבא לגבי אור העצמות ממש, וע\"כ נק' בשם קו\"ח בעלמא, שזהו כדמיון חוט השערה באדם שהיא קצרה ומצומצמת ביותר לפי שהחיות העובר בה הוא בא ונמשך בבחי' צמצום גדול כידוע שהשערות בוקעים ויוצאים מבחי' צומח שבחיות הגוף הצומח בבחי' מותרות בלבד כמ\"ש במ\"א. וכך מבחי' אותיות שבא\"ס עצמו נמשך הקו הזה והוא ע\"י ענין בקיעת יו\"ד דס\"ג שבטה\"ע כמו אז<sup data-n=\"1698\">17</sup> יבקע כשחר אורך כו', כך מה שא' באורך<sup data-n=\"1699\">18</sup> נראה אור, היינו בחי' אור הקו החוט זה הנראה מאורך העצמי, הנה הוא בא דרך בקיעה בעלמא, כדמיון חוט השערה שבוקעת ויוצאת כו' וד\"ל.\n<b>וזהו</b> ענין וי\"ו דקדוש הא' שבחי' קדש עצמו הרי הוא בערך קדושת עצמי' אא\"ס כמ\"ש<sup data-n=\"1700\">19</sup> בזוהר בפי' קדש מלה בגרמי' שהוא מובדל בערך לגמרי בתכלית האחה\"פ כו' כנ\"ל, אך שבוקע הארה בעלמא מעצמות קדושתו, אז נק' קדוש בוי\"ו, והוא בחי' הקו\"ח הנ\"ל, וזהו בחי' מל' דא\"ס שנעשה בחי' כתר לא\"ק כו'. וקדוש הב' הוא בחי' צמצום הב' שמבחי' מל' דא\"ק כשנעשה כתר לע\"י וא\"א כו' כמ\"ש בע\"ח בשער הכללים שגם מבחי' חכ' הקדומה דא\"ק כשצריך להיות המשכה ממנו, להיות בחי' מקור לעולם האצי' שזהו בחי' ע\"י וא\"א בחי' כתר דאצי' גם זה א\"א להיות כ\"א ע\"י צמצום גדול שהוא רק בחי' שערות בלבד ע\"ד הנ\"ל. וקדוש",[["1694","13","<b>ושער רישא כעמר נק'</b>: ע\"פ דניאל ז, ט."],["1695","14","<b>קווצותיו תלתלים</b>: שה\"ש ה, יא."],["1696","15","<b>ודלת ראשך כארגמן</b>: שם ז, ו."],["1697","16","<b>צמצום הראשון הנק' מק\"פ וחלל כו' כמ\"ש בע\"ח</b>: בתחילתו. וראה לקו\"ת ויקרא הוספות נא, ב ואילך. ובכ\"מ."],["1698","17","<b>אז יבקע כשחר אורך</b>: ישעי' נח, ח."],["1699","18","<b>באורך נראה אור</b>: תהלים לו, י."],["1700","19","<b>כמ\"ש בזוהר בפי' קדש מלה בגרמי'</b>: זח\"ג צד, ב."]]],[2101920301,"הג' הוא בחי' צמצום הג' שכאשר צריך להיות המשכה מן המאציל לנאצלי' כמו להאציל אורות דחו\"ב כו' הרי ג\"כ הוא ע\"י בחי' צמצום דבחי' שערות. וזהו מ\"ש בע\"י ושער רישי' כעמר נקא, וכן בחי' דיקנא דע\"י וא\"א שהן בחי' שערות לבנות כו' וכידוע<sup data-n=\"1701\">20</sup> דאור אבא דאצי' מקבל מבחי' מזל ונוצר חסד כו'. ונמצא יש כאן ג' מיני צמצומי' עד שנאצל עולם אצי' בכלל, והן ג' פעמי' קדוש עד שנק' ה' צבאות שהוא בחי' ההמשכה בהתחלקות דחו\"ב ומדות שהן כלולים בשם הוי' יו\"ד חכ' ה\"א בינה כו' וד\"ל.\n<b>והנה</b> כמו\"כ יש ג' מיני צמצומים בבחי' האצי' עד שמתהווה עולם הנפרד יש מאין כו' והן ג\"כ ג\"פ קדוש ע\"ד הנ\"ל מאוא\"ס לנאצלים עד שנק' הוי' צבאות בג' עולמות בי\"ע כו', והיינו ענין ג' מיני שערות לבנות שחורות ואדומות שבבחי' ע\"י וז\"א ומל' כנ\"ל. דהנה מ\"ש וע\"י יתיב ושער רישי' כעמר נקא, הוא בחי' הצמצום הראשון שמתצמצם האור לבוא בבחי' חכ' סתימאה להיות נק' חכים ומבין כו'. וכמו בחי' אור אבא דאצי' שמקבל ממזל דנוצר וכה\"ג להיות כי אוא\"ס שבכתר הוא למעלה מעלה מבחי' החכ' עד שהחכ' נק' בחי' עשי' לבד, כמ\"ש כולם<sup data-n=\"1702\">21</sup> בחכ' עשית כו' וכתי' עושה<sup data-n=\"1703\">22</sup> פלא שגם פלאות חכ' הוא בבחי' עשי', והיינו אלף דאאלפך<sup data-n=\"1704\">23</sup> חכ', ואין המשכה זו רק מבחי' מותרות ונובלות שהוא בחי' צומח שבחי כו' והיינו מבחי' מותרי מו\"ס דע\"י שנמשך בשערות דדיקנא דא\"א שנק' זקן אהרן, כמו עד\"מ הזקן בשנים ששערות זקנו לבנות, והוא כאשר נתמלא חכ' בבחי' גדלות המוחין עד שיוצאין ובוקעין בחי' מותרות שהן השערות דזקן וע\"כ נק' זקן<sup data-n=\"1705\">24</sup> זה קנה חכ' כו' כידוע. וכך למעלה בבחי' עתיק יומין שנק' זקן כמאמרז\"ל בים<sup data-n=\"1706\">25</sup> נדמה להם כבחור בשעת מ\"ת נדמה להם כזקן כו', הרי בחי' השערות דדיקנא הוא נמשך מבחי' מותרי מוחין דגדלות החכ' כו', אבל הוא בבחי' צמצום גדול כנ\"ל בענין השערות שהוא בבחי' הצמצום. וכמו עד\"מ השערה הגשמי' שהאדם אינו מרגיש כאב בגלחו אותה כו', אבל אעפ\"כ יש בשערות חילוקי מדריגות, שיש מהן שמורין על בחי' המשכת חסדים והן ענין בחי' שערות לבנות, שהלבנונית מורה על בחי' החסד דוקא כידוע, וגם כאן בבחי' המשכת אור החכ' ממקורה כו' הנה הוא בא מצד מקור החסדי' שבאא\"ס המאיר בע\"י כי<sup data-n=\"1707\">26</sup> חפץ חסד הוא כו', והיינו בחי' חוורתא שבגולגלתא דע\"י כו'. וזהו שאנו רואי' שהזקן כולו",[["1701","20","<b>וכידוע דאור אבא דאצי' מקבל מבחי' מזל ונוצר חסד</b>: ראה זח\"ג רפט, ב. ע\"ח שער הכללים פ\"ה. וראה ס' מאמרי אדה\"ז עה\"ת ח\"ב לע' תקעד. וש\"נ."],["1702","21","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["1703","22","<b>עושה פלא</b>: בשלח טו, יא. ועוד."],["1704","23","<b>דאאלפך חכ'</b>: איוב לג, לג. שבת קד, א."],["1705","24","<b>זקן זה קנה חכ'</b>: קידושין לב, ב. תו\"כ קדושים יט, לב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תשמ."],["1706","25","<b>בים נדמה להם כבחור בשעת מ\"ת נדמה להם כזקן</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב. וראה לקו\"ת צו ט, ד ובהמ\"מ שם. ס' מאמרי אדהאמ\"צ בראשית ע' רפב ואילך. שמות ח\"א ע' קלא. ויקרא ח\"א ע' רמח. וש\"נ."],["1707","26","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."]]],[2101920302,"רחמי' וחסדים פשוטים, ולכך כל מחילת העוונות הוא ע\"י המשכת י\"ג מדה\"ר שהן י\"ג ת\"ד דא\"א כו'. וכמ\"ש אם<sup data-n=\"1708\">27</sup> יהיו חטאיכם כשנים כשלג ילבינו כו' שהוא בחי' המתקת כל דין קשה שבא מצד העוונות והחטאים כידוע וד\"ל. וזהו בחי' קדוש הא' בחי' צמצום דוי\"ו שנמשך מכתר לחו\"ב דאצי'.\n<b>וקדוש</b> הב' הוא בחי' צמצום הב' שמחכ' ובינה במדות דאצי' שנק' ז\"א שמקבל ההארה מחו\"ב כידוע, שאז ההארה נמשכת מז\"א בבחי' צמצום ודין קשה, והן בחי' שערות דז\"א שנאמר בו שחורות<sup data-n=\"1709\">28</sup> כעורב כידוע שהשחרות מורה על תוקף הדין והוא להיות שבמדות אין האור דחו\"ב שם רק בצמצום ולא בהתרחבות כמו שהן במקורן, וגם להיות כי המדות יש בהן בחי' התחלקות וצמצומי' רבים מאוד עד שיוכל להיות בחי' הסתעפות דיני' קשי' למי שאינו ראוי כו' וכמ\"ש<sup data-n=\"1710\">29</sup> באד\"ר דד' מאות בתי דינין קשים מסתעפי' מדינא קשי' דז\"א וע\"כ נא' בבחי' השערות דז\"א שחורות ולא לבנות כשערות דע\"י, וע\"ד שאמר בזהר<sup data-n=\"1711\">30</sup> בענין ה' איש מלחמה כו', והיינו בים שנדמה להם כבחור, וכמ\"ש תפארת<sup data-n=\"1712\">31</sup> בחורים כחם בבחי' הגבורות, וכ\"ז מפני שמבחי' המדות דז\"א בא ונמשך השפע למטה לצורך הנהגות העולמות כו' משא\"כ<sup data-n=\"1713\">32</sup> בבחי' ע\"י וא\"א, שהוא למעלה מבחי' ההמשכה למטה בעולמות כידוע וד\"ל. וקדוש הג' הוא בחי' צמצום הג' שבמל' דאצי' שנא' שם ודלת<sup data-n=\"1714\">33</sup> ראשך כארגמן סומקי גו סומקי כו' שהוא תכלית הדין ביותר לפי שבחי' המל' הוא בחי' עולם הדיבור שמשם נמשך שרש התהוות בע\"ג בג' עולמות בי\"ע, אשר זהו בחי' צמצום היותר אחרון להסתיר כ\"כ אור האלקי כו', ע\"כ הן בחי' שערות אדומות כארגמן, משא\"כ בחי' שערות דז\"א שהוא למעלה עדיין מהיות בחי' מקור לבע\"ג רק שההשגחה נמשך משם כו'. וזהו קדוש הג' עד שנק' ה' צבאות בבי\"ע להיות מלא כל הארץ כבודו כו' וד\"ל.\n<b>ונמצא</b> גם מאצי' לבי\"ע יש ג' צמצומים עד שנק' הוי' צבאות וכ\"ז הוא מפני שצריך שיבוא האור העליון מגבוה לנמוך שהוא בבחי' דילוג הערך בשינוי המהות כמו מכתר לחכ' וחכ' במדות ומדות בדיבור וכה\"ג, ע\"כ צריך שיומשך האור בבחי' שערות שהוא שפע והמשכה מצומצמת הבאה בשינוי המהות כנ\"ל שהוא ענין המשכת אור בקיעה בעלמא. אמנם הוא עצמו הטעם שיכול לירד מטה מטה מגבוה לנמוך ביותר מפני שהוא בא בשינוי המהות כו', משא\"כ אם לא",[["1708","27","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח."],["1709","28","<b>שחורות כעורב</b>: שה\"ש ה, שם."],["1710","29","<b>וכמ\"ש באד\"ר דד' מאות בתי דינין קשים מסתעפי' מדינא קשיא דז\"א</b>: באוה\"ת נ\"ך (נסמן לעיל בתחילת המאמר) הל' כאן: וכמ\"ש (בזח\"ג נשא דקכ\"ט סע\"א) דממצחא דז\"א מתערין ד' מאה בתי דינין."],["1711","30","<b>בזהר בענין ה' איש מלחמה</b>: בשלח טו, ג. וראה זח\"ג מט, א."],["1712","31","<b>תפארת בחורים כחם</b>: משלי כ, כט."],["1713","32","<b>משא\"כ בבחי' ע\"י וא\"א</b>: באוה\"ת נ\"ך שם: משא\"כ בעת\"י נאמר המתנשא מימות עולם כו'."],["1714","33","<b>ודלת ראשך כארגמן סומקי גו סומקי</b>: זח\"ג שם מח, ב."]]],[2101920303,"הי' האור בא דרך בחי' שערות לא הי' יורד למטה בשינוי המהות למטה כ\"כ ולא הי' ביכולת המקבל לקבל, וכענין הושיט<sup data-n=\"1715\">34</sup> הקב\"ה אצבעו הקטנה ביניהן ושרפן כו' וכה\"ג. וע\"כ זהו הכלל בכל ההשתלשלות שכל ירידת האור מגבוה לנמוך למטה מטה ביותר הנה הוא בא ונמשך ע\"י בחי' שערות דוקא וד\"ל.\n<b>והנה</b> ידוע בענין סלסלה<sup data-n=\"1716\">35</sup> ותרוממך כו' שההלכות שבתורה נמשלו לנימין ושערות שבראש וזקן, אשר ע\"ז אמר סלסלה ותרוממך כו' לסלסל בשערות שהוא להבדיל בין דין לדין לעמוד כל דבר הלכה על בוריה ולא לבלבל הלכות בקושיות שזהו כמו דיבוק וקליעת השער, ולתרץ כל קושי' ה\"ז כמשל המסלסל שמפריד שער משער כו' וכמ\"ש במ\"א. ועכ\"פ נק' הלכות שבתו' בשם שערות ולכאורה דבר זה פלא גדול הוא. אך הענין הוא להיות כי בחי' חכ' שבתו' ירדה בצמצומים והעלמות רבות כמו חכ' עילאה שגנוזה בהלכות תרומות ומעשרות וכל סדר זרעים וכן הלכות שבסדר קדשי' וסדר טהרות, שע\"ז<sup data-n=\"1717\">36</sup> אמר חוסן ישועות חכ' ודעת כו'. ולפי הנראה לנו לעין השכל לא מושג כלל ענין חכ' מאחר שמלובשים הדברים בענינים גשמיים מאד. אך זהו ענין צמצום והשפלת ירידת אור ח\"ע למטה מטה כ\"כ בענינים גשמיים דנוגה כמו בקרבנות דבהמה ומצומח דתבואות וכה\"ג. ולהיות הארה זו מוגבלת מאד נמשלו ההלכות שבתו' בשם נימין ושערות, כמו עד\"מ השערה שהאור והחיות מצומצם בה בהעלם ביותר כנ\"ל, והיינו לפי שכל ירידת אור הבא מלמעלה בבחי' פירוד וריחוק הערך בשינוי המהות ממקור חוצבה שמשם נמשך הוא ענין ההמשכה ע\"י בחי' שערה שבה וע\"י נמשך בשינוי המהות בבחי' פירוד וריחוק הערך לגמרי. וזהו ענין ההלכות שבתו' הנגלית המלובשת בדברים גשמיים שנעשים בשינוי המהות במהות אחר לגמרי מכמו שהיא נמשכת ממקורה שאינה שם במהות וסוג ערך חכ' זו שמושג לנו בדברים גשמיים לא מיני' כו' כמו לימוד ההלכה דאם<sup data-n=\"1718\">37</sup> בהרת קדמה לשער לבן שנחלקו בה קוב\"ה ומתיבתא דילי' כמ\"ש בגמ' בעובדא דרבה ב\"נ וודאי בחי' ח\"ע שבהלכה זו בג\"ע מופשטת מכל בחי' גשם שהרי אין בהרת גשמי' בג\"ע כלל ואין לבחי' חכ' שבדין בהרת הנגלה לנו ערך וסוג כלל עם בחי' חכ' הרוחני' שבהלכה זו בעסקם בה בג\"ע, ואעפ\"כ משם נמשכה להתלבש למטה מטה גם בעולם העשי' וע\"כ נק' בחי' ירידת והעלמת המשכה כזאת מג\"ע דיצירה בעולם העשי' בשם נימין ושערות. ועד\"ז מגעה\"ע דבריאה ביצירה שבא האור ג\"כ בשינוי ודילוג המהות בערך המהות דחכ' דיצירה שנשתנה בעשי', וכללות בחי' חכ' שבבי\"ע ה\"ז נמשך מבחי' חכ' שבמל' דאצי' בבחי' נימין ושערות ונק' נימין דכלה וז\"ש סלסלה",[["1715","34","<b>הושיט הקב\"ה אצבעו הקטנה ביניהן ושרפן</b>: סנהדרין לח, ב."],["1716","35","<b>סלסלה ותרוממך . . כמשל המסלסל שמפריד שער משער כו' וכמ\"ש במ\"א</b>: משלי ד, ח. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' קז. מאמרי אדהאמ\"צ קונטרסים ע' תקמג."],["1717","36","<b>שע\"ז אמר חוסן ישועות חכ' ודעת</b>: ישעי' לג, ו. שבת לא, א."],["1718","37","<b>דאם בהרת קדמה . . כמ\"ש בגמ' בעובדא דרבה ב\"נ</b>: ב\"מ פה, ב."]]],[2101920304,"ותרוממך דקאי בהלכות דתושבע\"פ מל' קרינן לה. והוא ג\"כ מ\"ש ודלת ראשך כארגמן סומקי גו סומקי כנ\"ל, להיות שבחי' דינין והלכות דתושבע\"פ הם מלאים גדרים וסייגים לגופי המצות הכתובים בתושב\"כ כידוע, וגם להיות שבתושבע\"פ מתחלק כל דיני המצות לפרטי פרטים חילוקים מצומצמים ביותר לדקדק בהן עד כחוט השערה, כמו הלכות<sup data-n=\"1719\">38</sup> שבת שהן כהררים התלוים בשערה כו' וכה\"ג שכ\"ז הוא מצד בחי' הגבורו' והצמצומי' לחלק ולצמצם כ\"כ האור והשפע דח\"ע שבמל' כו', וזהו שהן כמראה האודם שמורה על בחי' הדין ביותר, וזהו כארגמן דוקא וד\"ל.\n<b>והנה</b> באמת יש בזה ג' מדריגות בדרך פרט והן ג' מיני שערות אדומות ושחורות ולבנות כנ\"ל, וכולן הן בבחי' המשכת אור ח\"ע שבתו' שיורדת ממדריגה למדריגה בג' מיני שערות הללו שהן בבחי' ע\"י וז\"א ומל' כנ\"ל. אך הנה תחילה יש להבין בביאור ענין השערות שאעפ\"י שלכאורה הרי הן בבחי' חיצוני' ומותרות השפע עד שאין נוגעין כלל לפנימיות החיות שבאדם שהרי כשיגזוז אותם לא ירגיש כלל כידוע, מ\"מ הנה אנו רואים בהם בחי' מעלה ומדריגה יתירה והוא בענין שערות הזקן דוקא, להיות ידוע שגם ששערות הזקן בוקעים ויוצאים רק מבחי' מותרי המוחין מ\"מ בחי' מותרי המוחין הללו באים מצד בחי' גדלות המוחין ביותר עד אשר יש בהן כח המוליד דוקא אז מצמיחין הן שערות וראי' מן הקטן שאין בו חכ' ומוחין דגדלות רק בבחי' הקטנות שאז אין בו בחי' מותרי המוחין שראוים להוליד וממילא לא יצמחו בו שערות הזקן, וכן האשה מפני שדעתה<sup data-n=\"1720\">39</sup> קלה ואין במוחה בחי' מותרי המוחין שבבחי' הגדלות ע\"כ לא תצמחנה בהן שערות הזקן כלל, וכן<sup data-n=\"1721\">40</sup> הסריס מפני שאין במוחו בחי' מותרי המוחין שהן באים מצד הלחלוחית והוא בטבעו מוחו יבש כו' ע\"כ לא יוליד ולא יצמח בו שער הזקן אעפ\"י שחכמתו ודעתו גדולה כו' כמ\"ש במ\"א. וא\"כ עכ\"פ יש בשערות הזקן מעלה יתירה מצד שרשם בבחי' גדלות המוחין דוקא, והוא ענין זקן שקנה חכ' כו' אשר מטעם זה הוזהרו על פאת זקנם דוקא, וכמ\"ש ופאת<sup data-n=\"1722\">41</sup> זקנם לא יגלחו כו' ואי' בזהר שהמגלח פאת זקנו פוגם בבחי' דיקנא עילאה כו' כי<sup data-n=\"1723\">42</sup> בצלם אלקים עשה את האדם כו', וכמו שבאדם למטה גדילים שערות הזקן מצד בחי' גדלות המוחין כו' כך למעלה בבחי' שערות דדיקנא עילאה הוא מצד בחי' גדלות המוחין עליונים דח\"ע דוקא, ובחי' השפעה מח\"ע שבגדלות בבחי' שערות דדיקנא גם שבאה בהן בבחי' דילוג ופירוד בשינוי המהות לגמרי מ\"מ שרשן בא מבחי' פנימיות גדלות המוחין דח\"ע דוקא. ואמנם בחי' שערות הראש ושער הגוף הרי",[["1719","38","<b>הלכות שבת שהן כהררים התלוים בשערה</b>: חגיגה י, א."],["1720","39","<b>שדעתה קלה</b>: שבת לג, ב."],["1721","40","<b>וכן הסריס . . אעפ\"י שחכמתו ודעתו גדולה כו' כמ\"ש במ\"א</b>: ראה גם לקו\"ת אחרי כח, ד. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תפח ואילך וע' תשעח ואילך. ובכ\"מ."],["1722","41","<b>ופאת זקנם לא יגלחו כו' ואי' בזהר שהמגלח פאת זקנו פוגם בבחי' דיקנא עילאה</b>: אמור כא, ה. ראה זח\"ג פח, ב. קלג, ב."],["1723","42","<b>כי בצלם אלקי' עשה את האדם</b>: נח ט, ו."]]],[2101920305,"גם באדם למטה גדולם בבחי' קטנות המוחין שבראש וקטנות החיות שבגוף הנק' מותרות כו' שהרי גם בתינוק בן יומו צומחי' שערות הראש ושער הגוף כו' וד\"ל.\n<b>אך</b> הנה שרש בחי' ההלכות שבתורה שנק' נימין ושערות, היינו בבחי' שערות שבראש כמ\"ש סלסלה כו' וכמש\"א<sup data-n=\"1724\">43</sup> האי אמתא דחזיא שמהפך במזיי' דרישי' עד מתי אתה מסלסל כו' לפי שההלכות הן נמשכים מבחי' קטנות וצמצומים דח\"ע כשמתצמצם במדות עליונות שנק' גופא וגם בשער הראש שאינו צומח רק מבחי' הקטנות והמותרות הנק' נובלות אשר יוצאים מבחי' פירוד מהמוח ואינם נחשבים מבחי' עצמות המוח כלל, וכמו\"כ בחי' השפעות והמשכות ההלכות שנק' הילוך מצומצם מבחי' הקטנות כו'<sup data-n=\"1725\">*43</sup>. ובזה יש ג' מדריגות חלוקות, בחי' שערות שבראש דע\"י הן לבנות דוקא, כמ\"ש ושער רישי' כעמר נקא כמו באדם למטה שכאשר יזקין אז שערות ראשו ג\"כ לבנות, ושערות ראש דז\"א הן שחורות כמ\"ש קווצותיו כו' שחורות כו', וקאי בשערות דז\"א<sup data-n=\"1726\">44</sup>, ושערות דמל' כארגמן ג\"כ בראש הוא כמ\"ש ודלת ראשך כארגמן כו'. וכ\"ז הוא בבחי' ירידת והשתלשלות אור דח\"ע<sup data-n=\"1727\">45</sup> שבקטנות מו\"ס דא\"א וע\"י כו' שיורד תחילה בשער רישי' בבחי' שערות לבנות שמורה על תוקף החסדי' ששם הוא בחי' רחמים פשוטים משום דלית<sup data-n=\"1728\">46</sup> שמאלא בעתיקא ובירידת האור יותר בבחי' ז\"א שמקבל ממוחין דאו\"א שם יורד ונמשך בחי' קטנות המוחין שבראש בבחי' תוקף הדין ביותר, והוא מ\"ש שחורות כעורב כו' כמו לטמא ולפסול ולחייב כו' מפני שהוא בבחי' הגבורות יותר לרחק למי שראוי לריחוק כו', לפי שבחי' המוחין שבמדות הם בבחי' הקטנות ביותר ומבדילין ביותר בין טמא לטהור לרחק בבחי' הגבורות והצמצומים ביותר, והוא מ\"ש להבדיל<sup data-n=\"1729\">47</sup> בין טמא לטהור כו' דכיין ומסאבין כו' שזהו בכללות ענין תושב\"כ שהוא בבחי' המדות דז\"א דמח\"ע<sup data-n=\"1730\">48</sup> דאבא נפקת כנ\"ל, ובירידת האור עוד מבחי' המדות דז\"א במל' שהוא בחי' תושבע\"פ כמו בחכמי ישראל המחדשים ומדקדקים בהלכות פרטיות כו' שם נמשך האור מבחי' קטנות המוחין שבראש דמל' עד שהוא כארגמן סומקי גו סומקי כו' בתוקף הדין ביותר כמו לעשות גדרים וסייגים הרבה לתורה לרחק את הטמא כו' בתכלית הריחוק ביותר, שזהו מצד בחי' גבורות וצמצומים דשמאל דוחה ביותר, וכן בענין ריבוי והתחלקות דינין פרטיי' שהן ריבוי ההלכות פרטיות שנק' נימין דכלה כנ\"ל שכ\"ז הוא רק בבחי' הגבורות ביותר כנ\"ל. ועז\"א סלסלה ותרוממך כו' להסיר יניקת בחי' הדינין הקשין שעושין קליעת שער מצד המותרות כמו עד\"מ קליעת שער גשמי שבא מצד בלבול",[["1724","43","<b>וכמש\"א האי אמתא . . עד מתי אתה מסלסל</b>: ראה מגילה יח, א: שמעוה לאמתא דבי רבי דאמרת לההוא גברא דהוה קא מהפך במזיי' ואמרה לי' עד מתי אתה מסלסל בשערך."],["1725","*43","<b>ראה הגה\"ה באוה\"ת נ\"ך שם (נסמן לעיל בתחילת המאמר)</b>: מסופק אני כו'."],["1726","44","<b>דז\"א</b>: בכת\"י ב: דראש."],["1727","45","<b>דח\"ע</b>: בכת\"י ב: דחו\"ב."],["1728","46","<b>דלית שמאלא בעתיקא</b>: זח\"ג קכט, א. ועוד."],["1729","47","<b>להבדיל בין טמא לטהור</b>: ע\"פ שמיני יא, מז."],["1730","48","<b>דמח\"ע דאבא נפקת</b>: ראה זח\"ב סב, א. ועוד."]]],[2101920306,"ההבלים זרים שבמוח מצד בחי' מותרות גסות וכיוצא ומשום שיניקת החיצונים מקבלים מפסולת הנופלים למטה מבחי' השערות דמל' כמ\"ש<sup data-n=\"1731\">49</sup> בזהר בשערהא אחידן כו', אשר ע\"כ אמרו שער<sup data-n=\"1732\">50</sup> באשה ערוה כו', וע\"כ הוצרך לגזור על אשה יפ\"ת שתגלח<sup data-n=\"1733\">51</sup> שער ראשה ועשתה את צפרניה כי הצפרנים והשערות באים מפסולת הגבורות, כמ\"ש אודם<sup data-n=\"1734\">52</sup> שממנו כו', ע\"כ אמר סלסלה כו' להפריד הבלבול, וממילא לא יהי' יניקה לסט\"א<sup data-n=\"1735\">53</sup> רק כפי המדה הקצובה מכבר ע\"פ מאמר קו המדה. וזהו מ\"ש דבחכ'<sup data-n=\"1736\">54</sup> אתברירו שהוא בבחי' חכ' דבתושבע\"פ דוקא כמ\"ש סלסלה כו' וד\"ל. ומ\"ש סלסלה ותרוממך היינו משום דנעוץ<sup data-n=\"1737\">55</sup> תחלתן בסופן דוקא ע\"כ בבחי' סלסול דשערות ראש דכנ\"י כארגמן הנ\"ל מגיע ברוממות המדריגות שהוא בבחי' שער רישי' דע\"י שהוא כעמר נקי כו' שכולו רחמי' וחסדים פשוטים כנ\"ל (והיינו שא' בזהר<sup data-n=\"1738\">56</sup> ע\"פ עין לא ראתה אלקי' זולתך יעשה למחכה לו למאן דדייק מילין דחוכמתא דוקא שהוא בחי' העיון שבתורה שבע\"פ לדקדק עד כחוט השערה כנ\"ל ששרשו מגיע בעדן עילאה שהוא בבחי' פנימית ע\"י וא\"א שמשם בוקע הארות והמשכות בבחי' שערות לבנות כו', אשר עין לא ראתה בגעה\"ע והתחתון שאין ההארה שם לנשמות רק מבחי' נימין דמל' כו' וזהו למחכ\"ה כח מ\"ה דחכ' בהיפוך אתוון, וכמ\"ש במ\"א).\n<b>ובכ\"ז</b> יובן ג\"כ ענין ג' מיני צמצומי' דג' מיני שערות הנ\"ל בענין השתלשלות העולמות ג\"כ עד שיוכל להיות בחי' חכ' ושכל אנושי בעוה\"ז השפל בבחי' פירוד ושינוי המהות כ\"כ להיות שאותיות הדיבור שבמל' נמשכים מבחי' מותרי המוחין שבמל' ונק' מילין דהדיוטא כמו יהי<sup data-n=\"1739\">57</sup> אור יהי רקיע כו' עד שבהשתלשלות רבות מתהווה מהבל רוח פיו שבע\"מ גם בחי' חכ' ושכל אנושי בעוה\"ז, ואעפ\"י שבחי' חכ' של כל הנבראי' ונוצרי' כו' כלא ממש חשיבי לגבי בחי' ח\"ע שבאצי' שנק' חכים כו' מ\"מ בחי' ח\"ע זו הרי היא בחי' מקור למקור כו' עד התהוות בחי' חכ' דבי\"ע רק שיורד האור דרך בחי' צמצומי' רבים, דהיינו דרך ג' צמצומים כללים מח\"ע דאור אבא במדות וממדות לדיבור דע\"מ כו' ומדבור למעשה. וא\"כ יובן שאין ערוך כלל לבחי' חכ' אנושית לגבי חכ' שבתורה גם שמלובשת בדברים גשמיים כו', להיות שההלכות שבתו' הן בחי' נימין דכלה שהוא בחי' המשכת חכ' שבמל' עצמה כמו שהיא במקורה כו' משא\"כ ירידת האור ושפע הנמשך מהבל הדיבור במלאכים עד התהוות חכ' האנושי שאין בזה מבחי'",[["1731","49","<b>כמ\"ש בזהר בשערהא אחידן</b>: זח\"ג ס, ב. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"ד ע' א'שלז. וש\"נ."],["1732","50","<b>שער באשה ערוה</b>: ברכות כד, א."],["1733","51","<b>שתגלח שער ראשה ועשתה את צפרני'</b>: תצא כא, יב."],["1734","52","<b>אודם שממנו כו'</b>: נדה לא, א."],["1735","53","<b>לסט\"א</b>: בכת\"י ב: לטמא."],["1736","54","<b>דבחכ' אתברירו</b>: ראה זח\"ב רנד, ב. ובכ\"מ."],["1737","55","<b>דנעוץ תחלתן בסופן</b>: ס' יצירה פ\"א מ\"ז."],["1738","56","<b>בזהר ע\"פ עין לא ראתה . . למאן דדייק מילין דחוכמתא</b>: ישעי' סד, ג. זח\"א קל, ב."],["1739","57","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."]]],[2101920307,"חכמה העצמי שבמל' עצמה רק מאור הבא בגילוי חיצוני בהארה בעלמא מהבל הדיבור בלבד ואף גם זאת הנה הוא בא בשינוי המהות ולא כמו שהוא עד\"מ השכל המושג מן הדיבור שאותו השכל שבמוח הוא מושג גם בדיבור שזהו למעלה בחי' חכ' שבדיבור, אלא מהבל הדיבור נתהווה שכל הנפש, כמו ויפח<sup data-n=\"1740\">58</sup> באפיו כו' שמרוח פיו נתהווה נפש האדם כו' הרי בא בשינוי המהות לגמרי, משא\"כ בחי' שערות שנמשכים ממותרי מוחין שבראש דמל' שהוא המשכת חכ' העצמית המושג לנשמות בג\"ע, וכן בעוה\"ז בהתלבשותה בדברי' גשמיים אעפ\"י שמצומצם בה האור מאוד כו'. וע\"כ אמרו סלסלה ותרוממך שתרומם לנפש האדם, שנפש האדם אינה רק מבחי' הבל דרוח פיו כמ\"ש ויפח באפיו נ\"ח, ושרש ההלכה היא בעצמיו' דח\"ע שבזו\"נ וע\"י וא\"א כנ\"ל וד\"ל.\n<b>והנה</b> ידוע דאת<sup data-n=\"1741\">59</sup> זלעו\"ז עשה אלקי' וכמו שיש בסט' דקדושה בחי' שערות דקדושה בבחי' ג' מדריגות כנ\"ל, כך בס\"א דקליפה יש ג\"כ בחי' שערות שבזקן וראש דקליפה מאחר שנעשים גם הם בציור אדם רק שנק' אדם בליעל כידוע והוא מ\"ש מלך<sup data-n=\"1742\">60</sup> זקן וכסיל שנק' ע\"י דקליפה שיש לו זקן בבחי' שערות לבנות ונק' מלך זקן וכסיל היפוך בחי' שערות דקדושה שמשם נמצא שרש החכ' כו'. וכללות הענין הוא ג\"כ ע\"ד הנ\"ל בענין הכלל בכל בחי' שערות שהן באים בבחי' ירידת אור ושפע שבבחי' דילוג גדול ושינוי ממהות למהות כו', כך בסט\"א יש בהם בחי' השפע שיורד שם דרך בחי' דילוג הערך ממהות למהות ולא בבחי' השתלשלות דרך עו\"ע כו', ואז נמשך שם בחי' פירוד גמור ביותר כו'. והענין הוא להיות ידוע הגם שסט\"א נק' אלקים אחרים מפני שמקבלי' רק מבחי' אחוריים ותמצית כו' שהוא בבחי' ריחוק הערך מאוד מן הקדושה מ\"מ כולם מודים באחדות ה' ויש בהן בחי' ביטול שלא למרוד ציווי ה' כמו גם בלעם שא' לא<sup data-n=\"1743\">61</sup> אוכל לעבור את פי ה' לעשות קטנה כו', ואעפ\"י שהן בבחי' יש נפרד עד שנעשי' ממנו ע\"ז כו' מ\"מ יודעים<sup data-n=\"1744\">62</sup> את רבונם וקרו לי' אלקא דאלקיא רק שאין זה בבחי' פנימיות רק בבחי' חיצוני' שהוא רק בחי' ההודאה בלבד שמודים בדבר זה שהוא אלקא דאלקיא אבל אין זה נוגע אליהם להיות עובדי ה' בביטול והשתחוואה גמורה כמו צבא השמים שבסט' דקדושה שמשתחוים בבחי' ביטול פנימי כו', אלא הם מחזיקים א\"ע לבחי' יש נפרד העושה חיל לאמר כחי ועוצם ידי כמ\"ש לי<sup data-n=\"1745\">63</sup> יאורי כו', אבל אינם כופרים בה' לגמרי להיות שנמשך אליהם אור אלקות ומקבלים חיות האלקו' עכ\"פ רק שבא אליהם בבחי' אחוריים כו'. אשר ע\"כ לא יוכל לכפור לגמרי לפי שיודעים היטיב שלולא בחי' הארת אור האלקי אליהם אין להם חיות וקיום מצד עצמן כלל אשר לזה קורין לו אלקי האלקי' כו'. וע\"כ לא יכול בלעם לשנות ולעבור דבר ה' כי לא יכול למרוד בשום אופן, וכמ\"ש מי לא",[["1740","58","<b>ויפח באפיו</b>: בראשית ב, ז."],["1741","59","<b>דאת זלעו\"ז עשה אלקי'</b>: קהלת ז, יד."],["1742","60","<b>מלך זקן וכסיל</b>: נסמן לעיל."],["1743","61","<b>לא אוכל לעבור את פי ה'</b>: בלק כב, יח."],["1744","62","<b>יודעים את רבונם</b>: ראה להלן בסמוך."],["1745","63","<b>לי יאורי</b>: יחזקאל כט, ג. וראה בכ\"ז בס' שער היחוד לאדהאמ\"צ קמו, א. וש\"נ."]]],[2101920308,"יראך מלך הגוים, וכמו ושמי נורא בגוים, וכתי' מלך אלקי' על גוים, רק שהוא רם ומתנשא עליהן מרחוק כי לא מאיר עליהם בבחי' פנימיות רק בבחי' חיצוני' ואחוריים שלזה הם בבחי' פירוד, אבל אינן כופרים לגמרי מטעם שמקבלים שרש יניקתם מן הקדושה ויודעים את רבונם בבחי' ההודאה מרחוק עכ\"פ כנ\"ל וד\"ל.\n<b>אך</b> הנה כ\"ז מצד שהאור והשפע האלקי מאיר עליהם, וזאת ההארה גם שבאה ונמשכת בסט' דקליפה בריבוי ההשתלשלות מעילה לעילה בכל פרטי המדריגות שבהן מראשן לסופן כמו מקליפה דאצי' בקליפה דבריאה ומקליפה דבריאה לקליפה דיצי' כו' כידוע שאזלעו\"ז עשה כו', ויש קליפה דאצי' בפרצוף אדם ראש ומוחין וגופא כו' ומשפיע לבריאה והיינו כמו מבחי' נה\"י דז\"א דקליפה דאצי' נמשך מוחין לבחי' ע\"י דקליפה כו', והוא הנק' מלך זקן וכסיל כו', מ\"מ לא יוכל להיות בהן בחי' נפרד גמור כ\"כ למרוד כו' מאחר שלא נפסק שם הארת אור האלקי לגמרי גם שמצומצם שם בתכלית ההסתר כו' וראי' מבלעם וכה\"ג כנ\"ל. אך כאשר הולך השפע בסט\"א שלא בבחי' עו\"ע אלא בבחי' ריחוק הערך בשינוי ממהות למהות שהוא ע\"י בחי' שערות כנ\"ל, אזי יוכל להיות בהם בחי' פירוד גמור כמו קליפה דסנחרב שכיחש באלקות לגמרי כנ\"ל.\n<b>וביאור</b> הדבר הנה גם שיש ריבוי השתלשלות ביותר כ\"ז שההשתלשלות הולכת ונמשכת בבחי' עו\"ע אשר אין העלול רחוק מן העילה כ\"כ ויש לה ערך וסוג כו' ואינו בא בשינוי המהות בדילוג הערך כ\"כ, אזי גם ברבבות ירידת המדריגות לא ישתנה המהות של האור והשפע הראשנה כ\"כ רק שבתכלית הירידה במדריגה היותר תחתונה שם הוא במיעוט האור ביותר, אבל הוא אותו האור ממש שבראשית ההשתלשלות כמו אור השפע הנמשך מן הרצון לשכל ומשכל למדות ודיבור ומעשה הרי גם במעשה ודבור הוא אור אותו הרצון שבשכל רק שנתמעט אורו בירידתו דרך השכל ומן השכל ירד למדות ומן המדות בדיבור כו', מפני שאין כאן שינוי המהות כלל ברצון זה שכמו שהוא בשכל כך הוא במדות ודיבור ומעשה רק שנתמעט כח אורו בלבד כו', משא\"כ בהיות הרצון בא בשינוי מהות בהתלבשות שונות, וכמו הלבשת המשלים להשכל שאינו נגלה שם במהותו רק דרך לבוש והעלם המשל כו' וכה\"ג שזהו בחי' השערות וכידוע. וכך יובן למשכיל למעלה בבחי' השתלשלות עו\"ע דפרצופי' העליונים דא\"ק וע\"י כו' שלא ע\"י העלם ולבוש דבחי' שערות הרי הארה הראשונה לא נשתנה בשינוי המהות רק שבא במיעוט וצמצום ביותר, משא\"כ ע\"י בחי' שערות בא האור בשינוי המהות, וע\"כ יוכל להיות התהוות מהות חדש שאינו בערך כלל ממהות המשפיע כנ\"ל בסט' דקדושה שמתהווה מהות החכ' ע\"י בחי' מזל דנוצר בחי' שערות מלמעלה מן החכ', וכן עד\"ז עד התהוות חכ' למטה מטה בעולם העשי' כו'.\n<b>ואמנם</b> יובן מזה בהבדלת הערך גם בסט' דקליפה שאם האור הוא הולך ומשתלשל בהם דרך עו\"ע שהוא בקירוב הערך גם שכל עיקר שורש הראשון שלהם אינו רק מבחי' האחרונה שבקדושה המצומצם ביותר כנ\"ל, מ\"מ"],[2101920309,"א\"א שיתהווה בהם בחי' נפרד גמור שיוכל להכחיש לגמרי באלקות אלא כולם מודים וקרו לי' אלקא דאלקיא רק שהארה זאת מאירה בצמצום והעלם גדול ביותר כאשר בא בהם בבחי' ההשתלשלות ביותר עד שיוכל לומר לי יאורי כו' ויוכל למרוד ולעבור רצון ה' כמ\"ש פרעה מי<sup data-n=\"1746\">64</sup> ה' אשר אשמע בקולו כו', אבל כולם יודעים ומודים על האמת וזשארז\"ל<sup data-n=\"1747\">65</sup> שיודעי' את רבונם ומתכונים למרוד בו ולעבור רצון ה' כנ\"ל, אך עכ\"ז אין זה פירוד גמור כ\"כ כמו מי שמכחיש במציאות אור האלקי לגמרי, כמו עד\"מ עבד המורד באדונו שגם שמורד ואינו רוצה לישא עול אדוניו, מ\"מ יודע ומודה שהוא עבד, והוא אדונו ומלכו רק שאינו רוצה להיות בביטול אליו כו', משא\"כ המורד בעיקר המלוכה לומר שאינו מלך כלל אלא הוא המלך וכה\"ג זהו הנק' מורד גמור. והוא ענין קליפה דסנחרב מלך אשור שהי' מכחיש במציאות אלקות לגמרי, וע\"כ אמר מי בכל אלקי הארצות להשוות ח\"ו עם אלקי' אחרים עץ ואבן וכו\"מ הווים ונפרדים ולא הי' מאמין כלל שהוא ית' קדמון לכל הקדומי' ועלת כל העילות כו' כשאר אוה\"ע דקרו לי' אלקא דאלקיא רק שאינם רוצים לעבדו כי אומרים עזב ה' את הארץ, וכה\"ג כנ\"ל.\n<b>והנה</b> שרש זה הפירוד העצום הנה הוא בא מפני ששורש מזלו דסנחרב זה למעלה בסט' דקליפה שנק' אדם בליעל בבחי' יניקת שערות דאדם זה בלבד, שנק' מלך זקן וכסיל כי אזלעו\"ז עשה אלקי' כנ\"ל שההמשכה וההשפעה הבאה בבחי' דילוג גדול כ\"כ בשינוי המהות כמו בחי' שערות כנ\"ל, מזה יוכל להיות בחי' יניקה לקליפה קשה שהיא בבחי' פירוד לגמרי להיות מכחיש לגמרי ולהיות מהות בפ\"ע לגמרי כאלו לא קבל אור ושפע מן המשפיע ואין לו קשר וחיבור עמו כלל כמו בחי' ההשפעה דשערות הרחוקה במהות ערך נבדל לגמרי מחיות שבראש וגוף עד שכאשר יחתוך אותו לא ירגיש כאב כלל כידוע, א\"כ לא יש ליניקה שבהם שום שייכות וקירוב כלל לגבי אור וחיות של המשפיע שהוא אור אלקי וע\"כ יכול להכחיש לגמרי כו'. והן המה האפקורסין שכופרים בה' לגמרי ואינם מאמינים בחידוש העולם כו' כידוע שאין להם תיקון ועלי' כלל כידוע<sup data-n=\"1748\">66</sup> בשם הבעש\"ט ז\"ל שיותר יש תיקון לגוי עובד ע\"ז מן האפקורסין מטעם הנ\"ל, וראי' לזה שהרי לעתיד נא' אז<sup data-n=\"1749\">67</sup> אהפוך אל עמים כו', ונהרו<sup data-n=\"1750\">68</sup> אליו כל הגוים כו', לפי שהם מאמינים באחדות הוי' רק שמפני משכא דחויא נתגשמו ביותר נדמה להם הנהגה הטבעית שע\"פ כו\"מ וכה\"ג שזהו העיקר ולע\"ל כתי' וראו<sup data-n=\"1751\">69</sup> כל בשר מפני שיהי' לאחר הבירור כו'. אבל האפקורסים אין להם עלי' גם לעתיד כ\"א אבודם זהו תקונם כו'.",[["1746","64","<b>מי ה' אשר אשמע בקולו</b>: שמות ה, ב."],["1747","65","<b>וזשארז\"ל שיודעי' את רבונם ומתכונים למרוד בו</b>: ראה תו\"כ בחוקותי כו, יד. וראה ס' מאמרי אדהאמ\"צ בראשית ע' צח."],["1748","66","<b>כידוע בשם הבעש\"ט ז\"ל שיותר יש תיקון לגוי עובד ע\"ז מן האפיקורסין</b>: ראה גם בס' שבחי הבעש\"ט מכת\"י (ירושלים תשמ\"ב) ע' 249 (שם המאמר מאוה\"ת נ\"ך שנסמן לעיל בריש המאמר). ובהנסמן שם."],["1749","67","<b>אז אהפוך אל עמים</b>: צפני' ג, ט."],["1750","68","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב."],["1751","69","<b>וראו כל בשר</b>: ישעי' מ, ה."]]],[2101920310,"<b>כ\"ז</b> יובן ענין המאמר שבסנהדרין פ' חלק ע\"פ ביום ההוא יגלח אדני בתער השכירה בעברי הנהר מלך אשור כו' שיגלח הוי' את שערות הראש דמלך אשור שהוא בחי' שרש יניקתו למעלה שמקבל מבחי' השערות דוקא, וכאשר יגלחו ויחתכו את שערות הראש דמלך זקן וכסיל כו' ממילא לא יהי' מסתעף ממנו בחי' נפרד גמור כ\"כ שיהי' ביכולתו להכחיש ולכפור לגמרי כו', כי מצד בחי' ההשתלשלות דעו\"ע שלא ע\"י בחי' שערות גם בריבוא רבבות השתלשלות בסט\"א דאזלעו\"ז עשה כו', לא יוכל להיות בחי' פירוד גמור כזה לכפור לגמרי רק שמורד ופורק עול לבד כנ\"ל וד\"ל.\n<b>וז\"ש</b> ביום ההוא יגלח אד', שם אד' דוקא בחי' הגבורות, שכדי להעביר השער שהוא בחי' הגבורות והצמצומים צריך שיהי' המבערם ג\"כ בבחי' הגבורות, כענין לעולם<sup data-n=\"1752\">70</sup> ירגיז כו' כי לבער הרע צ\"ל בחי' תוקף הדין כמו ובערת<sup data-n=\"1753\">71</sup> הרע כו'. וזהו בתער השכירה, בתער דוקא כמו בלוים שגם הם מבחי' הגבורות בסט' דקדושה, אך בחי' שערות הוא נבדל בערך ויוכל להיות מזה בחי' גבורות קשות ביותר, ע\"כ העבירו<sup data-n=\"1754\">72</sup> תער על כל בשרם כו', וכמ\"ש בזהר. וענין התער יש בו ב' פרושים הא' תער כפשוטו שהוא המספרים המגלחי', והב' מענין תער ונרתק כמו חרבי<sup data-n=\"1755\">73</sup> מתערה כו'. והענין הוא כמ\"ש כי<sup data-n=\"1756\">74</sup> שמש ומגן הוי' אלקי' ששם אלקי' הוא כמו נרתק לשמש להעלים ולהסתיר כו', כך שם אלקי' הוא בחי' הגבורות המצמצמים ומעלימים לאור דשם הוי' שלא יאיר רק למי שראוי ולא למי שאינו ראוי כו', כי מצד עצם אור החסד שבשם הוי' יוכל להאיר ולהשפיע בכולם בשוה לרעים כמו לטובים לפי שמטבע<sup data-n=\"1757\">75</sup> הטוב להטיב לכל גם למי שאינו ראוי כראוי. וכמו אברהם איש החסד שהי'<sup data-n=\"1758\">76</sup> מטיב חסדו גם לערביים וכה\"ג וע\"כ יצא<sup data-n=\"1759\">77</sup> ממנו ישמעאל בחי' מותרי החסדים כו'. ולזה צריך להיות בחי' הגבורות עליונות דשם אלקים לצמצם ולהסתיר דהיינו למנוע האור והשפע, ולהיות מעצור לרוחו לצמצם את אור החסד שבלבו שלא להשפיע למי שאינו ראוי רק לראוי כו', הנה לזה צריך בחי' גבורות דוקא שהוא בחי' תגבורת כח גדול לעצור רוחו כמו איזהו<sup data-n=\"1760\">78</sup> גבור הכובש כו', וכמו כל מי שיכול לכבוש ולעצור רוחו נק' גבור כו'. ולמעלה היינו ג\"כ התער והנרתק דשם אלקים ושם אד' כו', שהוא בחי' תוקף ועוז הכח לגבור על החסד ולצמצמו כו', והוא המגלח לבחי' השערות שהן מותרי",[["1752","70","<b>לעולם ירגיז</b>: ברכות ה, א."],["1753","71","<b>ובערת הרע</b>: פ' ראה יג, ו."],["1754","72","<b>העבירו תער על כל בשרם וכמ\"ש בזהר</b>: נשא ח, ז. ראה זח\"ג מח, א. קכז, א ואילך."],["1755","73","<b>חרבי מתערה</b>: יחזקאל כא, ח-י."],["1756","74","<b>כי שמש ומגן</b>: תהלים פד, יב."],["1757","75","<b>שמטבע הטוב להטיב</b>: ראה תניא שעהיחוה\"א פ\"ד. עמה\"מ שער שעשועי המלך רפ\"א. שומר אמונים ויכוח ב' סי\"ד. ובכ\"מ."],["1758","76","<b>שהי' מטיב חסדו גם לערביים</b>: ראה סוטה י, א ואילך. ב\"מ פו, ב. ובכ\"מ."],["1759","77","<b>יצא ממנו ישמעאל</b>: פסחים נו, א. ובכ\"מ."],["1760","78","<b>איזהו גבור הכובש</b>: אבות פ\"ד, מ\"א."]]],[2101920311,"השפע הבאים מצד ריבוי האור שנפל וצומח מותרות כידוע. וזהו שא' שיגלח בסט\"א את בחי' המותרות שאינו ראוי לפי שמזה מתהווים קליפות קשות ביותר כנ\"ל וע\"כ אין צריך להיות מותרות השפע במלך זקן כו' (משא\"כ בסט' דקדושה אדרבה צריך הכה\"ג לגדל פרע שער, משום דקדושה אתמשך בשערות כמ\"ש קדוש<sup data-n=\"1761\">79</sup> יהי' כו' רק בלוים צריך לעבור תער כמ\"ש בזהר).\n<b>ומ\"ש</b> את הראש ושער הרגלים וגם את הזקן תספה, הענין הוא דשערות הראש ורגלים הן בחי' חיצוני' הגוף בלבד ממותרי הדמים ולחלוחית שבגוף, משא\"כ בחי' שערות הזקן שבא מבחי' מותרי מוחין דוקא שהוא מבחי' פנימי' המוחין דגדלות כשנגדלים בשלימות אז יצאו שערות הזקן, ואת זלעו\"ז כו' כמו בבחי' שערות דדיקנא דקדושה, הוא בחי' מותרי מוחין דקדושה כו' כנ\"ל, ומבחי' שערות הזקן דקליפה שנק' מלך זקן וכסיל נמשך למטה בבחי' חכמות חיצוני' כמו חרטומי מצרים, שנא' ואת זקניו יחכם<sup data-n=\"1762\">80</sup> כו' וז\"ש וגם את הזקן תספה שלא יהי' מלך זקן ולא יומשך ממנו בחי' מותרות חכ' דקליפה הגם שאין בהם טומאה כ\"כ ובזהר<sup data-n=\"1763\">81</sup> קוראם רה\"מ סבא פרקי דשטותא, משום שנאמר מלך זקן וכסיל, ויש יתרון<sup data-n=\"1764\">82</sup> לחכמה מן הסכלות כו', מ\"מ מטמאות את הנפש, ובפרט כמו חכמת הפלסופיא שנמשך ממנה האפקורסין כידוע, שמזה הי' שרש קליפה דסנחרב וע\"כ אמר וגם את הזקן תספה כו', והיינו שאמרו בגמרא דאתא קודב\"ה וגזי' לדיקני' כו' וכמו בפרעה שירד הקדב\"ה בכבודו ובעצמו כו' ולא ע\"י מלאך ושליח<sup data-n=\"1765\">83</sup> כו', כך מאחר דזלעו\"ז עשה כו' צריך להיות גילוח המלך זקן כו' ע\"י הקב\"ה בעצמו דוקא כו' וד\"ל.",[["1761","79","<b>קדוש יהי'</b>: נשא ו, ה."],["1762","80","<b>ואת זקניו יחכם</b>: ע\"פ תהלים קה, כב."],["1763","81","<b>ובזהר קוראם רה\"מ סבא פרקי דשטותא</b>: זח\"ג מז, ב. וראה גם דרמ\"צ קה, א."],["1764","82","<b>ויש יתרון לחכמה מן הסכלות</b>: קהלת ב, יג."],["1765","83","<b>ולא ע\"י מלאך ושליח כו'</b>: ראה זח\"א קיז, א. לקו\"ת צו טז, א. ובהמ\"מ לשם."]]],[2101920312,"<h3><i>נוסח אחר</i>: ביום ההוא יגלח</h3>\n<b>נוסח אחר</b>\n<b>ביום</b><sup data-n=\"1766\">1</sup> ההוא יגלח ה' בתער השכירה בעברי נהר במלך אשור את הראש ושער הרגלים וגם את הזקן תספה. להבין זה שהשי\"ת בכבודו ובעצמו יגלח את מלך אשור, ומה ענין גילוח זה. הנה באמת יש הפרש בין סנחריב מלך אשור לכל האומות, כי בכל האומות כתיב הודו<sup data-n=\"1767\">2</sup> לאלקי האלקים כל\"ח, וכמ\"ש בזהר<sup data-n=\"1768\">3</sup> דקרו לי' אלקא דאלקייא, פי' כי עם היותם עובדי כו\"מ אעפ\"כ לא שהם מכחישים במציאת הבורא ית' אדרבה כולם מודים בו ויודעים היותו ית' יוצר כל היצורי' אלא שזהו ההפרש בינם לישראל עם סגולתו, שהם אומרים שגם המזלות הם יש ודבר בהיותם מנהלים ומשפיעים חיות בעולם השפל שלנו כי כך מסר להם הבורא ית' ועזב את הארץ בידם, והוא ית' הוא אלקא דאלקייא אבל על השמים כבודו, ואינן כישראל שאומרים אין<sup data-n=\"1769\">4</sup> עוד מלבדו גם בארץ מתחת ואין ממש באלהיהם שהם הכו\"מ ולפי שהאומות אינן כן ומאמינים בכו\"מ לענין שהם המשפיעים חיות בעולם השפל ולכן הם מזבחים ומקטירים להכו\"מ כדי שישפיעו להם חיות ושפע שזה תלוי ברשותם ואות נפשם, אבל בו ית' הם מודים וכמ\"ש במלאכי<sup data-n=\"1770\">5</sup> ממזרח שמש עד מבואו מהולל שמי בגוים, וכן בכל<sup data-n=\"1771\">6</sup> חכמי הגוים ובכל מלכותם מאין כמוך, והרבה פסוקים כיוצא באלו כמו הללו<sup data-n=\"1772\">7</sup> את הוי' כל גוים כו' מי<sup data-n=\"1773\">8</sup> לא יראך מלך הגוים כו' כל<sup data-n=\"1774\">9</sup> העמים תקעו כף כו', משא\"כ סנחריב ששלח לחרף אל חי ואמר ההצילו<sup data-n=\"1775\">10</sup> אלהי העמים את ארצם מידי, איה אלהי ספרוים אלהי חמת כו', והשוה גם אלקים חיים להם וכמ\"כ פרעה אמר מי<sup data-n=\"1776\">11</sup> הוי' אשר אשמע בקולו כו' אלא שאעפ\"כ פרעה לא כפר אלא בשם הוי' אבל בשם אלקים הודה אבל סנחריב הי' כופר בכל וכדכתי' בהדיא בקרא אשר<sup data-n=\"1777\">12</sup> שלחו לחרף אלקים חי כו'. והנה נודע כי אין<sup data-n=\"1778\">13</sup> לך דבר למטה שאין לו מזל מלמעלה וגם סנחריב היה לו שר למעלה, והוא גם הוא מחולק משאר כל השרים של האומות שכולם קרו לי' אלקא דאלקא ולכן גם האומות המקבלים מהם הם מודים לה' כו' והוא כופר בכל וממנו נתהוה סנחריב הגשמי מלך אשור הכופר. ואמנם להבין",[["1766","1","<b>ביום ההוא</b>: נדפס כאן מגוכי\"ק אדמו\"ר הצ\"צ, והוא הנחה אחרת של מאמר הקודם. וראה בהמ\"מ בתחילת המאמר שם. ונמצא ג\"כ בס' מאמרי אדה\"ז נביאים ע' מג."],["1767","2","<b>הודו לאלקי האלקים כל\"ח</b>: תהלים קלו, ב."],["1768","3","<b>בזהר דקרו לי' אלקא דאלקיא</b>: עד\"ז בסוף מס' מנחות."],["1769","4","<b>אין עוד מלבדו</b>: ע\"פ ואתחנן ד, לט."],["1770","5","<b>במלאכי ממזרח שמש עד מבואו מהולל שמי בגוים</b>: א, יא. [וכאן הוא צירוף הפסוק דמלאכי והפסוק דתהלים קיג, ג: ממזרח שמש עד מבואו מהולל שם ה']."],["1771","6","<b>בכל חכמי הגוים</b>: ירמי' י, ז."],["1772","7","<b>הללו את ה' כל גוים</b>: תהלים קיז, א."],["1773","8","<b>מי לא יראך מלך הגוים</b>: ירמי' שם."],["1774","9","<b>כל העמים תקעו כף</b>: תהלים מז, ב."],["1775","10","<b>ההצילו אלהי העמים את ארצם מידי</b>: ע\"פ מלכים ב יח, לג-לד. יט, יב-יג. ישעי' לו, יח-יט. לז, יב-יג."],["1776","11","<b>מי הוי' אשר אשמע בקולו</b>: שמות ה, ב."],["1777","12","<b>אשר שלחו לחרף אלקים חי</b>: מל\"ב יט, טז."],["1778","13","<b>אין לך דבר למטה שאין לו מזל מלמעלה</b>: ראה ב\"ר פ\"י, ו."]]],[2101920313,"איך אפשר להיות התהוות קליפה גסה וקשה כ\"כ להיות כופר במציאות השי\"ת לגמרי שהוא בחי' מציאות נפרד לגמרי ממנו ית' ולמה תבדל משאר כל הקליפות שבסט\"א שכולם מודים בה' ואינן נפרדים לגמרי כ\"כ לפי שמקבלים חיות מהקדושה כו'. אך הענין דהנה כתיב את<sup data-n=\"1779\">14</sup> זלע\"ז עשה האלקים פי' דכמו שבקדושה יש השתלשלות המדרגות בריבוא רבבות מדרגות כך הוא ג\"כ בסט\"א.\n<b>והנה</b> בסט' דקדושה כתי' בדניאל ועתיק<sup data-n=\"1780\">15</sup> יומין יתיב כו' לבושי' כתלג חיור ושער רישיה כעמר נקא, ופי' לבושי' קאי על שערות דדיקנא שהמה לבנים כשלג כי את הקב\"ה המשיל לאיש זקן שיש לו זקנה ושערותיו לבנות וז\"ש ועתיק יומין יתיב כו', ובאמת כי זהו פלאי מה זה ענין<sup data-n=\"1781\">16</sup> זקנה קמיה קוב\"ה כו'. אך הענין כי כ\"ז הוא ע\"ד משל ומליצה, כמו עד\"מ שערות הזקן שבאדם הגשמי המה נמשכים מהמוח שמותרי מוחי' בוקעי' ויוצאי' בשערות הזקן וכנראה בעליל שלכן אין גדילים שערות הזקן באשה לפי<sup data-n=\"1782\">17</sup> שדעתה קלה ואין לה מוחי' גדולים כ\"כ שיהי' מהם מותרות שיצאו ויגדלו בזקן כו'. וגם באמת אנו רואי' לכאורה בהיפוך שהשערות הם אינן נוגעים כלל להמוח עד שגם כשיגזוז אותם לא ירגיש במוחו שום כאב כלל, אך הענין שזהו לפי שהם בחי' המשכה הנמשכת בפירוד מהמוח ואינן מעצמיותו ומהותו כ\"א מן המותרות שלו שלכן הם כדבר נפרד ממנו שאין נוגע לו כלל כו', וכך עד\"מ זה יש ג\"כ השפעה כזו למעלה ברוחנית ממנו ית' והיא הנק' בשם דיקנא עילאה כי<sup data-n=\"1783\">18</sup> בצלם אלקים עשה את האדם כתיב וכמו שבאדם יש זקן בגשמיות והיא בחי' המשכה שמהמוח היוצאת בבחי' פירוד ככה יש גם למעלה המשכה מבחי' חכמתו ית' בדוגמא זו וע\"כ נאמר פאת<sup data-n=\"1784\">19</sup> זקנם לא תגלחו והמגלח<sup data-n=\"1785\">20</sup> זקנו פוגם בדיקנא עילאה כו' והיינו כי להיות התהוות חכמה של הנבראי' מחכמתו העצמית ית' שאין לה חקר ונק' חכים<sup data-n=\"1786\">21</sup> ולא בחכמה ידיעא, ואפי' בחי' חכמה דאצי' מקור כל ההשתלשלו' היא כאין ואפס לגבי חכמתו ית' שאינה ממהות וערך החכמה ידיעא היא החכמה דאצילות כו', ובאמת אילו הי' ההמשכה מעצמיות חכמתו ית' לא הי' כלל באפשרי להיות התהוות החכמה דאבי\"ע, אלא לפי שההמשכה היא רק מבחי' החיצוני' והמותרו' של אותו החכמה ונמשלה לשערות שהם המשכה שבפירוד ממהות המקור שמשם נמשכת, שלכן יוכל להיות מזה התהוות מהות חכמה אחרת שאינה ממהות וסוג אותה החכמה כלל, וזהו ענין הלכות התורה שנק' בשם נימין ושערות כי עם היותם חכמתו ית' אבל הוא השפלת חכמתו ית' בעניני גשמיים תרומות ומעשרות כו', והשפלה זו מעצמיו' חכמתו הרוחני' הבלתי מוגבלת נק' בשם שערות דוקא מטעם הנ\"ל.",[["1779","14","<b>את זלע\"ז עשה האלקים</b>: קהלת ז, יד."],["1780","15","<b>ועתיק יומין יתיב . . ושער רישיה כעמר נקא</b>: דניאל ז, ט."],["1781","16","<b>ענין זקנה קמיה קוב\"ה</b>: ראה יבמות טז, ב."],["1782","17","<b>לפי שדעתה קלה</b>: שבת לג, ב."],["1783","18","<b>כי בצלם אלקים עשה את האדם</b>: נח ט, ו."],["1784","19","<b>פאת זקנם לא תגלחו</b>: אמור כא, ה."],["1785","20","<b>והמגלח זקנו פוגם בדיקנא עילאה</b>: ראה זח\"ג פח, ב. קלג, ב."],["1786","21","<b>חכים ולא בחכמה ידיעא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101920314,"<b>והנה</b> באמת בדרך פרט יש ג' בחי' שערות, הא' הם אותן שערות לבנות הנ\"ל שנאמר בדניאל גבי עתיק יומין כו', והב' הוא מ\"ש בשה\"ש קצותיו<sup data-n=\"1787\">22</sup> תלתלים שחורות כעורב, והם בחי' שערות הזקן של הקב\"ה בזמן שנק' דודי כמש\"ש דודי<sup data-n=\"1788\">23</sup> צח ואדום כו' מה דודך מדוד כו' וע\"ז קאי מ\"ש קצותיו תלתלים כו' והוא בחי' ז\"א כידוע, והג' הוא בחי' שערות דכנס\"י שנאמר בה ודלת<sup data-n=\"1789\">24</sup> ראשך כארגמן שהם שערות אדומים. ולהבין כללות ענין ג' מיני שערות אלו, הענין כי זהו ענין ג' צמצומי' שיש מזה לזה, שהם המשכות שבבחי' פירוד וריחוק ממהות המשפיע שלכן נק' בשם שערות דוקא, וכבר נת' ענין לבושי' כתלג חיור שהוא בשביל להיות המשכת בחי' חכמה באצילות מחכמתו העצמית ית' (היא הח\"ס) שהיא בריחוק והבדל המהות, והמשכה כזו נק' שערות, ונק' שערות הזקן דוקא שהם הנמשכים מן המוח כנ\"ל ומהם מתהוה בחי' החכמה דאצי' אבא יונק ממזלא כו' (וכמ\"כ המוחי' דז\"א שנמשכים מאו\"א), ומה שנק' בשם שערות לבנות היינו לפי שמשם הוא בחי' רחמים פשוטים וכנודע שבז\"א הוא שיש התחלקות ו\"ק חסד ודין תרין עיינין כו' משא\"כ בעתיקא<sup data-n=\"1790\">25</sup> לית שמאלא כו' והחסד<sup data-n=\"1791\">26</sup> נמשל לגוון הלבן כידוע ומבואר במ\"א, הב' הם בחי' שערות דז\"א היינו להיות התהוות בחי' בי\"ע בע\"ג מאצילות הוא ג\"כ המשכה בדילוג הערך ונק' שערות והם נק' שערות שחורות לפי שיש בו בחי' גבורות לצמצם השפע שהגבורות מורים על גוון השחור כדכתי' שחורות<sup data-n=\"1792\">27</sup> כעורב כו', הג' בחי' שערות דכנ\"י מל' דאצי' היא בחי' עולם הדיבור שיהי' בחי' המשכת עשרה מאמרות לומר יהי אור יהי רקיע גשמיים שהם מילין<sup data-n=\"1793\">28</sup> דהדיוטא כו' ונחשבי' ג\"כ בשם שערות.\n<b>והנה</b> את זלע\"ז עשה האלקים ויש בקליפ' ג\"כ בחי' שערות ע\"ד הנ\"ל, ויש שערות דדיקנא דקליפ' ושערות הראש כו', וענינם הוא ג\"כ בחי' השפעה בדילוג הערך ממהות למהות, כי הנה כל בחי' הסט\"א כולם מודים בה' (וכמאמר בלעם<sup data-n=\"1794\">29</sup> לא אוכל לעבור את פי ה') לפי שמקבלים חיות מהקדושה האלקי' ויודעים שלולי חיות זה היו מתבטלים ממציאותם ולכן לא יוכלו לכפור בה' לגמרי, כ\"א זאת היא רעתם שהם יש ודבר גם בעצמותם ואינן בבחי' ביטול לגמרי כמו צבא מעלה שבסט' דקדושה, שלזאת נקראי' סטרא אחרא, שאינן מקבלים אא\"ס בפנימיותם מצד שאין להם בחי' הביטול רק שהם מודים בלבד בה' וקרו לי' אלקא דאלקיא אבל אינו נוגע אליהם, אבל מ\"מ אין כופרים לגמרי להיותם מקבלים",[["1787","22","<b>קצותיו תלתלים</b>: [כ\"ה בגוכי\"ק]. שה\"ש ה, יא."],["1788","23","<b>דודי צח ואדום כו' מה דודך מדוד</b>: שה\"ש ה, ט-י."],["1789","24","<b>ודלת ראשך כארגמן</b>: שם ז, ו."],["1790","25","<b>בעתיקא לית שמאלא</b>: ראה זח\"ג קכט, א. ובהמ\"מ במאמרי אדהאמ\"צ דברים ח\"ג ע' תתעא. נ\"ך ע' קצג."],["1791","26","<b>והחסד נמשל לגוון הלבן כידוע ומבואר במ\"א</b>: ראה גם לקו\"ת ואתחנן יג, ב. שה\"ש נ, ד. תו\"ח ויצא קעט, ד."],["1792","27","<b>שחורות כעורב</b>: שה\"ש ה, שם."],["1793","28","<b>מילין דהדיוטא</b>: זח\"ג קמט, ב. וראה לקו\"ת אחרי כה, ד. ובכ\"מ."],["1794","29","<b>בלעם לא אוכל לעבור את פי ה'</b>: בלק כב, יח."]]],[2101920315,"חיות מהקדושה כנ\"ל. והנה גם שיש כמה וכמה השתלשלות המדרגות בקליפות שכל א' הוא מקבל חיות משלמעלה הימנו, וכל מה שיורד ונמשך החיות בהשתלשלות יותר אזי הוא מתרחק יותר מהקדושה האלקית, אעפ\"כ לא יוכל להיות התהוות הנפרד הגמור אלא כולם מודים בה' ע\"ד הנ\"ל לפי שיודעים שמקור חיות זה הוא מהקדושה, כי בחי' ההשתלשלות אינו גורם שינוי המהות כו', והתהוות הנפרד הגמור הכופר במציאות ה' לגמרי ע\"ד הנ\"ל בסנחריב מלך אשור אינו אלא לפי שהתהוותו מן הסט\"א גופא הוא רק בבחי' שערות בלבד שהשערות הוא בחי' המשכה שבשינוי המהות ובבחי' פירוד ממש מן המשפיע עד שנראה כאילו הוא דבר בפ\"ע ואינו שייך כלל להמשפיע כנ\"ל באריכות בסט' דקדושה שע\"י השערות נעשה התהוות מהות חדש שאינו מערך המשפיע והוא בחי' התהוות חכמה דאצילות או דבי\"ע שאינן מערך חכמתו העצמית ית' כו' ואינן תופסים עצמו' חכמתו כו' וכך באלפי אלפים הבדלות לאין קץ ותכלית בהשתלשלות שבסט\"א כשההשפעה נמשכת בדרך עו\"ע אזי לא נתהוה מזה עדיין הנפרד הגמור כ\"א כולם מודים לה' אבל כשההשפעה נמשכת בבחי' פירוד ממש מהמשפיע עד שנראי' כאילו היא דבר בפ\"ע ממש יוכל המתהוה ממנה להפרד ממש ולהיות נעשה יש גמור ולכפור בה' ולומר שאין עוד עליו גבוה כלל, וזהו ענין סנחריב מלך אשור שאמר איה<sup data-n=\"1795\">30</sup> אלהי חמת אלהי ספרוויים כו' ההצילו את ארצם מידי כי יציל ה' אלקיכם את הארץ הזאת מידי, וכפר לגמרי במציאות הבורא ית', והיינו לפי שהמזל שלו שמלמעלה מקבל מבחי' שערות כנ\"ל.\n<b>והנה</b> לעת\"ל יגלח ה' בעברי נהר במלך אשור את הראש כו' כלומר שיגזזו השערות שלא יהיו צומחים מן הגוף ואזי לא יהי' התהוות הנפרד הגמור עכ\"פ גם שיהי' בחי' השתלשלות מעילה לעילה יהי' הכל בסוג א' דהיינו כנ\"ל דקרו לי' אלקא דאלקיא כו', ודיים הקליפות שנמשך להם חיות מסט' דקדושה אף שאינן בביטול כבסט' דקדושה כנ\"ל אבל לא יצמח שערות מהם שהוא השפעה שבבחי' פירוד שמתהוה מזה הנפרד הגמור כנ\"ל, וז\"ש יגלח ה' במלך אשור דוקא שמקבל מן השערות כנ\"ל שלכן הוא כופר לגמרי, את הראש ושער הרגלים וגם את הזקן כו' כי שערות הזקן הם נעלים יותר משערות הראש והרגלים, ששערות הראש והרגלים הם מחיצוני' הגוף משא\"כ שערות הזקן באים ממותרי מוחין שהם בחי' פנימי' וכנראה בעליל שבאשה שדעתה קלה ואין לה מוחי' מרובים כ\"כ להיות<sup data-n=\"1796\">*</sup>.\n<b>",[["1795","30","<b>איה אלהי חמת . . ההצילו את ארצם</b>: נסמן לעיל קרוב לתחילת המאמר."],["1796","*","<b>להיות</b>: עד כאן נמצא בגוכי\"ק."]]],[2101920316,"<h3></b>[ויט<sup data-n=\"1797\">1</sup> משה<sup data-n=\"1798\">2</sup> גו' וישב הים לפנות בוקר לאיתנו].</h3>\n<b></b><b>[ויט משה גו' וישב הים לפנות בוקר לאיתנו].</b>\n<b>...ולהיות</b> המשכה ממקום גבוה כ\"כ יודע הי' הקב\"ה שלא הי' באפשרי לישראל כפי שהיו אז באותו פרק ובאותו זמן לעורר, כי זה הי' מיד אחר יציאתם ממצרים שהיו<sup data-n=\"1799\">3</sup> שקועים שם בנ' שערי טומאה וכנז'<sup data-n=\"1800\">4</sup> בדרז\"ל שהי' קיטרוג על הים כל הלילה מה נשתנו אלו מאלו הללו עע\"ז כו' לכן התנה<sup data-n=\"1801\">5</sup> תנאי עם הים שיקרע לפני בנ\"י כו' ופי' שעדיין לא נגמר ישותו עד שיקיים תנאו ויתבטל מיש לאין וכנ\"ל<sup data-n=\"1802\">6</sup> בדין התנאי שעד שמתקיים התנאי אין הדבר כלום א\"כ עד שיקרע הים ונתבטל מיש לאין עדיין לא הי' ממש כ\"כ בישותו שנתן לו הקב\"ה במע\"ב על תנאי זה כנ\"ל, ולפיכך הי' בנקל להיות נקרע גם שלא הי' המשכה ממקום גבוה ורם כ\"כ, פי' כי עם היות כי ההמשכה בקי\"ס הי' מבחי' סוכ\"ע הנ\"ל דקמי' אין ויש שוין ממש אבל הי' רק הארה בלבד משם משום שישראל הן במדרגה קטנה ולא הי' מהם אתעדל\"ת אלא שהקב\"ה בכבודו ובעצמו הוריד הארה משם ולכן לא הי' רק הארה בלבד, ולפי שלא הי' הים עדיין יש כ\"כ מאחר שעדיין לא נתקיים תנאו כנ\"ל, לכך גם כח הארה זו הספיקה לבטלו מישותו הקלה זו לאין, משא\"כ אם הי' מתהוה בבחי' יש בלי שום תנאי בעולם אזי הי' נגמר ישותו כראוי להיות יש ודבר ממש ואז קשה הי' אח\"כ להיות מתבטל לאין אם לא ע\"י המשכת עצמיו' הסוכ\"ע דקמי' אין ויש שוין ולא ע\"י הארתו לבד. והמשכה זו א\"א להיות כ\"א באתעדל\"ת דוקא שאזי מעורר אתעדל\"ע מעצמיו' הסוכ\"ע משא\"כ באתעדל\"ע מצד עצמו דיו בזה שמוריד ומשפיל הארה א' ממנו, ולפי שלא הי' באפשרי להיות אתעדל\"ת אז ביצ\"מ לכן הוצרך הקב\"ה להתנות תנאו עם הים שאזי יהי' יכול להקרע גם בלי אתעדל\"ת מטעם הנ\"ל.\n<b>ובזה</b> יובן מ\"ש לאיתנו לתנאו גבי וישובו<sup data-n=\"1803\">7</sup> המים ולא גבי קריעתם לפני ישראל, כי הנה פי'<sup data-n=\"1804\">8</sup> איתנו הוא חוזקו ותוקפו והיינו שנגזר ישותו להיות יש ודבר",[["1797","1","<b>ויט משה</b>: נדפס כאן מגוכי\"ק אדמו\"ר הצ\"צ בס' תקע\"ב [1116 נב, א], והוא הנחה משנת תקע\"ב, אך יש שם רק דף אחד וחסר התחלת המאמר. ומתוכנו ניכר שהוא ע\"פ ”ויט משה גו' וישב הים לפנות בוקר לאיתנו\". ונמצא גם בס' מאמרי אדה\"ז עה\"ת ח\"א ע' רעא. [ולע\"ע לא מצאנו תוכן המאמר בשאר ספרי רבותינו נשיאינו]."],["1798","2","<b>ויט משה גו'</b>: בשלח יד, כז."],["1799","3","<b>שהיו שקועים שם בנ' שערי טומאה</b>: כן הובא בכ\"מ. וראה זהר חדש יתרו לא, א. ובס' השיחות ה'תש\"ב ע' 94: אין שער הנו\"ן זיינען ניט געווען קיין אידן, נאר דאס איז די שמרים פון מ\"ט שערים. וראה בהמ\"מ ס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רסב. ס' שער האמונה יג, ב."],["1800","4","<b>וכנז' בדרז\"ל שהי' קיטרוג . . מה נשתנו אלו מאלו</b>: ראה זח\"ג קא, ב. זח\"ב קע, ב."],["1801","5","<b>התנה תנאי עם הים</b>: ב\"ר פ\"ה, ה. שמו\"ר פכ\"א, ו."],["1802","6","<b>וכנ\"ל בדין התנאי</b>: ראה לקו\"ש ח\"ו ע' 92 הע' 36."],["1803","7","<b>וישובו המים</b>: בשלח שם, כט."],["1804","8","<b>פי' איתנו הוא חוזקו ותוקפו</b>: ראה פירש\"י שם."]]],[2101920317,"ממש ע\"י שקיים תנאו שיקרע לפני ישראל שאזי הוא גמר קיום הדבר שנתן לו הקב\"ה במע\"ב להיות יש ודבר. והנה היכר תוקפו וחזקו הוא ע\"י מה ששב הים אח\"כ על המצרים וירדו בו במצולות<sup data-n=\"1805\">9</sup> כמו אבן אלא שזה הי' ע\"י שנקרע מתחלה לפני ישראל ולכן כתי' אז לאיתנו כלומר לחזקו ותוקפו וע\"י מה ע\"י תנאו שקיים תחלה במה שיקרע לפני ישראל שעי\"ז יכול אח\"כ לשוב על המצרים וד\"ל.\n[הגהות מכ\"ק אדמו\"ר הצ\"צ]\nגם הים<sup data-n=\"1806\">10</sup> ראה האי<sup data-n=\"1807\">11</sup> דכתיב בי' וינוס, כי יוסף ע\"י וינוס בחי'<sup data-n=\"1808\">12</sup> ל\"ת חותם שוקע מזה נמשך חותם בולט קי\"ס גילוי עצום, וזה החילוק בין וינוס דים להרים<sup data-n=\"1809\">13</sup> רקדו חותם בולט שלמטה, ולכן נאמר וישב הים לאיתנו כמ\"ש ביוסף ותשב<sup data-n=\"1810\">14</sup> באיתן כו', וכן בקר בחי' יוסף כמ\"ש בזהר בלק ר\"ד ב' וזהו לפנות בוקר לאיתנו ע\"ד דוד<sup data-n=\"1811\">15</sup> אתקין לי' חופאה כו' והיינו בחי' ים כו'.\n<b>איתנו</b> עמ\"ש<sup data-n=\"1812\">16</sup> בענין איתן האזרחי ואיתן יסוד אבא כו' ע' ע\"פ ראה ולכן עי\"ז נגמר ישותו כי התהוו' היש גשמי דוקא מסוכ\"ע יש אמיתי.\n<b>על</b><sup data-n=\"1813\">17</sup> הנהר כו' אלע\"ל לא נצטרך תנאי כי יומשך ממקום עליונה יותר בחי' איתן ממש יתגלה לע\"ל.",[["1805","9","<b>במצולות כמו אבן</b>: בשלח טז, ה."],["1806","10","<b>הים ראה</b>: תהלים קיד, ג."],["1807","11","<b>האי דכתיב בי' וינוס</b>: ע\"פ וישב לט, יב-יג: ויעזוב בגדו בידה וינס ויצא החוצה גו' וינס החוצה. וב\"ר פפ\"ז, ח."],["1808","12","<b>בחי' ל\"ת </b> [לא תעשה]<b> חותם שוקע</b>: לקו\"ת שה\"ש מה, א ואילך."],["1809","13","<b>להרים רקדו</b>: שם, ד."],["1810","14","<b>ותשב באיתן</b>: ויחי מט, כד."],["1811","15","<b>דוד אתקין לי' חופאה</b>: זהר בלק שם."],["1812","16","<b>עמ\"ש בענין איתן האזרחי . . ע' ע\"פ ראה</b>: תהלים פט, א. לקו\"ת ר\"פ ראה. וראה גם קונטרס לימוד החסידות ע' 5 ואילך."],["1813","17","<b>על הנהר</b>: ישעי' יא, טו."]]],[2101920318,"<h3>ענין קרי\"ס</h3>\n<b>ענין</b><sup data-n=\"1814\">1</sup> קרי\"ס, כתיב לגוזר<sup data-n=\"1815\">2</sup> ים סוף לגזרים כל\"ח ואמרו<sup data-n=\"1816\">3</sup> שנגזר לי\"ב גזרים לכל שבט גזר מיוחד בפ\"ע לעבור בו, למה צריך גזר וקרע לכל שבט ושבט בפ\"ע. ועוד י\"ל מ\"ש בישעי' דלעתיד יעברו בנהר והניף<sup data-n=\"1817\">4</sup> ידו על הנהר והכהו לז' נחלים לז' בלבד ולא לי\"ב ולמה גם בי\"ס לא הי' הקרע לז' או לעתיד ג\"כ יהי' לי\"ב גזרים, והלא נאמר כימי<sup data-n=\"1818\">5</sup> צאתך מאמ\"צ אראנו נפלאות לעתיד. אך הנה לעתיד אמר והיתה<sup data-n=\"1819\">6</sup> מסילה לשאר עמו אשר ישאר מאשור וממצרים המה בני הגולה שנתפזרו בד' מלכיות כו' יתקבצו כולם בימוהמ\"ש ותחילת העברתם יהי'<sup data-n=\"1820\">7</sup> דרך אותו הנהר שהוא נהר פרת והוא יקרע לז' נחלים ויהי' בו מסילה לעבור בו שאר עמו כו'.\n<b>והנה</b> כתיב בנהר פרת והנהר<sup data-n=\"1821\">8</sup> הרביעי הוא פרת הוא דמעיקרא, פי' כי הנהר שממנו נפרדו הד' נהרות הוא עצמו הנהר פרת, כמ\"ש ונהר<sup data-n=\"1822\">9</sup> יוצא מעדן פי' נהר זה הוא נהר פרת שיוצא מן העדן להשקות את הגן ומשם יפרד נהר זה ונחלק לד' נהרות והוא נהר פישון נהר גיחון כו' עד נהר הרביעי הוא פרת ודקדקו רז\"ל על תיבת הוא שלכאורה הוא מיותר ע\"כ אמרו הוא דמעיקרא שהוא נהר פרת עצמו הנהר הראשון שממנו נפרדו הד' נהרות, ונהר פרת זהו שיבקע לעתיד כמ\"ש והניף ידו על הנהר והכהו לז' נחלים כו'. וז\"ש הפך<sup data-n=\"1823\">10</sup> ים ליבשה בנהר יעברו ברגל שם נשמחה בו, הרי על ענין קרי\"ס אמר הפך ים ל' עבר ועל ענין העברת הנהר לעתיד א' בנהר יעברו ברגל ושם נשמחה לעתיד ולהבא, כמ\"ש כימי צאתך מארמ\"צ אראנו נפלאות לעתיד וגם גזרו אומר שמזכירים יצי\"מ לע\"ל כמ\"ש למען<sup data-n=\"1824\">11</sup> תזכור את יום צאתך מארמ\"צ כל ימי חייך להביא לימות המשיח ועוה\"ב, ולכאורה ממ\"ש שם נשמחה בו משמע שם דוקא נשמחה בו ולא תזכור עוד אז יצי\"מ וקי\"ס כו'.",[["1814","1","<b>ענין קרי\"ס</b>: מאמר זה הוא הנחת כ\"ק אדהאמ\"צ, ונו\"א (הנחת כ\"ק אדמו\"ר הצ\"צ) נדפס להלן. ונדפס בשינויים ובתוס' הגהות בלקו\"ת צו טז, ד. (ומתחיל: והניף ידו על הנהר וגו' הנה ים סוף כו'). ובאריכות בס' שער האמונה מאדהאמ\"צ פרקים נ\"ב-ס\"ד (פג, א ואילך). המאמר נמצא ג\"כ בס' מאמרי אדה\"ז עה\"ת ח\"א ע' רנד."],["1815","2","<b>לגוזר ים סוף לגזרים</b>: תהלים קלה, יג."],["1816","3","<b>ואמרו שנגזר לי\"ב גזרים</b>: ראה פדר\"א פמ\"ב. תנחומא בשלח י. פירש\"י תהלים שם. וראה מכילתא בשלח יד, טז. וראה גם לקו\"ת צו טו, ד. יז, א ואילך. בהעלותך לא, ב. מסעי צד, ד. מאמרי אדהאמ\"צ ויקרא ח\"א ע' רכא (ובהמ\"מ שם)."],["1817","4","<b>והניף ידו על הנהר</b>: ישעי' יא, טו."],["1818","5","<b>כימי צאתך מאמ\"צ</b>: מיכה ז, טו."],["1819","6","<b>והיתה מסלה לשאר עמו</b>: ישעי' שם, טז [כאן הובא הפסוק בקיצור, ושם: לשאר עמו אשר ישאר מאשור כאשר היתה לישראל ביום עלותו מארץ מצרים]."],["1820","7","<b>יהי' דרך אותו הנהר שהוא נהר פרת</b>: ראה פירש\"י ישעי' שם."],["1821","8","<b>והנהר הרביעי הוא פרת הוא דמעיקרא</b>: בראשית ב, יד. בכורות נה, ב ובפירש\"י שם."],["1822","9","<b>ונהר יוצא מעדן</b>: בראשית שם, י."],["1823","10","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["1824","11","<b>למען תזכור את יום צאתך . . להביא לימות המשיח</b>: פ' ראה טז, ג. ברכות יד, ב."]]],[2101920319,"<b>והנה</b> להבין כ\"ז יש להקדים תחילה שרש ענין קי\"ס מהו, דהנה באמת י\"ל לאיזה טעם העבירם בתוך הים ביבשה דוקא דאם מפני שלא רצה לנחותם<sup data-n=\"1825\">12</sup> דרך ארץ פלשתים כי קרוב הוא, כמה דרכים היו לפניו שלא דרך י\"ס, ואם מפני שרצה לטבוע למצרים בי\"ס הלא הוא ית' כל יכול ויש לפניו כמה דרכים להמית כולם בדבר רח\"ל וכה\"ג. אלא הענין הפשוט מורה שלא בשביל טביעת מצרים בים סוף העבירם שם, כי זה הי' דרך אגב, אלא בשביל תועלת ישראל עצמם שצריכין לעבור בי\"ס כדי שיהי' הכנה בנפשם לקבלת התורה בהר סיני פנים<sup data-n=\"1826\">13</sup> בפנים כו'.\n<b>ולהבין</b> מהו השייכות לקי\"ס עם מתן תו' צ\"ל תחילה שרש ענין הים מהו, דהנה ידוע מאמר<sup data-n=\"1827\">14</sup> הזהר ע\"פ זה הים גדול כו' שם אניות יהלכון כו' דכמו שאית ימא לתתא כך אית ימא לעילא כו' ושם אניות יהלכון בחי' ארבין דסלקין ונחתין כו' ונונין כו', והענין הוא כמו עד\"מ הים הגשמי יש בו כל הברואים שיש ביבשה כמארז\"ל כל<sup data-n=\"1828\">15</sup> מה שיש בים יש ביבשה כו' אך הבריות שבים א\"א להיות ביבשה כלל ומיד<sup data-n=\"1829\">16</sup> שיעלו ביבשה מתים כו' ולא יתקיימו אפי' שעה אחת וכן הבריות שביבשה א\"א להיות בים אפי' שעה אחת מפני שנחנקים ממימי הים וכמ\"כ הבריות שבים נחנקים מאויר שביבשה כו', וזהו דבר פלא לכאורה אם הם ברואי' ממין א' בים וביבשה למה נשתנה טבע חיותם כ\"כ מן ההיפך עד דמה שזה לו לאור וחיות נפשו הוא ממית לזולתו ומה שמחי' לזולתו הוא ממית לו כו'. אך הענין הוא דבחי' הים הוא דבר מגביל ומכסה על הברואים שמובלעים בו וא\"א להם לקבל מאויר הארץ רק מן הים, וכן הוא נעשה כמו דבר מגביל על הבריות שביבשה שלא יוכלו לקבל ולחיות בים כי שם<sup data-n=\"1830\">17</sup> לים חוק וגבול להבדיל ולהעלים בין הבריות שבים ובין הבריות שביבשה שלא יוכלו בריות שבים לעלות ליבשה ולא יוכלו בריות שביבשה לירד לים אבל אם לא הי' מי הים עולה ומכסה על הבריות כלל הי' אפשר להיות חיבור ושיתוף בבריות שבים וביבשה להיות בריות שבים יוכלו לקבל מאויר שביבשה ובריות שביבשה יוכלו לקבל חיות בים כו', רק הים עולה ומכסה על הברואים שלא יתראו ביבשה כלל והוא אשר נעשה להבדיל ביניהם בתכלית מן הקצה אל הקצה כו' וד\"ל. והנמשל מזה יובן ג\"כ למעלה בבחי' י\"ם העליון דאצי' שנק' ג\"כ בשם י\"ס סופא דכל דרגין כידוע והענין הוא שהוא סופא דכל דרגין דאצי' וא\"כ הוא הנעשה כמו בחי' מסך מפסיק ומבדיל בין אצי' לבריאה עד אשר לא יעבור אור מאצי' לבריאה ולא יעלה שום אור מבריאה",[["1825","12","<b>לנחותם דרך ארץ פלשתים</b>: בשלח יג, יז."],["1826","13","<b>פנים בפנים</b>: ואתחנן ה, ד."],["1827","14","<b>מאמר הזהר ע\"פ זה הים גדול</b>: תהלים קד, כה ואילך. זח\"ב מח, ב."],["1828","15","<b>כל מה שיש ביבשה יש בים</b>: חולין קכז, א. ירושלמי שבת פי\"ד ה\"א."],["1829","16","<b>ומיד שיעלו ביבשה מתים כו' ולא יתקיימו אפי' שעה אחת</b>: ראה בכ\"ז חולין שם. ביאוה\"ז בשלח מא, ג ואילך. תו\"א בשלח סב, ב. סה\"מ תקס\"ג ח\"א ע' קנד (בנוסח הא'). תו\"ח תולדות קנח, ב. לקוטי שיחות ח\"ח ע' 363. חי\"ט ע' 161."],["1830","17","<b>שם לים חוק וגבול</b>: ע\"פ ירמי' ה, כב. משלי ח, כט. ב\"ב עג, א."]]],[2101920320,"לאצילו' כנ\"ל במשל בבריות שבים שלא יוכלו לעלות ליבשה ובריות שביבשה לא יוכלו לירד לים כו'.\n<b>ולהבין</b> ביאור הדברי' הנה י\"ל תחילה בביאור ענין בחי' ים העליון דאצי' מה הוא, הנה ידוע דבחי' מל'<sup data-n=\"1831\">18</sup> דאצי' הוא בחי' הדיבור העליון כמ\"ש בדבר<sup data-n=\"1832\">19</sup> ה' שמים נעשו כו' והן עשרה מאמרות יהי<sup data-n=\"1833\">20</sup> אור יהי רקיע וכה\"ג שהם רק בחי' המשכות פרטיות מי\"ס דאצי', במאמר יהי אור נמשך מאור חסד דאצי' כו' וכך כל בחי' האורות העליונים דאצי' מתלבשים באותיות הדיבור העליון כידוע, ולהיות כי אותיו' הדיבור הוא בחי' מעלים ומסתיר ומכסה על כל המתלבש בו ע\"כ נק' בשם ים כמו שהים הוא מכסה על כל מה שבתוכו כנ\"ל, כמו עד\"מ דיבור האדם הנה מלובש בו רצון ושכל ומדות, כמו כשמדבר דברי חסד ואהבה או דברי חכ' או דברי תענוג ורצון כו' הרי התענוג והרצון והשכל והאהבה אינם מושגים לשומע במהותם כמו שהם ממש כי השומע אינו שומע רק בחי' אותיו' בחי' דומם כמו הבל הפה הגשמי, רק שמבין מתוך הדיבור את הרצון והשכל או האהבה, וה\"ז בא למקבלים דרך הסתר ושינוי המהות לגמרי לפי שאותיו' הדיבור מעלימים ומצפינים מהות הרצון והשכל בתוכם, וכמו הים שמעלים ומכסה מה שנגנז בתוכו, כך כל בחי' האורות עליונים כו' דרצון וחכ' ומדות דאצי' נעלמי' וגנוזים באותיות הדיבור המכסה ומעלים אותן עד שלגבי הנבראים שנבראו מבחי' אותיו' הדיבור דע\"מ אין להם השגה כלל וכלל במהות אורות דאצי' הגנוזים באותיות הדיבור מאחר שכל עיקר התהוותם אינו רק מבחי' הבל אותיו' הדיבור והבל אותיות הדיבור מעלים ומכסה על כל מה שבתוכו מבחי' אור העליון כמ\"ש כל<sup data-n=\"1834\">21</sup> הנחלים הולכים אל הים שהם בחי' המדות העליונים כו' והמל'<sup data-n=\"1835\">22</sup> נק' ים ועל זה אמר זה הים גדול כו', ולזה הטעם אין הנשמות ומלאכים דאצי' יכולים לירד בבי\"ע שהוא בחי' יבשה עלמא דאתגליא שמקבלי' מאותיו' הדיבור כי אותיו' הדיבור מכסה עליהם, כמו דגים שמובלעים בים שא\"א להם לירד ביבשה ואם יוצאות ביבשה לא יוכלו לחיות מאויר הארץ, כן לא יוכלו לבוא למטה לחיות מחיות הדיבור כו', וכמ\"כ להיפך א\"א שיעלו נשמות ומלאכים דבי\"ע באצי' כי יתבטלו שם לגמרי כמו בריות שביבשה שא\"א להם לחיות בים, וכ\"ז מפני בחי' דיבור העליון שנק' ים סופא דכל דרגין שבאצי' שנעשה כמו מסך מעלים ומבדיל בין אצי' לבריאה עד שא\"א שיבוא ויומשך אור דאצי' להתגלות למטה בבי\"ע ולא יוכלו הנבראים לעלות לאצי' כנ\"ל במשל הים הגשמי שהוא חוק וגבול להבדיל ביז בריות שבים לבריות שביבשה כנ\"ל וד\"ל. [ומ\"ש בזהר<sup data-n=\"1836\">23</sup> ע\"פ וידגו לרוב בקרב הארץ שיש נשמות ומלאכים העליונים דאצי' ממש שיורדות",[["1831","18","<b>מל' דאצי' הוא בחי' הדיבור</b>: ראה זח\"א פו, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ב ע' שפב."],["1832","19","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ה."],["1833","20","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["1834","21","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["1835","22","<b>והמל' נק' ים</b>: ראה פרדס שכ\"ג (שער ערכי הכינויים) מע' ים."],["1836","23","<b>בזהר ע\"פ וידגו לרוב בקרב הארץ</b>: ויחי מח, טז. זח\"ג קפז, ב."]]],[2101920321,"ומתגלות בקרב הארץ ביבשה בחי' עלמא דאתגליא, זהו כמו ענין קרי\"ס שמן ההעלם נעשה גילוי לקרוע המסך כנ\"ל כמשי\"ת בע\"ה].\n<b>והנה</b> איתא בזהר<sup data-n=\"1837\">24</sup> שבבחי' ים העליון יש נונין וארבין שעל זה אמר שם אניות יהלכון כו', והענין הוא כידוע שבחי' נשמו' דאצי' המתכללי' במל' דאצי' ומתאחדים בה בתכלית הן הנק' נוני ימא רבא והוא כמו ג' סבות ורשב\"י כמ\"ש<sup data-n=\"1838\">25</sup> בזוהר בכמה דוכתי על רב המנונא סבא שהוא נוני ימא רבא דשט בימא רבא ועד\"מ דגים שבים שמובלעים בים ומתאחדים בה בתכלית עד שהמים להם כמו חיות לנפשם כמו חיות האויר שיחי' ממש הבע\"ח בארץ כידוע ויותר מזה שהרי הבע\"ח מופרד במציאות חיות נפשו רק שמקבל מן האויר והדגים מובלעים בתוך הים והים מכסה עליהם מלמעלה שזהו מורה על בחי' חיות עצמי' וכך הנשמו' דאצי' בבחי' ים העליון שבבחי' חכ' שבדיבור העליון מובלעים שם ומתאחדים בבחי' אלקות בבחי' חיות עצמי כמש\"א<sup data-n=\"1839\">26</sup> רשב\"י בחד קטירא אתקטרנא כו' בי' אחידא בי' להיטא כמארז\"ל למה<sup data-n=\"1840\">27</sup> ת\"ח נמשלו לדגים שבים שמיד שפורשים ליבשה מתים כו', והרבה יותר מביטול והתכללו' של הנשמות ומלאכי' שנבראו מבחי' אותיו' הדיבור שזה כמו חיות הבע\"ח מן אויר הארץ כך מקבלי' מהבל רוח פיו כמ\"ש וברוח<sup data-n=\"1841\">28</sup> פיו כל צבאם דאעפ\"כ הן דבר ויש בפ\"ע וגם<sup data-n=\"1842\">29</sup> יש להם חומר גופני כמו אש ורוח כידוע רק שהוא מבטל בחי' יש שבו ע\"י השגתו בכח אלקי המהווה אותו מאותיו' הדיבור כנ\"ל, ואין זה ערך כלל לבחי' ביטול והתכללו' דנשמו' ומלאכי' דאצי' בים העליון שזהו כמו דגים שמובלעים בים וכמו עובר<sup data-n=\"1843\">30</sup> שהוא ירך אמו ואוכל<sup data-n=\"1844\">31</sup> ממה שאמו אוכלת כו' כידוע בבחי' עיבור הנשמות במל' כו' וד\"ל.\n<b>אך</b> בחי' ארבין הוא עד\"מ הספינה גשמי' שהולכת ע\"ג הים שההולכים בהם הם בנ\"א שחיים מן האויר וא\"א להם לחיות כלל בים אך כדי שיוכלו לעבור בים עושים להם ספינות שהם עשוים להגביל על מי הים שלא ישטפו על בנ\"א כי גם שהספינות שקועות קצת במים אבל עיקרם שטים ע\"פ המים ואין להם חיבור עם",[["1837","24","<b>בזהר שבבחי' ים העליון יש נונין וארבין</b>: זח\"ב מח, ב (הובא לעיל)."],["1838","25","<b>כמ\"ש בזוהר בכמה דוכתי</b>: ראה זח\"א בהקדמה ו, א. זח\"ג קפח, א. וראה ביאוה\"ז קמט, א. סידור עם דא\"ח קה, א. סה\"מ תקס\"ה ע' תרחץ. תו\"ח בראשית ד, ד. מאמרי אדהאמ\"צ בראשית ע' קנא. וש\"נ."],["1839","26","<b>כמש\"א רשב\"י בחד קטירא אתקטרנא כו' בי' אחידא בי' להיטא</b>: ראה זח\"ג רפח, א. רצב, א. ובהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' שכט."],["1840","27","<b>למה ת\"ח נמשלו לדגים שבים</b>: ראה ברכות סא, ב. ע\"ז ג, ב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' א'כד. ובתו\"ח לך לך צו, א."],["1841","28","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["1842","29","<b>וגם יש להם חומר גופני כמו אש ורוח כידוע</b>: ראה סידור ערה, ד (בשם ס' שער הגמול להרמב\"ן). ובכ\"מ."],["1843","30","<b>עובר שהוא ירך אמו</b>: גיטין כג, ב. ובכ\"מ."],["1844","31","<b>ואוכל ממה שאמו אוכלת</b>: נדה ל, ב."]]],[2101920322,"הים כלל כי הספינות עשויות מעצים שצומחין בארץ רק מחמת יסוד הרוח שבהם המה שטים ע\"פ המים ואמנם עיקר המעלה הוא לעשות הבדל ומסך שלא ישקעו בנ\"א בים ויוכלו גם הם לעבור על הים ולחיות בו ועי\"ז יש חיבור לברואים שביבשה לעבור בים ולא ימותו מפני מימי הים כי הספינה מפסקת, וכך יובן ממש בבחי' ארבין עליונים שהם בחי' מלאכים רוחניי' עשוים להבדיל ולהפסיק על ים העליון שיוכלו נשמו' דבי\"ע לעבור שם ולא ישקעו ויבלעו בים העליון ויתבטלו לגמרי, וז\"ש שם אניות יהלכון כו' שהם בחי' מלאכי' רוחניי' שנעשי' כמו בחי' ספינה לעבור בה נשמות עליונות שהם מעלמא דאתגליא בים העליון כמ\"ש בגוהרקי<sup data-n=\"1845\">32</sup> דר' חייא כו' כמ\"ש במ\"א באריכות, כי המלאכים אינם מתבטלי' במל' דאצי' כמו נשמו' דאצי' כי שרשם מבחי' אותיו' הדיבור שנמשך מאין ליש גמור וע\"כ יש להם גוף בבחי' יש גמור כנ\"ל ויש<sup data-n=\"1846\">33</sup> מלאכי' שנק' עצים כמ\"ש אז ירננו כל עצי היער ועושין מהן ארבין לנשמות שבעלמא דאתגליא שיוכלו לעבור בים העליון כו' וכמ\"כ מאצי' לבי\"ע מתלבשים נשמו' דאצי' בלבוש המעלי' עליהם שיוכלו להיות<sup data-n=\"1847\">34</sup> ביבשה בחי' עלמא דאתגליא ולא ימותו כו' וכמ\"ש במ\"א וד\"ל.\n<b>ומעתה</b> יש להבין בשרש ענין קרי\"ס מהו, דהנה כתיב ובנ\"י<sup data-n=\"1848\">35</sup> הלכו ביבשה בתוך הים דמשמע<sup data-n=\"1849\">36</sup> שעיקר הנס היינו מה שנהפך ים ליבשה כמ\"ש הפך ים ליבשה כו' וזהו שאמר שהלכו בנ\"י ביבשה בתוך הים שעיקר הרבותא שהים נעשה בחי' יבשה שזהו למעלה ענין גילוי בחי' ההעלם, שבחי' ים העליון הוא בחי' ההעלם וההסתר של בחי' דיבור העליון על בחי' אורו' העליונים שבאים ונמשכי' בו כנ\"ל וכאשר ההעלם נעשה בחי' גילוי נק' זה בשם קי\"ס העליון כמו שנקרע ים התחתון ונהפך לבחי' יבשה כו' ואז יוכלו כל האורות העליונים דאצי' לבוא בבחי' גילוי בבי\"ע כי אין להם בחי' מסך מבדיל ועד\"מ כמו שהיו יכולי' בריות שבים לעלות ליבשה לולי שהים מכסה עליהם כנ\"ל ולמעלה היינו שאין בחי' דיבור העליון מכסה ומעלים על בחי' אורו' עליונים שנמשכים בו מבחי' המדות וחכ' ורצון כו', ובל' המקובלי' נק' זה באופן אחר והוא בחי' עיבור ולידה שהנשמו' דאצי' כלולין במל' דאצי' שנק' ים בבחי' עיבור כמו עובר שירך אמו הוא כו' בתכלית ההתכללות ואח\"כ יוצאים לידי גילוי בבי\"ע בבחי' לידה וזהו ענין קרי\"ס כמו פתיחת וקריעת הרחם להוליד נשמות וכמ\"ש קול<sup data-n=\"1850\">37</sup> ה' יחולל אילות כו' וזהו עד<sup data-n=\"1851\">38</sup> יעבור כו', ולפ\"ז מ\"ש ובנ\"י הלכו כו' היינו בחי' נשמות שיצאו",[["1845","32","<b>בגוהרקי דר' חייא</b>: ב\"מ פה, ב. וראה מאמרי אדה\"ז עה\"ת ח\"א ע' שעט. ס' מאמרי אדהאמ\"צ נ\"ך ע' תעח. ובהמ\"מ שם."],["1846","33","<b>ויש מלאכים שנק' עצים כמ\"ש אז ירננו</b>: תהלים צו, יב. וראה גם ס' מאמרי אדה\"ז ”אתהלך לאזניא\" ע' לח. סה\"מ תקס\"ה ח\"ב ע' תשפא. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'קיד. וש\"נ."],["1847","34","<b>להיות ביבשה . . וכמ\"ש במ\"א וד\"ל</b>: ניתוסף מכת\"י ב. ובכת\"י א: לחיות (וליתא יותר)."],["1848","35","<b>ובנ\"י הלכו ביבשה</b>: בשלח יד, כט."],["1849","36","<b>דמשמע שעיקר הנס . . בתוך הים</b>: ניתוסף ע\"פ כת\"י ב."],["1850","37","<b>קול ה' יחולל אילות</b>: תהלים כט, ט."],["1851","38","<b>עד יעבור</b>: בשלח טו, טז."]]],[2101920323,"בבחי' לידה בגילוי שנק' יבשה בתוך הים לפי שהים נפתח ונקרע עד שבא לידי גילוי כו', והיינו שאמרו שאפי'<sup data-n=\"1852\">39</sup> שפחה ראתה על הים מה שלא ראה יחזקאל כי הי' כ\"כ עוצם גילוי אורות דאצי' בבי\"ע עד שנמשך בחי' גילוי הנבואה לשפחה בים מה שלא ראה יחזקאל כו', כי נבואת יחזקאל הוא בבחי' היצי' אחר הבדלת המסך הנק' ים ונק' רקיע כו' כנ\"ל וד\"ל.\n<b>והנה</b><sup data-n=\"1853\">40</sup> יש פי' שני במ\"ש ובנ\"י הלכו כו' שעיקר הרבותא הוא מה שהלכו גם בתוך הים ביבשה דהיינו שגם בבחי' ים העליון שהוא בחי' העלם שם הלכו ביבשה, וזהו להיפך מפי' הא' שההעלם נעשה גילוי כו' אלא הענין הוא שבחי' הגילוי עלה ונכלל בבחי' ההעלם להיות גם שם בחי' הגילוי דיבשה וז\"ש שהלכו ישראל ביבשה בתוך הים שגם בבחי' ההעלם דים הלכו שם בבחי' גילוי ויבשה כו', וזהו הפי' המובן לכאורה ממאמר הזוהר הידוע כמו כד<sup data-n=\"1854\">41</sup> סליק ימא גלגלוהי כו', שזהו ענין בחי' העלאת הנשמו' דבי\"ע שעלו בבחי' אור האצילות, ופי' בנ\"י הן הנשמו' דבי\"ע הלכו ביבשה כמו שהן בבחי' הגילוי שלהם בתוך הים בעולם העליון דאצי', ולפ\"ז לכאורה לא נהפך ונקרע הים והלא כתיב ויבקעו<sup data-n=\"1855\">42</sup> המים כמ\"ש הפך ים ליבשה. אמנם הענין הוא דבאמת ליכא נפקותא כלל בענין גוף הדבר בב' הפירושי' הללו דבין כך ובין כך הכל הי' ע\"י ענין בחי' קי\"ס דוקא דהיינו שבחי' אותיות המפסיקים ומכסים לאורו' עליונים וגם ממילא נעשה כיסוי והעלם זה עצמו לגבי אורות התחתונים דבי\"ע שחסד ומל' נקרעו ונבקעו באופן שלא יסתיר ויכסה כלל ואז ממילא יש חיבור לאורות עליוני' עם אורות תחתונים בין ע\"י ירידת אור העליון למטה בין בעליו' אור התחתון למעלה ואין נ\"מ בזה כלל רק לענין אופן ההתגלות לבד אם נתגלה מלמעלה למטה או מלמטה למעלה הוא דאיכא נפקותא בזה אבל בגוף הענין שהוא בחי' ההתגלות בלי הבדל ומפסיק בזה אין נפקותא לב' הפירושי' דבין כך ובין כך לא הסתיר בחי' הדיבור שנק' ים ונתגלה מה שכמוס בתוכו, רק לפי' האריז\"ל עיקר גילוי זה מלמעלה למטה שהוא גילוי אורות דאצי' לחוץ בבי\"ע ולפי' הזוהר היינו שעלו נשמו' דבי\"ע באצי' מפני שאין עליהם בחי' כיסוי והסתר למנוע עלייתן כו' וד\"ל. (ואפשר דשניהם אמת ולא סתרי אהדדי כלל, כי מאחר שנבקע המסך הרי יש ב' דרכי' א' דרך העליון אל התחתון והב' דרך התחתון להעליון ושניהם נק' הליכה רק שזה עולה וזה יורד ועל שניהם יתפרש ובנ\"י הלכו כו').",[["1852","39","<b>שאפי' שפחה ראתה על הים</b>: ראה מכילתא בשלח טו, ב."],["1853","40","<b>והנה יש פי' שני במ\"ש ובנ\"י הלכו כו'</b>: ראה בכ\"ז זח\"ב מח, ב. פע\"ח שער חגהמ\"צ (שכ\"א) פ\"ח. סידור עם דא\"ח רפט. מאמרי אדהאמ\"צ ויקרא ח\"א ע' ריב ואילך וע' רנ ואילך. שער האמונה לאדהאמ\"צ עא, ב. פד, א. פו, א ואילך."],["1854","41","<b>כד סליק ימא גלגלוהי</b>: זח\"ב מח, ב (נסמן לעיל)."],["1855","42","<b>ויבקעו המים</b>: בשלח יד, כא."]]],[2101920324,"<b>אך</b> הנה גם לב' הפירושים הי' צריך שיקרע הים לי\"ב גזרי' וקרעים דוקא למספר י\"ב שבטי בנ\"י דוקא, כי הנה ידוע שכללות מספר בנ\"י שהם בחי' נשמות דבריאה שמקבלים מבחי' מל' דאצי' הנק' ימא תתאה כו' הן י\"ב שבטי' והתכללותם הראשון הוא רק ארבעה דגלי' דגל מחנה ראובן כולל ג' שבטים כו' שהן<sup data-n=\"1856\">43</sup> ד' מחנות שכינה למעלה כמו בכתות המלאכי' בחיצוני' העולמו' שנחלקים ג\"כ לד' והד' נחלקים לי\"ב מחנות מחמת כ\"א נחלק לג' דוקא כמ\"ש בים<sup data-n=\"1857\">44</sup> של שלמה שהוא עומד על י\"ב בקר והים עומד עליהם מלמעלה כו' וי\"ב הבקר הללו ג' לכל צד בד' צדדים כידוע כמ\"כ הוא למעלה בד' מחנו' שכינה מחנה מיכאל מחנה גבריאל מחנה רפאל מחנה אוריאל מזרח ומערב צפון ודרום ד' סטרי עלמא וכל מחנה כוללת ג' כו' והן י\"ב מחנות ושרשם למעלה הוא בחי' י\"ב<sup data-n=\"1858\">45</sup> גבולי אלכסון שבבחי' ו\"ק מזרח ומערב כו' וכמ\"כ בעולם האצי' כללותם הראשון הוא רק ארבעה ונחלק כ\"א לג' עד שהן י\"ב שבטים בנשמו' דאצי' וי\"ב מחנו' במלאכי' דאצי' ושרשם י\"ב גבולי אלכסון שבבחי' ו\"ק דאצי' כו' וז\"ש ששם<sup data-n=\"1859\">46</sup> עלו שבטים שבטי י\"ה כו' ב' מיני שבטים שבטים שבמל' ובחי' שבטי י\"ה דז\"א כו' וד\"ל כידוע. אך הטעם לזה שנחלק כ\"א לג' דוקא הנה זה יובן ממה שאנו רואים שיש ג'<sup data-n=\"1860\">47</sup> פרקין בידים וברגלי' כמו פרק העליון שביד הוא האצבעות והוא בחי' חב\"ד שביד שהרי יש בהן הארת השכל ברמז או לכתוב דבר חכמה כו' ופרק האמצעי הוא בחי' חג\"ת שבו כו' ונמצא ג' פרקין דיד ימין שהן חב\"ד חג\"ת נה\"י שבחסד דרועא ימינא ובחי' ג' פרקין שביד השמאל גבורה דרועא שמאלא הן ששה וכמ\"כ ששה ג' פרקין שברגל ימין וג' פרקין שברגל שמאל כו' הרי שנים עשר מדריגות לפי שמתכללי' חו\"ג ונה\"י שהן הידים והרגלי' כ\"א מג' מדריגות דוקא שהוא בחי' חב\"ד חג\"ת כו' וכמו שבאדם כו' כך למעלה הנה בבחי' ו\"ק דאדם העליון יש התכללות זה וע\"כ גם הנשמו' והמלאכים שמקבלי' מזה הן נחלקים לי\"ב דוקא דהיינו ד' בכלל וכל א' לג' כנ\"ל בים של שלמה, וד' מחנות שלמטה הם ד' דגלי מדבר כידוע וד\"ל.\n<b>אמנם</b> עכ\"פ בשעה שהלכו בנ\"י בתוך הים הנה לב' הפי' הנ\"ל הי' צריך שיקרע הים לי\"ב גזרים וקרעים לכל שבט גזר וקרע מיוחד שיעבור בו מאחר שנאמר ששם עלו שבטים שבטי י\"ה כו' הרי כמו שלמטה בעולם הבריאה י\"ב שבטים כך למעלה י\"ב שבטים באצי' ולפ\"ז הי' צריך שיקרע הים לי\"ב קרעים וגזרים בין בשביל גילוי אורות עליונים דאצי' בבי\"ע שמתגלים מבחי' ו\"ק דאצי'",[["1856","43","<b>שהן ד' מחנות שכינה</b>: ראה זח\"ג קיח, ב. ביאוה\"ז לכ\"ק אדהאמ\"צ פה, א. ולכ\"ק אדמו\"ר הצ\"צ ע' תנא."],["1857","44","<b>בים של שלמה שהוא עומד על י\"ב בקר</b>: ראה מלכים א ז, כה. זח\"א רמא, א."],["1858","45","<b>י\"ב גבולי אלכסון</b>: ראה בפרטיות בפרדס שכ\"א (שער פרטי השמות) פ\"ו ואילך."],["1859","46","<b>ששם עלו שבטים</b>: תהלים קכב, ד. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' רעח ואילך. שערי תשובה מב, ג."],["1860","47","<b>ג' פרקין בידים</b>: ראה זח\"א רמא, א. וראה גם סה\"מ תקס\"ח ח\"א ע' שעה. מאמרי אדהאמ\"צ נ\"ך ע' שכג וע' שמו. סה\"מ תרמ\"ז ע' נו ואילך. ובכ\"מ."]]],[2101920325,"שנחלקים לי\"ב שבטים עליונים דאצי' שבהכרח להיות מקום מעבר לכל א' בפ\"ע בים העליון שיעבור בו מלמעלה למטה מאחר שכ\"א מובדל מזולתו והוא מדריגה מיוחדת בפ\"ע דוקא הרי צריך שיהי' לו דרך ומעבר בפ\"ע כמו גם שלשה שמסט' דחסד כ\"א צריך דרך ומעבר בפ\"ע כמו הילוך הדגלים או כמו י\"ב בקר שכ\"א מדריגה בפ\"ע, ובין בבחי' ההעלאה שעולין בחי' הי\"ב שבטים שבבריאה באצי' כפי<sup data-n=\"1861\">48</sup> פי' השני המובן בזוהר צריך להיות ג\"כ דרך ומעבר לכ\"א לעלות בו בפ\"ע כי כאו\"א מקבל שפעו בפרטיות בהבדל מזולתו וע\"כ כאשר נקרע בחי' ים העליון צ\"ל לכ\"א קרע מיוחד אליו שיעלה בו, כי יש שרש לכ\"א באצי' מובדל מזולתו שלא יוכל לעלות שם במסילה של זולתו ולכן נקרע הים לי\"ב קרעים דוקא כו' וד\"ל. וכמ\"כ עכשיו בענין התפילות מכללות נש\"י הרי<sup data-n=\"1862\">49</sup> י\"ב שערים למעלה שתפילת כל שבט עולה בשער המיוחד אליו, וכן בענין ירידת אור השפע ע\"י התפילות מאצי' לבי\"ע ג\"כ נמשך לכל שבט ע\"י שער המיוחד אליו כי לכ\"א שפע מיוחדת ודרך מיוחד בשער השייך אליו, מלבד שער הי\"ג שכולל כולם שע\"י יוכלו כללות נש\"י לעלות בו וגם ע\"י יוכל להיות ירידת השפע כו' להיותו כולל כולם והוא שער<sup data-n=\"1863\">50</sup> הפונה קדים כו'.\n<b>וזהו</b> לגוזר י\"ס לגזרים לי\"ב גזרים דוקא כל\"ח, כי צ\"ל בחי' חיבור ויחוד מאצי' לבי\"ע כדי שיומשך תמיד בחי' חסד עליון להחיות רוח שפלים דבי\"ע כו' וכמ\"ש כי<sup data-n=\"1864\">51</sup> אמרתי עולם חסד יבנה כו' ואם הי' בחי' זה ההעלם דים העליון מבדיל תמיד לא הי' נמשך חסד עליון לעולם הנברא יש מאין וגם לא היו יכולים הנבראים לעלות ולהתכלל ביחוד העליון כו' ע\"כ אמר דמה שגוזר י\"ס לגזרים הוא משום כל\"ח וד\"ל.\n<b>ומעתה</b> הנה יש להבין עוד מה שייכות יש לקרי\"ס למתן תורה שבשביל מתן תורה הוצרך להעבירם בי\"ס דוקא כנ\"ל, אך הנה שרש הענין הוא דקרי\"ס הי' תועלת גדול בנפשם לכשיהיו בהר סיני שעי\"ז יהיו יכולים לקבל התו', לפי שענין קבלת התו' בכלל הרי היא המשכת גילוי אא\"ס בחכ\"ע שנמשך למטה בחכ' תתאה בחי' המל' שהיא כנ\"י וזהו שנק' קבלת התו' שקבלו בנ\"י מאא\"ס שבחכ\"ע כו' והיינו ממש כדוגמת גילוי האורות עליונים דאצי' בבי\"ע כמו בי\"ב מחנות שכינה ובד' דגלי' וכה\"ג שא\"א להיות זה כ\"א ע\"י קרי\"ס העליון בתחילה שהוא כמו בחי' בקיעת הפרסא המבדיל בין אצי' לבריאה כו' ואם לאו לא",[["1861","48","<b>כפי פי' השני המובן בזוהר</b>: ראה לעיל פיסקא: והנה יש שני פי'."],["1862","49","<b>הרי י\"ב </b> [תוקן ע\"פ כת\"י ב. ובכת\"י א: יג]<b> שערים למעלה שתפילת כל שבט עולה בשער המיוחד אליו</b>: ראה פע\"ח שער התפילה (ש\"א) בהקדמה. לקו\"א להה\"מ סקל\"ג (ובמ\"מ לשם). שו\"ע אדה\"ז הל' ק\"ש סס\"ח ס\"ב. מאמרי אדה\"ז הקצרים ע' תקפא. תו\"ח נח עד, א (ובהמ\"מ שם). וישב ריא, ג. שער הכולל בהקדמה."],["1863","50","<b>שער הפונה קדים</b>: יחזקאל מו, א. ועוד."],["1864","51","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."]]],[2101920326,"היו יכולים להגיע לבחי' ומדריגת זה דקבלת התו' פב\"פ כו', וגם לפי' הב' שהליכתן ביבשה בתוך הים הי' ענין עליות הנשמו' דבריאה באצי' שזה ג\"כ א\"א בלי קרי\"ס דוקא כו' וד\"ל.\n<b>אך</b> הנה עיקר ענין קבלת התו' אז הי' רק בבחי' המשכת אא\"ס בחכ\"ע וחכ\"ת בשביל בחי' המעשה דוקא והוא תו' הנגלי' לנו בענין קיום המצות מעשיות בפ\"מ היום<sup data-n=\"1865\">52</sup> לעשותם דוקא ות\"ת<sup data-n=\"1866\">53</sup> כנגד כולם הכל בבחי' הנגלה הבא למטה בעוה\"ז בחי' עלמא דאתגלייא בהתלבשות בדברים גשמיי' דוקא כי אורייתא<sup data-n=\"1867\">54</sup> סתים וגליא כו' כידוע וחלק הנגלה הוא ענין החכ' שבה שבאה בהתלבשות חיצוני' ברמ\"ח מ\"ע ושס\"ה ל\"ת בגשמיות כידוע אבל חלק הנסתר שבה הוא הנקרא פנימי' התו' כו' שעל זה א' ולמחר<sup data-n=\"1868\">55</sup> לקבל שכרם למחר דוקא בעוה\"ב שיומשך לכנ\"י בחי' פנימיות התו' שזהו ענין התגלות טעמי מצות וסודות שעכשיו הם כמוסים ונעלמים למעלה מעלה גם באצי' כי גם למשה א' ופני<sup data-n=\"1869\">56</sup> לא יראו בחי' פנימית התורה כמו שהוא כמוס עמדי בעצמיו' אא\"ס שלמעלה מהחכ' והוא בחי' תענוג הנעלם שבעצמותו שהוא בבחי' ההעלם גנוז בתורה בלתי נגלה בבחי' החכ' גם לא בבחי' ח\"ס והוא הנק' עדן סתימאה שנאמר בו עין<sup data-n=\"1870\">57</sup> לא ראתה אלקים זולתך כו' וכדפירש\"י<sup data-n=\"1871\">58</sup> ע\"פ ישקני מנשיקות פיהו שהן טעמי תו' כו' שלא יתגלו לישראל רק לעתיד בימוהמ\"ש דוקא דכתיב בו הנה<sup data-n=\"1872\">59</sup> ישכיל עבדי ירום ונשא כו' שזהו בחי' גילוי עצמי' אא\"ס שמאיר במלכא משיחא שעל ידו יומשך בחי' טעמי תו' לישראל וזהו ישכיל עבדי להשכיל לישראל מבחי' טוב טעם ותענוג הנעלם שבמצות שלא נתגלו עד כאן גם למשה והאבות וכה\"ג וזהו ירום כו' למעלה מן האבות עד וגבה<sup data-n=\"1873\">60</sup> מאד היפך אותיות דאדם שהוא למעלה מבחי' אדם שנק' אדם קדמאה בחי' אור החכ' כי<sup data-n=\"1874\">61</sup> אדם בגי' מ\"ה וכתיב מה<sup data-n=\"1875\">62</sup> שמו כו' והוא למעלה מבחי' משה שע\"י משה ניתנה תו' הנגלית לנו וע\"י משיח יומשך ויושפע לישראל בחי' פנימי' התו' שארוכה<sup data-n=\"1876\">63</sup> מארץ מדה בעליות רבות במדריגות הפנימיות שבעולם הא\"ס עד אין קץ ושיעור להיותה למעלה מן החכ' כו' וזהו שכתוב עין לא ראתה רק אלקים זולתך בבחי' הא\"ס ממש, וגם פירוש הפשוט מורה כך שהרי בימוהמ\"ש ותחה\"מ יקומו הכל ויהי' לאלפי אלפים רבבות כו' ואיך ילמוד עם",[["1865","52","<b>היום לעשותם</b>: ואתחנן ז, יא. עירובין כב, א."],["1866","53","<b>ות\"ת כנגד כולם</b>: פאה ריש פ\"א."],["1867","54","<b>אורייתא סתים וגליא</b>: זח\"ג עא, ב. עג, א."],["1868","55","<b>ולמחר לקבל שכרם</b>: עירובין שם."],["1869","56","<b>ופני לא יראו</b>: תשא לג, כג."],["1870","57","<b>עין לא ראתה</b>: ישעי' סד, ג."],["1871","58","<b>וכדפירש\"י ע\"פ ישקני מנשיקות פיהו</b>: שה\"ש א, ב. וראה ס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תעג ואילך. ס' שער האמונה לאדהאמ\"צ ג, ב (ובהמ\"מ שם)."],["1872","59","<b>הנה ישכיל עבדי</b>: ישעי' נב, יג. וראה ת\"י וילקו\"ש שם."],["1873","60","<b>וגבה מאד היפך אותיות דאדם</b>: ראה זח\"ג רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["1874","61","<b>כי אדם בגי' מ\"ה</b>: ראה ע\"ח שער התיקון (ש\"י) פ\"ג. ובכ\"מ."],["1875","62","<b>מה שמו</b>: משלי ל, ד."],["1876","63","<b>שארוכה מארץ מדה</b>: איוב יא, ט."]]],[2101920327,"כולם התו' הנגלית, ועוד שבודאי גם משה והאבות ודורות הראשונים שהיו יודעים את התו' כולה יקומו ולמה יצטרכו לקבל ממשיח ללמוד התו' הנגלית כו', אלא הענין הוא שילמד דעת לכולם מבחי' פנימי' התו' הנ\"ל ואשר עין לא ראתה עדיין רק אלקים יעשה למחכה לו ע\"י משיח דכתיב בי' וגבה מאד כו' וד\"ל.\n<b>והנה</b> כמו שמבואר למעלה בענין קבלת התו' הנגלית בהר סיני שהוצרך להעביר את ישראל בים תחילה מטעם הנ\"ל שיהי' בחי' בקיעת המסך תחילה שיוכל להיות גילוי ההעלם כו' ועי\"ז יוכלו לקבל התו' בחיצוני' בקיום המצות בהעלאות והמשכות מאצי' לבריאה ומבריאה לאצי' כמ\"כ ממש לעתיד כשיצטרכו להגיע למדריגת קבלת התו' בפנימי' ע\"י משיח כנ\"ל יצטרכו לעבור בנהר פרת כו' וכמו שהוצרכו לעבור בים דוקא לצורך קבלת התו' בנגלה מסיני כך יצטרכו לעבור בנהר פרת דוקא לעתיד בשביל קבלת התורה בנסתר שנק' עדן אשר עין לא ראתה כו'. וזהו מ\"ש עד<sup data-n=\"1877\">64</sup> יעבור עמך הוי' עד יעבור עם זו כו' ולא כתיב בהעברה זאת השני' שם הוי' אלא עד יעבור סתם, כי העברה הראשונה עד יעבור עמך ה' זהו מה שעברו בים בשביל קבלת התו' בנגלה שהוא בבחי' שם הוי' דחכ' כמ\"ש ויאמר<sup data-n=\"1878\">65</sup> הוי' אל משה כו', אבל עד יעבור הב' קאי לעתיד בימוהמ\"ש ותחה\"מ שיהי' בנהר פרת בשביל פנימי' התו' שלמעלה משם הוי' דחכ' כו' ע\"כ א' עד יעבור סתם שהוא בחי' עצמו' אא\"ס ממש שנק' סדכ\"ס דלא<sup data-n=\"1879\">66</sup> ידע לי' בר איהו כו' כמ\"ש אלקים זולתך כו'. וזהו מ\"ש הפך ים ליבשה דקאי בקי\"ס שקודם מתן תו' הנגלית ואח\"כ לעתיד יעברו בנהר פרת בשביל פנימית התורה ואז א' שם נשמחה בו ממש עד שאז לא יזכר יצי\"מ וקי\"ס רק בדרך טפל בעלמא וכמו שא' כל<sup data-n=\"1880\">67</sup> ימי חייך להביא לימוהמ\"ש כו' וד\"ל.\n<b>ולהבין</b> ביאור ענין העברה שני' לעתיד בנהר פרת דוקא הנה יש להקדים תחילה במ\"ש ונהר יוצא מעדן כנ\"ל זהו בחי' המח'<sup data-n=\"1881\">68</sup> שנק' נהר שיוצא בתמידות מבחי' החכ'<sup data-n=\"1882\">69</sup> הנק' עדן כו'. וביאור זה הנה מבואר למעלה בבחי' הדיבור העליון שנק' ים כמ\"ש כל הנחלים הולכים אל הים שהוא כל בחי' המחשבות נמשכים ומתלבשים בדיבור וכל המדות והשכל וגם הרצון והתענוג אותיות הדיבור מכסה ומעלים עליהם לבלתי הגלות נגלות לחוץ כמו שהן, כך למעלה כל בחי' אורות העליונים דחו\"ב וע\"י ובחי' המדות דז\"א כולם מתעלמי' תוך הדיבור דעשרה מאמרות בדבר ה' שמים כו' וככה ממש הוא בחי' אותיות המח' עליונה כי כמו שיש בחי' דיבור למעלה אע\"פ שאין דיבורו כדיבורינו כו' כך יש בחי' אותיות",[["1877","64","<b>עד יעבור עמך ה'</b>: בשלח טו, טז (הובא לעיל)."],["1878","65","<b>ויאמר ה' אל משה</b>: בשלח יד, טו. ועוד."],["1879","66","<b>דלא ידע לי' בר איהו</b>: ראה זח\"ב רי, ב. זח\"ג קכט, ב. קמ, ב. רפח, א."],["1880","67","<b>כל ימי חייך להביא לימוהמ\"ש</b>: נסמן לעיל."],["1881","68","<b>המח' שנק' נהר</b>: ראה גם תו\"א נח ט, ב. לקו\"ת שה\"ש יז, ג. ובכ\"מ."],["1882","69","<b>החכ' הנק' עדן</b>: ראה זח\"ג רצ, א. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתסד."]]],[2101920328,"המח' אע\"פ שנאמר כי<sup data-n=\"1883\">70</sup> לא מחשבותי מחשבותיכם, מ\"מ עכ\"פ זה מובן שבחי' המח' ג\"כ בחי' כיסוי והעלם לכל האורות העליונים שמתלבשים בה כמו שהשכל<sup data-n=\"1884\">71</sup> והשגה שהיא בחי' רוחניות ההשכלה הרי כשמתלבשת באותיות המחשבה הרי המחשבה נעשה כמו לבוש ממש להעלים ולהסתיר אור השכל הרוחני לבלתי הגלות נגלית בבחי' עצם מהותו כמו שהוא ממש וכן גם המדות שבלב רוחני' הם בלב וכשבאין ומתלבשי' במחשבה הרי נתפסים ומתעלמים בבחי' לבוש המח' כאדם שמלביש א\"ע כו' וראי' לכ\"ז שהרי א\"א שיבוא גילוי אור השכל והמדות כמו שהן למטה להיות נתפסים באיזה מציאות דבר שכל או מדה כ\"א ע\"י המח' שבאמצעות המח' דייקא הם נתפסים במציאות דהיינו ע\"י בחי' הרהורי אותיו' במח' שתופסים בתוכם לבחי' אור השכל והמדות כו' וכאשר נתפסים ע\"י המח' ה\"ז כמו בחי' כיסוי והעלם עליהם [כמ\"ש במ\"א בענין אש מים רוח דאגלידו מיא כשנתפס ההשגה במח' ואע\"פ שהבינה וההשגה עצמה נק' נהר כידוע אין זה רק בעצם מהות השגת שכל כמו שהוא אבל בחי' המשכתן והתפשטותן הוא כשבא בבחי' אותיות המח' דוקא הוא שמתרבה ומתפשט ברוב ענינים חלוקים ונמשכים מזה לזה כו'], וזהו הטעם שהמח' נק' נהר כי נהר לשון המשכה והתפשטות הוא ודוקא שיוצא ונמשך בתמידות בלי הפסק כמו ונהרו<sup data-n=\"1885\">72</sup> אליו כל הגוים כו' כמו שאנו רואים שהמח' היא תמידית שהרי המח' משוטטת תמיד בכל רגע השקט לא תוכל כי בתמידות עוברת רעיונות המח' בכלי מוחו מכל דבר ודבר לא תנוח לעולם כמו שהנהר לא תנוח ויוצא ונמשך בתמידות בלי הפסק כלל, וענין נביעת והמשכת המח' בתמידות הוא מכח השכל שנק' חכ' שהרי הקטן<sup data-n=\"1886\">73</sup> אין לו מח' וכן הבהמה כו' וכל שדעתו וחכמתו יותר, יותר נקבע בו מחשבות עמוקות בתגבורת ההמשכה כמו נהר גדול שמתגבר בהתפשטותו מפני מעיינות שגוברים בבקיעתם מן הארץ כידוע<sup data-n=\"1887\">74</sup> דחכ' נק' מעיין כו', וכך יובן למעלה בבחי' המח' העליונה שנק' נהר שיוצא מעדן עילאה בחי' חכ' שמ\"ש ונהר יוצא מעדן היינו שיוצא תמיד בלי הפסק כלל, ואמנם בחי' המח' שנק' נהר הוא בחי' העלם וכיסוי על אורות עליונים דחו\"ב ומדות כו' וע\"כ הדיבור נק' ים כי מה שחושב במח' בא הכל בדיבור וזהו כל הנחלים הולכים אל הים אבל המח' נק' נהר ולא ים מטעם שהיא תמידית היא נמשכת ממקורה תמיד כו' משא\"כ הים שהוא הדיבור שאינו רק לפרקים כו' וד\"ל.\n<b>והנה</b> שרש ענין קיבול השכר דלעתיד בהתגלות לישראל בחי' פנימי' התו' ע\"י משיח כו' היינו שיהי' אז התגלות בחי' העצמי' והפנימי' דעדן העליון שהוא בחי' פנימי' ועצמי' דחכ\"ע שנק' עדן [כידוע<sup data-n=\"1888\">75</sup> דפנימי' אבא הוא בחי' פנימי'",[["1883","70","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["1884","71","<b>שהשכל והשגה . . בבחי' עצם מהותו כמו</b>: ניתוסף מכת\"י ב."],["1885","72","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב. וראה גם פרדס שכ\"ג (שער ערה\"כ) מע' יאור."],["1886","73","<b>הקטן אין לו מח'</b>: חולין יב, ב."],["1887","74","<b>כידוע דחכ' נק' מעיין</b>: ראה זח\"ב מב, ב. ובהמ\"מ במאמרי אדהאמ\"צ דברים ח\"ב ע' תתצב."],["1888","75","<b>כידוע דפנימי' אבא הוא בחי' פנימי' ע\"י</b>: ראה סה\"מ תקס\"ה ח\"ב ע' תתסה. וש\"נ."]]],[2101920329,"ע\"י שהוא בחי' פנימי' התענוג שבפנימי' החכ' כו'] וז\"ש עין לא ראתה אלקים זולתך יעשה למחכה לו זה עדן היינו לע\"ל דוקא שיתגלה טעמי המצות וסודותיהם כנ\"ל, ולכאורה י\"ל בזה למה דוקא לעתיד יתגלה ולא עכשיו. אך הענין הוא דעכשיו מעלים ומכסה על פנימי' החכ' בחי' ההשגה שבמח' שנק' נהר כנ\"ל בפי' ונהר יוצא מעדן, והיינו מה שפנימי' ועצמי' החכ' נתפס ע\"י אמצעית כלי ההשגה באותיו' המח' שזה הלבוש של ההשגה מסתיר הוא ומעלים לבחי' נקודה פנימי' של החכ' כמו שהיא במהותה ועצמותה ממש כנ\"ל. וביאור דבר זה יובן עד\"מ הידוע מכח המוליד ההיולי שבטיפה שהוא רוחני וכלולה מכל האברי' שמתפשטי' אח\"כ ובודאי מה שהאברים נגלים ונראים בהגשמה גמורה אין זה ערך לבחי' אור וחיות ההיולי שבטיפה שכלול מכל האברים ומ\"מ שם נמצאו אך בחי' האור ההיולי מוסתר בהם אחר שנעשית גשם כו' כן ממש בחי' נקודת אור החכ' כמו שהיא בבחי' עצמותה ממש היא רוחני והיולי ומה שנמשך מאין רוחני זה בחי' ההתפשטות של מהות ההשגה באותיו' ממש במח' ה\"ז כמו לבוש מעלים ומסתיר על בחי' נקודה העצמי' של החכ' אע\"פ שמכחו נמשך השגת השכל שבא במח' וכמו שנראה בחוש שכח נביעת המעיין עצמו מוסתר ונעלם ע\"י אמצעות הנהר המתפשט הימנו כי לא נודע גילוי מקורו מאין הוא נמשך ומתפשט מפני התפשטות הנהר שמכסה על מקורו אע\"פ ששרש הנהר ממקורו הוא בא כמ\"ש נהרא<sup data-n=\"1889\">76</sup> מכיפי' מיבריך כו', וכיוצא בזה יובן איך שנקודת החכ' עצמה מוסתר ונעלם במחשבת השגת השכל המלביש את נקודת החכ' כי מה שנתפס אור החכ' ע\"י אמצעי' השגה זו במח' אין זו תפיסת עצמותה ומהותה של החכ' כלל להיות כי מחשבת השגת השכל מסתרת ומעלמת על עצם נקודת אור החכ' והשכל ואינו נגלה כמו שהוא רק הארה חיצוני' ממנו הוא אשר נגלה ונתפס ע\"י השגה זו אע\"פ שמכח החכ' גם זאת ההשגה שבמח' באה מאין ליש כידוע שחו\"ב<sup data-n=\"1890\">77</sup> נק' תרין ריעין כדמיון מעיין ונהר או טיפה בולד וכה\"ג כו', וראי' לדבר זה ידוע ממה דלא<sup data-n=\"1891\">78</sup> קאים איניש אדעתי' דרבי' כו' גם ששמע והבין ההשגה אבל לא קאי על בחי' נקודה העצמי' שבשכל זה ששמע והשיג כו'.\n<b>ולהבין</b> דבר זה בתוס' ביאור, הנה ידוע שהחכ'<sup data-n=\"1892\">79</sup> נק' בשם ראי' והסתכלות ע\"כ נק'<sup data-n=\"1893\">80</sup> החכמי' עיני העדה כו' שהוא בחי' ראי' השכל כמו איזהו<sup data-n=\"1894\">81</sup> חכם הרואה את הנולד כו' ע\"כ חכם<sup data-n=\"1895\">82</sup> עדיף מנביא וכו' וגם בבחי' ההשגה של כל דבר",[["1889","76","<b>נהרא מכיפי'</b>: שבת סה, ב. וראה גם לקו\"ת שה\"ש לט, א."],["1890","77","<b>שחו\"ב נק' תרין ריעין</b>: ראה זח\"ג ד, א."],["1891","78","<b>דלא קאים איניש</b>: ע\"ז ה, ב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תמד."],["1892","79","<b>שהחכ' נק' בשם ראי'</b>: ראה פרדס שכ\"ג (שער ערכי הכינויים) מע' ראי'. יהל אור על תהלים ע' תתקנט. ובהמ\"מ בס' מאמרי אדהאמ\"צ הנחות תקע\"ז ע' כז."],["1893","80","<b>נק' החכמים עיני העדה</b>: ראה ע\"ח שער דרושי הנקודות פ\"א. אור תורה להה\"מ נג, ב. תניא אגה\"ק סי\"ד (קכ, ב). לקו\"ת ואתחנן ד, ב. מאמרי אדהאמ\"צ נ\"ך ע' קסד. וש\"נ."],["1894","81","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א."],["1895","82","<b>חכם עדיף מנביא</b>: ב\"ב יב, א."]]],[2101920330,"חכ' יש הפרש בין השגה דבינה שאינו רק מבין ומשיג את הדבר כו' ע\"י הסבר הקרוב אל השכל אבל לא שמשיג בעצם מהות הדבר כאלו רואה במהותו אך בחי' אור הראי' דחכ' שרואה ומשיג בעיני השכל לעצם הדבר במהותו הרי אז מה שצריך להאריך כמה שעות וזמנים בדברים רבים להסביר לזולתו יהי' נתפס ברגע קטן בסקירה אחת, וזהו שאינו<sup data-n=\"1896\">83</sup> דומה שמיעה לראי' שהשומע אינו משיג רק לפי מה ששומע הסבר הדברי' ולא יש לו השגה במהות הדבר ממש ע\"כ צריך לשמוע כמה ימים ועדיין לא נודע לו מהות הדבר משא\"כ הרואה רואה במהות הדבר ממש וברגע קטן רואה כל מה שיש בו מה שצריך לספר לזולתו ימים ושנים רבים כו' וד\"ל, כמ\"ש<sup data-n=\"1897\">84</sup> בכתבי האריז\"ל שפ\"א נכנס אצל האריז\"ל תלמידו הרח\"ו ז\"ל ומצאהו שהי' מנמנם ואמר לו האריז\"ל שברגע זאת שהי' מנמנם הי' משיג ורואה בסודות עמוקות ביותר עד שאם הי' צריך לגלות אותם בדיבור ובכתב הי' צריך לשהות זמן רב ערך פ'<sup data-n=\"1898\">85</sup> שנים כו' ולכאורה דבר זה פלא גדול איך יכולת המח' וההשגה לתפוס ברגע אחד מה שצריך לדבר או לכתוב פ' שנים, ואם מפני שאנו רואים דמה שצריך אדם לדבר שעה ושתים נתפס במח' במעט רגע<sup data-n=\"1899\">86</sup> כמו ב' או ג' רגעים ומה שצריך לדבר יום אחד נתפס במח' עכ\"פ בזמן יותר כמו רבע או חצי שעה עד שלערך<sup data-n=\"1900\">87</sup> שנה צריך לחשוב ערך כמה ימים וחדשים כו', ואיך אמר שנתפס ברגע אחד כי הלא המח' אינה אלא כלל הדיבור ואין בפרט אלא מה שבכלל אבל הפרט דומה לכלל ולפ\"ע ריבוי דברי הפרט כן ערך ריבוי הכלל אבל רגע לגבי ס' שנה אין זה לפ\"ע הכלל לגבי הפרט כו'.\n<b>אך</b> הענין הוא לפי שיש באופן ההשגה ב' מדריגות כנ\"ל הא' אשר הוא נתפס ומושג באמצעות ענין המח' שזהו ענין השגת שכל הנתפס ע\"י אותיו' המח' (ולאו דוקא אותיו' המח' הגשמיי' שמהרהר בהם גם מילי דעלמא דברים הפשוטים שאינם ענין שכלי אלא גם בחי' מח' העיוני' הרוחני' שנק' מחשבת שכל עיונית כשמחשב דבר חכ' שבמח' זו הוא עיקר תפיסת אור אותו השכל והסברא והוא מבחי' אחוריים דאימא ונק' ג\"כ בחי' מל' דתבונה ששרשה בבחי' בינה עצמה שהוא כח השגת שכל להשיגו בהסבר העיון העצמי ואותו ענין ההשגה דבינה הוא אשר נתפס במח' רוחני' זו הנק' מח' עיונית שמעיינת בדבר חכ'",[["1896","83","<b>שאינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לקח טוב שלח יג, יח. ובהמ\"מ בס' מאמרי אדהאמ\"צ שם ע' כז."],["1897","84","<b>כמ\"ש בכתבי האריז\"ל שפ\"א נכנס אצל האריז\"ל תלמידו הרח\"ו ז\"ל</b>: ראה פע\"ח שער ק\"ש שעהמ\"ט (שט\"ז) פ\"א. עמק המלך הקדמה שלישית פ\"ב (י, ב ואילך), ובשער רישא דז\"א פ\"ט (קכו, ג). ס' יסוד יוסף. וראה בארוכה ע\"ד שינויי הנוסחאות במעשה זה, בהנסמן בהמ\"מ לס' מאמרי אדה\"ז עה\"ת ע' רסד. שער האמונה לאדהאמ\"צ צב, ב ואילך. ס' מאמרי אדהאמ\"צ שמות ח\"א ע' ז. תו\"ח שמות קג, א."],["1898","85","<b>פ' שנים</b>: בכת\"י ב: ס' שנים. [ועד\"ז הוא בהכת\"י לקמן בסמוך]. ובפע\"ח ועמה\"מ הנ\"ל ”שמונים\". וראה בארוכה בהמ\"מ שבהערה הקודמת."],["1899","86","<b>במעט רגע</b>: בכת\"י ב: במעט זמן."],["1900","87","<b>שלערך שנה</b>: בכת\"י ב: שלס' שנה."]]],[2101920331,"לתופסה בה כו' וד\"ל). והב' הוא בחי' נקודת פנימי' המושכל עצמו כמו שהוא ממש ולא כמו שהוא מושג באמצעות המח' עיונית והוא הנק' בחי' ראי' והסתכלות בחכ' עצמה כמו שהיא וכמו שא' בזהר על בחי' החכ' בלשון הסתכלות כמו אסתכלנא<sup data-n=\"1901\">88</sup> ברזא דחכמתא כו' וגם באד\"ר<sup data-n=\"1902\">89</sup> שא' ר' חזקי' מסתכל הוינא כו' וא' לו ר\"ש נושא עון חמית ובודאי לא שמע<sup data-n=\"1903\">90</sup> ר' חזקי' בראי' דנבואה בי\"ג ת\"ד דא\"א דאצי' שהרי הנבואה<sup data-n=\"1904\">91</sup> אינה אלא בנו\"ה דז\"א דאצי' ולמטה בהתלבשות בבי\"ע כידוע, אך בחי' ראי' והסתכלות זאת הוא בחי' ראי' והסתכלות דחכ' שנק' בשם ראי' אור העין, וכנ\"ל בענין איזהו חכם הרואה את הנולד שאינו דומה שמיעה לראי' כו', דהיינו כל מה שיצטרך לבוא בהשגה עיוני' במח' במשך זמן רב רואה בראי' בסקירה והבטה א', וע\"כ יוכל להיות דמה שיצטרך להביא אור החכ' שראה בבחי' ראי' והסתכלות בבחי' ההשגה במח' העיוני' ומשם ילבישנה עוד באותיות המח' עד שיביאה באותיות הדיבור שיהי' צריך שיעור זמן ס' שנה מה שראה והסתכל בסקירה והבטה א' בראי' דחכ' כו' וכמו שאם הי' צריך ר' חזקי' לפרט ולבאר בחי' התיקון הזה דנושא עון שיהי' מושג בהשכלת והשגת שכלי במח' עיונית עד שיהי' נתפס באותיו' המח' והדיבור הי' צריך לדרוש זמן רב כמו שנה או שנתים כו' ולפי שאינו דומה כלל שמיעה דבינה והשגה באותיו' המח' והדיבור לבחי' הראי' דחכ' כמו שכאשר הרואה כרך גדול בכל פרטי חלקיו וצריך לפרש לזולתו שבודאי יאריך בסיפורו כמה ימים וחדשים עד שיפרש ויבאר היטב כל מה שראה והראי' הי' בסקירה אחת כו', וכך יובן בענין מעשה הנ\"ל במה שנזכר בשבחי האריז\"ל שא' לתלמידו הרח\"ו שמה שראה והשיג חכ\"ע בסודות עליונים ברגע א' בשינתו צריך לשהות זמן ס' שנה להביא הדבר בדיבור ובכתב כי בחי' סקירת עצמיות חכ\"ע כמו שהיא כשיצטרך להביאה ולהלבישה במח' ודיבור הרי מרגע א' שראה צריך לחשוב ולדבר ס' שנה ואין דבר זה גוזמא כלל כמובן מכל הנ\"ל.",[["1901","88","<b>אסתכלנא ברזא דחכמתא</b>: כן מובא בכ\"מ. וראה מאמרי אדהאמ\"צ שמות ח\"ב ע' תלז וע' תקמט. ויקרא ח\"א ע' שכט. במדבר ח\"ב ע' תרמז. דברים ח\"א ע' קמח וע' רסא. דרושי חתונה ח\"ב ע' תקנד. תו\"ח נח מג, ג. ועוד."],["1902","89","<b>באד\"ר שא' ר' חזקי' מסתכל הוינא</b>: ראה זח\"ג קלב, ב: קם ר' חזקיה שארי ואמר כו' מסתכל הוינא וארו חמית נהורא יקירא דבוצינא עלאה כו' אנא שאיל מהם פשרא דחמית פתחו ואמרו נושא עון חמיתא אמר דא הוא תקונא תניינא יתיב א\"ר שמעון האידנא אתקשר עלמא כו'. וראה גם שער האמונה לאדהאמ\"צ שם צד, א. אמרי בינה שער הק\"ש סד, ב. תו\"ח שמות ח\"א קב, ד. ח\"ב של, א. מאמרי אדהאמ\"צ דברים ח\"א ע' קמח. ובמאמרי אדהאמ\"צ דרושי חתונה שם ז\"ל: וכמו בהשגה ברזא דחכמה שהי' ברשב\"י ותלמידיו בפרצופים העליונים כמו בי\"ג ת\"ד דא\"א שא' [שאמרו] לר' חזקי' נושא עון חמית כו' וזהו לשון אסתכלנא ברזא דחכמתא שזהו בחכמה שבבחי' אין ממש כו'."],["1903","90","<b>שמע</b>: בכת\"י ב: ראה."],["1904","91","<b>הנבואה אינה אלא בנו\"ה דז\"א דאצי'</b>: ראה שער היחודים להאריז\"ל פ\"א. שער רוה\"ק דרוש א. סידור שער הק\"ש עט, א. אמרי בינה שם עא, א. ובכ\"מ."]]],[2101920332,"<b>ובכ\"ז</b> יובן ג\"כ ענין פנימיו' התו' שנק' טעמי תו' שהוא בחי' פנימי' ועצמי' דחכ\"ע כמו שהיא ממש בלי אמצעי' לבוש ההשגה דמח' בעיון ואותיות כו' הוא הנק' בחי' ראי' והסתכלות דחכ' שלמעלה מבחי' שמיעה והשגה דבינה כנ\"ל והוא ענין הסקירה וההבטה בבחי' עצמי' הדבר כמו שהיא ע\"ד הנ\"ל בהסתכלות דר' חזקי' או בהסתכלות דהאריז\"ל ברגע אחד כל מה שצריך להביא בהשגה ודיבור ס' שנה וכה\"ג והוא ענין גילוי טעמי המצות לעתיד דוקא כי עכשיו הרי לא נתפס ומושג רק ע\"י אמצעי' כלי ההשגה והמח' שהוא בחי' מסתיר ומעלים על בחי' פנימי' ועצמי' כו' וכמו גם בגעה\"ע דעכשיו בעולם הבריאה שהנשמות משיגים שם בהשגת אלקות בבחי' בינה והשגה ממש להיות שנמשך להם כח ההשגה רק מבחי' בינה שבמל' דאצי' כידוע דאימא<sup data-n=\"1905\">92</sup> עילאה מקננא בכורסיא אבל לעתיד כתיב כי<sup data-n=\"1906\">93</sup> עין בעין נראה אתה ה' וכתיב והיו<sup data-n=\"1907\">94</sup> עיניך רואות את מוריך בבחי' ראי' והסתכלות במהו\"ע דאא\"ס ולא כמו שהוא מושג בהשגה ומח' כנ\"ל והיינו ע\"י בחי' ראי' דחכ' וכמ\"ש ואמר<sup data-n=\"1908\">95</sup> ביום ההוא הנה אלקינו זה וכמו זה<sup data-n=\"1909\">96</sup> אלי ואנוהו לפי שמשה<sup data-n=\"1910\">97</sup> שרשו מבחי' ראי' דחכ' וע\"כ נאמר בו וירא<sup data-n=\"1911\">98</sup> ראשית לו וכמארז\"ל כל<sup data-n=\"1912\">99</sup> הנביאים נתנבאו בכה ומשה בזה כו' (וגם שבנביאים נאמר ג\"כ ואראה<sup data-n=\"1913\">100</sup> אבל ע\"י<sup data-n=\"1914\">101</sup> אספקלריא ומשה בלא אספקלריא א' כמ\"ש במ\"א), וזהו כל עיקר ענין קיבול השכר של הנשמו' לעתיד בגילוי בחי' טעמי תומ\"צ שיגלה להם משיח וילמוד אותם לכל ישראל וכמ\"ש הנה ישכיל עבדי כו' שענין לימוד זה לעתיד לא יהי' כמו עכשיו שלומדי' הדבר חכ' שיבוא בהשגה בטוב טעם עד שנתפס בעיון המח' כו' כמו השגות הנשמות בג\"ע אלא לימוד דלעתיד יהי' בבחי' ראי' והסתכלות שיראו כולם בעין ראית השכל אשר יצטרך לבוא בהשגה ומח' זמן רב כנ\"ל, וזהו פי' ישכיל מקור להשגה שכלי' שהשגה שכלי' אינו רק הארה חיצוני' ומסתרת ומכסה עלי' כנ\"ל אבל פי' ישכיל ה\"ז בחי' מקור לכל מיני שכל אנושי<sup data-n=\"1915\">102</sup> המושג, והיינו מה שישפיע בכנ\"י ג\"כ בחי' זו להיות כ\"א",[["1905","92","<b>דאימא עילאה מקננא בכורסיא</b>: ת\"ז ת\"ו (כג, א). וראה מאמרי אדהאמ\"צ דברים ח\"א ע' רסב. קונטרסים ע' תכג. וש\"נ."],["1906","93","<b>כי עין בעין נראה אתה ה'</b>: ע\"פ שלח יד, יד."],["1907","94","<b>והיו עיניך רואות את מוריך</b>: ישעי' ל, כ."],["1908","95","<b>ואמר ביום ההוא הנה אלקינו זה</b>: ישעי' כה, ט."],["1909","96","<b>זה אלי ואנוהו</b>: בשלח טו, ב."],["1910","97","<b>שמשה שרשו מבחי' ראי' דחכ'</b>: ראה בהמובא לקוטי שיחות ח\"ו ע' 244 ואילך."],["1911","98","<b>וירא ראשית לו</b>: ברכה לג, כא."],["1912","99","<b>כל הנביאים נתנבאו בכה</b>: ראה ספרי ר\"פ מטות."],["1913","100","<b>ואראה</b>: ישעי' ו, א. יחזקאל א, א. ועוד."],["1914","101","<b>ע\"י אספקלרי' ומשה בלא אספקלרי' א' כמ\"ש במ\"א</b>: בכת\"י ב: ע\"י ז' אספקלריאות ומשה בלא אספקלרי' א' כמ\"ש במ\"א. ילקו\"ש ויקרא עה\"פ א, א — רמז תלב (ככת\"י הב'). וראה לקו\"ת שה\"ש כב, ב: ולכן כל הנביאים ואפילו משה רבינו ע\"ה ראה באספקלריא אלא שמרע\"ה ראה באספקלריא אחת המאירה ושאר הנביאים דרך ז' אספקלריאות. וכ\"ה בשערי אורה לאדהאמ\"צ סו, ב. ובכ\"מ."],["1915","102","<b>אנושי</b>: בכת\"י ב' ליתא."]]],[2101920333,"משכיל ורואה ומסתכל בבחי' ראי' דחכ' כו' וע\"כ דוקא לע\"ל יתגלו טעמי המצות כמו שהן למעלה ע\"י משיח ולא עכשיו כו' וד\"ל. וזהו שנאמר גבי<sup data-n=\"1916\">103</sup> עדן עין לא ראתה אלקי' זולתך יעשה למחכה לו פי' עין לא ראתה משום דעכשיו אין אור החכ' בבחי' ראי' דעין רק בבחי' השגה ומח' עיונית ע\"כ אמרו עין לא ראתה עדיין כו' והיינו בבחי' פנימי' ועצמי' דחכ\"ע כמו שהוא ממש מבלי אמצעות לבוש כלל שהוא בחי' עדן העצמי אשר עין לא ראתה עדיין רק אלקים זולתך יעשה למחכה לו לע\"ל כנ\"ל וד\"ל.",[["1916","103","<b>גבי עדן עין לא ראתה</b>: ישעי' סד, ג (הובא לעיל). ברכות לד, ב."]]],[2101920334,"<h3><i>נוסח אחר</i>: להבין ענין קי\"ס</h3>\n<b>להבין</b><sup data-n=\"1917\">1</sup> ענין קי\"ס שנקרע הים לי\"ב קרעים כמ\"ש לגוזר<sup data-n=\"1918\">2</sup> י\"ס לגזרים, גזרים רבים לכל שבט ושבט קרע בפ\"ע, מה צורך הי' להיות לכל שבט קרע מיוחד דוקא. גם צ\"ל מ\"ש בישעי' על לע\"ל והניף<sup data-n=\"1919\">3</sup> ידו על הנהר בעים רוחו והכהו לשבעה נחלים כו' והי' מסילה לשאר עמו כו'. ופי' לשאר עמו הם בני הגולה מד' מלכיות שבקיבוץ גליות לע\"ל יצטרכו לילך דרך הנהר הלז והקב\"ה יניף ידו עליו והכהו לז' נחלים שבהם יעברו בנ\"י ביבשה בתוך מי הנהר הנ\"ל. וצ\"ל מדוע אז יהי' רק שבעה גזרים דוקא ומה נשתנה מקי\"ס שעברו בנ\"י בו ביבשה בצאתם מארץ מצרים שאז נקרע לי\"ב קרעים כנ\"ל.\n<b>הנה</b> ענין הנהר הנ\"ל הוא נהר פרת וכמ\"ש בי' בנהר פרת והנהר<sup data-n=\"1920\">4</sup> הרביעי הוא נהר פרת וארז\"ל על מלת הוא, הוא פרת דמעיקרא, כלומר אותו הנהר עצמו היוצא מעדן, כמ\"ש ונהר<sup data-n=\"1921\">5</sup> יוצא מעדן להשקות כו', ואח\"כ ומשם יפרד והי' לארבעה ראשים שם האחד גיחון<sup data-n=\"1922\">6</sup> כו', והנהר הרביעי הוא פרת ונקרא בשמו של הנהר הראשון עצמו אשר ממנו נפרדו הארבע ראשים הנ\"ל, ונהר הלז הוא שיבקע לע\"ל ועליו הוא שיניף הקב\"ה את ידו והכהו לשבעה נחלים כו'.\n<b>ולהבין</b> כ\"ז צ\"ל מתחלה ענין קי\"ס מהו, שנחם אותם ה' דרך המדבר ים סוף כדי שיקרע הים לפניהם ולא נחם אותם דרך<sup data-n=\"1923\">7</sup> ארץ פלשתים הקרובה",[["1917","1","<b>להבין ענין קי\"ס</b>: מאמר זה נדפס מגוכי\"ק הצ\"צ. והוא נוסח שני ממאמר הקודם. וע\"ש בהמ\"מ."],["1918","2","<b>לגוזר י\"ס לגזרים</b>: תהלים קלה, יג. וראה לעיל בהמ\"מ לנוסח הראשון."],["1919","3","<b>והניף ידוע על הנהר</b>: ישעי' יא, טו-טז."],["1920","4","<b>והנהר הרביעי הוא נהר פרת וארז\"ל על מלת הוא הוא פרת דמעיקרא</b>: ע\"פ בראשית ב, יד. בכורות נה, ב ובפירש\"י שם.."],["1921","5","<b>ונהר יוצא מעדן . . ומשם יפרד</b>: בראשית ב, י ואילך."],["1922","6","<b>גיחון</b>: אוצ\"ל: פישון (כבכתוב שם)."],["1923","7","<b>דרך ארץ פלשתים</b>: בשלח יג, יז."]]],[2101920335,"יותר כו'. ומ\"ש בספרים כדי להמית את מצרים על שפת הים כמ\"ש וירא<sup data-n=\"1924\">8</sup> ישראל את מצרים מת על שפת הים כו' גם זה דחוק, כי בשביל זה בלבד לא הי' צריך לסבב סיבות כ\"כ כי כל יכול הוא להמית גם בלא\"ה, אלא שהי' צריך זה גם בשביל ישראל עצמם שיקרע הים דוקא לפניהם ועי\"ז יהי' להם תועלת אח\"כ לענין יכולת קבלת התורה כו'.\n<b>ולהבין</b> זה מהו שייכות קדימת ענין קי\"ס למ\"ת, צ\"ל תחילה ענין הים כי הנה ידוע המאמר<sup data-n=\"1925\">9</sup> בזהר ע\"פ זה הים גדול ורחב ידים כו' שיש בחי' ים למעלה ויש בו ארבין ונונין כו', והענין הוא עד\"מ כמו הים<sup data-n=\"1926\">10</sup> הגשמי שיש בו מכל מה שיש ביבשה והוא מכסה עליהם מלמעלה ומסתיר אותם שלא יתראו ביבשה, וכמארז\"ל בריות שבים אלמלא עולות ביבשה מיד מתות וכו', וכן הוא מכסה ומעלים לגבי בריות שביבשה שלא יוכלו לרדת בים וכמארז\"ל בריות שביבשה אלמלא יורדות בים כו', כמ\"כ הוא ענין הים שלמעלה שהוא בחי' מל'<sup data-n=\"1927\">11</sup> דאצי' שנקראת ים סוף פי' לפי שהיא סופא דכל דרגין שבאצי' והיא מפסקת בין האצי' לבי\"ע שאינה מניחה אורות האצי' להתפשט בבי\"ע וגם שלא יוכלו הנבראי' בבי\"ע לעלות באצי', ויש בה ארבין ונונין הנשמות נק' נונין והם בחי' נשמות דאצי' כמו<sup data-n=\"1928\">12</sup> נשמת רב המנונא סבא, כי כמו הדגים שבים הם מובלעים בתוך מי הים ומתאחדים עמהם בתכלית עד שהמים מתפשטים בתוך תוכיותם כך הנשמות שבאצי' הם בבחי' התכללות במל' דאצי' ובטלים בה בתכלית כי עובר<sup data-n=\"1929\">13</sup> ירך אמו הוא, והמלאכי' נק' ארבין כי כמו הספינות שבים שעם היותם ג\"כ שקועים בים כמו הדגים אבל מ\"מ הבדל גדול יש ביניהם שהדגים מובלעים בתוכיות הים ממש והיו לאחדי' עמו משא\"כ הספינות שאין המים מתפשטים ונבלעים בתוכיותם כלל אדרבה עיקר פעולתם הוא בהיפוך שהם מפסיקים בין מי המים ומונעים התפשטותם עד שעי\"ז יוכלו דרי היבשה לירד בהם ולא ימותו מפני מימי הים כי דופן הספינה מפסיק בינם לבינו. כמ\"כ הוא ענין המלאכי' למעלה שאינן מתבטלים במל' דאצי' כמו הנשמות כי אדרבה המלאכים המה יש ודבר בפ\"ע מלאך מיכאל כו' והיינו מפני שיש להם גופות והגופות הם הגורמים בחי' היש של נשמתם שלצד היותה מלובשת בגוף לכן אינה מתבטלת בתכלי' בימא עילאה הוא המל' כנ\"ל, כי הגוף מפסיק כנ\"ל משא\"כ הנשמות בעודם למעלה בבחי' עיבור במל' הם מופשטים מגוף כידוע.",[["1924","8","<b>וירא ישראל את מצרים</b>: בשלח יד, ל."],["1925","9","<b>המאמר בזהר ע\"פ זה הים גדול</b>: תהלים קד, כה ואילך. ראה זח\"ב מח, ב."],["1926","10","<b>הים הגשמי שיש בו מכל מה שיש ביבשה . . אלמלא עולות ביבשה</b>: ראה חולין קכז, א."],["1927","11","<b>מל' דאצי' שנקראת ים סוף</b>: ראה זח\"ג רנה, ב. רנו, ב."],["1928","12","<b>כמו נשמת רב המנונא סבא</b>: ראה זח\"א ו, א. זח\"ג קפז, ב. ביאוה\"ז לאדהאמ\"צ קמט, א. סידור עם דא\"ח קה, א. סה\"מ תקס\"ה ח\"ב ע' תרחץ. תו\"ח בראשית ד, ד."],["1929","13","<b>עובר ירך אמו</b>: גיטין כג, ב."]]],[2101920336,"<b>והנה</b> ביאור ענין מל' דאצי' שנקראת ים הוא כי בחי' המל' הוא ענין דיבור העליון שבדבר<sup data-n=\"1930\">14</sup> ה' שמים נעשו כו', וכל העשרה מאמרות שהם המשכות פרטיות מי\"ס דאצי' כולם מתלבשים באותיות הדיבור העליון כמ\"ש ויאמר<sup data-n=\"1931\">15</sup> אלקים יהי אור כו', והדיבור הוא מעלים ומכסה עליהם עד\"מ בגשמיות האותיות המקבלים השכל הרי המה מצפינים אותו ומעלימים אותו עד שלזאת יש מי אשר לא יוכל להבין השכל הגנוז בהם עד שיתפוס האותיות כידוע, כמ\"כ אותיות הדיבור עליון מעלים ומכסה על האורות עליונים דאצי' המתלבשים בו ועי\"ז אין הנבראי' דבי\"ע יכולים להשיגם ולתופסם כנ\"ל, וכן אין האורו' עליונים או הנשמות דאצי' יכולים לירד ולהתגלות בבי\"ע כי הדיבור מעכבם כנ\"ל ולכן נקרא ים.\n<b>וזה</b> הי' ענין קי\"ס שנאמר ובנ\"י<sup data-n=\"1932\">16</sup> הלכו בתוך הים ביבשה כו' דהיינו שמההעלם דים נעשה גלוי ויבשה כלומר שלא יסתיר עוד הדיבור העליון על האורות דאצי' המתלבשי' בו ויתגלו האורות דאצי' לנבראי' דבי\"ע. ויש בזה שני פירושים אם שהאורות דאצי' יורדי' ונמשכים בבי\"ע מלמעלה למטה וזהו פי' האריז\"ל בפע\"ח שקורא לקי\"ס בשם לידה כלומר שהנשמו' דאצי' הנק' נונין יורדי' ומתגלים בבי\"ע ממעלה למטה וזהו ובני ישראל ופירושו הם הנשמות דאצי' הלכו ביבשה שנתגלו בבי\"ע מתוך העלמם בים הנ\"ל, ואם לפי הנראה מדברי הרשב\"י ע\"ה בזהר הוא ענין העלאת הנשמו' דבי\"ע בעולם האצי' ופי' ובנ\"י הם הנשמו' דבי\"ע הלכו ביבשה בתוך הים שנתעלו באצי'. ובין כך ובין כך הוא ע\"י קריעת הים המעלים והמכסה דהיינו הפסקת אותיות הדיבור ובקיעותם שלא יסתירו על האורות הכמוסים בתוכם ואז יתגלו עצמיות האורות הנ\"ל לחוץ דהיינו בבי\"ע בין ע\"י עליה בין ע\"י ירידה כנ\"ל, ולכן נקרע הים לי\"ב קרעים דוקא כי כללות מספר הנשמות שבבי\"ע המקבלים מן המל' המה נחלקים לי\"ב בחי' בכלל, וכן המלאכים הנ\"ל נחלקים ג\"כ לי\"ב מחנות ונק' י\"ב<sup data-n=\"1933\">17</sup> בקר שהים עומד עליהם מלמעלה עם היותם דרך כלל ארבע מיכאל גבריאל רפאל אוריאל הנה כל א' מהם מתחלק גם הוא לשלש והם כמו ג'<sup data-n=\"1934\">18</sup> פרקין שיש בכל יד ורגל משתי הידות ורגלי האדם פרק העליון שבו האצבעות הוא בחי' חב\"ד כו' וכך גם הי\"ב שבטים בכללותם הם ד' דגלים דגל<sup data-n=\"1935\">19</sup> מחנה ראובן וכולל ג' שבטים וכן דגל מחנה יהודה כו'. וכמו שבהיותם בבי\"ע ומקבלים מן המל' דאצי' המה נחלקי' לי\"ב בחי' אלו אשר כל או\"א מקבל שפעו בפרטיות בהבדל מזולתו כך גם כשמצטרכי' להתעלות בעולם האצי' ע\"י קי\"ס המפסיק כנ\"ל אזי יש לכל א' ג\"כ שפע ודרך אחרת בפרט מובדלת מזולתו ולכן נקרע הים לי\"ב קרעים לכל שבט ושבט בפ\"ע כנ\"ל. ולכן הי' זה פעולה לשיהיו יכולים לקבל התורה אח\"כ שענין קבלת התורה לישראל שלמטה",[["1930","14","<b>שבדבר ה' שמים נעשו</b>: תהלים לג, ו."],["1931","15","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."],["1932","16","<b>ובנ\"י הלכו בתוך היום</b>: ראה בשלח יד, כט."],["1933","17","<b>י\"ב בקר שהים עומד</b>: ראה מלכים א ז, כה. זח\"א רמא, א."],["1934","18","<b>ג' פרקין . . יד ורגל</b>: ראה זהר שם."],["1935","19","<b>דגל מחנה ראובן . . יהודה</b>: במדבר ב, ג."]]],[2101920337,"הוא כדוגמת התגלות הארת האצי' לי\"ב מחנות שכינה שבבי\"ע הנ\"ל, שזה א\"א להיות כ\"א ע\"י קדימת קריעת הים ובקיעתו שהוא בקיעת הפרסא המפסקת כנ\"ל.\n<b>והנה</b> ענין מ\"ת הוא בחי' היום<sup data-n=\"1936\">20</sup> לעשותם בעוה\"ז בקיום המצות במעשה ומצות ת\"ת<sup data-n=\"1937\">21</sup> כנגד כולם ולמחר לקבל שכרם היינו לע\"ל, וענין קיבול השכר ההוא הוא ענין השפעת פנימית התורה לישראל שהוא ענין התגלות טעמי המצות שכעת הם כמוסים ונעלמים מעין כל חי ולע\"ל יתגלו לישראל וכדפרש\"י<sup data-n=\"1938\">22</sup> ע\"פ ישקני מנשיקות פיהו וגו' כנודע וזהו ענין משיח<sup data-n=\"1939\">23</sup> שנאמר בו הנה ישכיל עבדי מאברהם ונשא מיצחק כו' וגבה מאד<sup data-n=\"1940\">24</sup> אותיו' אדם, שיהי' למעלה מבחי' אדה\"ר ומבחי' מרע\"ה והוא ילמד דעת לכל העם בהשגת פנימי' התורה, כי אם לפי פשוטו שילמד תורה הנגלית לנו ולבנינו אינו מובן איך יוכל הא' לשאת אלפי' רבבות בנ\"א שיקומו בתח\"ה, ועוד והלא אז יקומו בתח\"ה כל הגדולי' אשר היו בארץ כמשה שכבר יודעי' כל התורה כו', אלא הענין כי אז יהי' הלימוד בפנימי' התורה שארוכה<sup data-n=\"1941\">25</sup> מארץ מדה ויש בה עליות רבות לאין קץ ותכלית, והנה בכדי שיוכלו לעלות ולהגיע למדרגת קבלת פנימית התורה הנ\"ל יצטרכו ג\"כ לעבור דרך הנהר פרת הנ\"ל כמו שלצורך קבלת התורה בסיני הוצרכו לעבור דרך ים סוף כו'.\n<b>והענין</b> כי הנה כמו שיש למעלה בחי' אותיות הדיבור כדכתי' בהדיא כי<sup data-n=\"1942\">26</sup> הוא אמר ויהי ובדבר<sup data-n=\"1943\">27</sup> ה' כו' כך יש שם ג\"כ בחי' אותיות המחשבה, ועם היות כי<sup data-n=\"1944\">28</sup> לא מחשבותי מחשבותיכם כתי' מ\"מ בחי' מחשבה הוא, וכמו שהדיבור העליון עם היות שאינו ג\"כ מערך וסוג הדיבור שלנו אעפ\"כ הוא בחי' כיסוי ולבוש המעלים לגבי האורות שלמעלה הימנו והן בחי' המדות עליונות הגדולה והגבורה כו' שמתלבשות ומתכסות בתוך הדיבור כו', וכן גם השכל שבמוח מתלבש בדיבור כשמדבר איזו השכלה כו', כמ\"כ ממש גם אותיות המחשבה הן בחי' כיסוי ולבוש להשכל שבמוח וגם אפי' להמדות שבלב אלא שהיא בחי' לבוש פנימי מהדיבור והדבור מקבל מהמחשבה שהרי אינו מדבר אלא מה שחושב אבל מ\"מ היא בחי' לבוש ומעלמת ומכסית על האור הגנוז בתוכה שלא יוכלו להשיגו אלא באמצעות המחשבה דוקא דהיינו ע\"י תפיסת והשגת האותיות כו', ובחי' המחשבה<sup data-n=\"1945\">29</sup> היא הנקראת בשם נהר ולא בשם ים כמו שנק' הדבור, לפי שהמחשבה היא תמידית שהרי השקט לא יוכל בלי מחשבה אלא רעיונות עוברות תמיד במוחו מזה ומזה ולכן נק' נהר שפירושו ענין המשכה כמו דכתיב ונהרו<sup data-n=\"1946\">30</sup> אליו כל הגוים",[["1936","20","<b>היום לעשותם . . ולמחר לקבל שכרם</b>: ואתחנן ז, א. עירובין כב, א."],["1937","21","<b>ת\"ת כנגד כולם</b>: פאה פ\"א, מ\"א."],["1938","22","<b>וכדפרש\"י ע\"פ ישקני</b>: שה\"ש א, ב."],["1939","23","<b>משיח . . הנה ישכיל עבדי</b>: ישעי' נב, יג. וראה ת\"י וילקוט שמעוני שם."],["1940","24","<b>מאד אותי' אדם</b>: זהר פנחס רמו, ב."],["1941","25","<b>שארוכה מארץ מדה</b>: איוב יא, ט."],["1942","26","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["1943","27","<b>ובדבר ה'</b>: ראה תהלים שם, ו."],["1944","28","<b>כי לא מחשבותי</b>: ישעי' נה, ח."],["1945","29","<b>המחשבה . . נהר</b>: נסמן לע' רסב."],["1946","30","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב."]]],[2101920338,"כו' ופי' שהמחשבה נמשכת תמיד מהשכל וז\"ש ונהר יוצא מעדן יוצא בתמידית מעדן הוא החכמה כו'.\n<b>והנה</b> ענין קיבול השכר שלע\"ל הוא בחי' התגלות עצמיו' עדן העליון כמארז\"ל עין<sup data-n=\"1947\">31</sup> לא ראתה אלקים זולתך זה עדן יעשה למחכה לו והיינו לע\"ל כו'. אמנם ענין גילוי זה הוא בחי' התגלות עצמיו' העדן<sup data-n=\"1948\">32</sup> שהיא החכמה ולא באמצעות הנהר הנ\"ל שהוא בחי' אותיות המחשבה המלבישות את החכמה, כי תפיסת החכמה שבאמצעות המחשבה אינו ענין תפיסת עצמיותה של החכמה כי הרי אדרבה המחשבה מסתרת ומעלמת על השכל כנ\"ל ואינה מגלית רק הארה בלבד כו', אלא ענין גילוי זה הוא התגלו' עצמיו' החכמ' כמו שהיא במהותה ועצמותה שהיא ביתר שאת ויתר עז לאין קץ ותכלית מכמו הגילוי שע\"י אמצעות אותיות המחשבה, וכמ\"ש בפע\"ח<sup data-n=\"1949\">33</sup> מעשה מהאריז\"ל שנמנם רגע א' ונכנם אליו תלמידו הר\"א ואמר לו שהשיג ברגע זו סודות עליוני' שאם הי' מגלה אותם הי' צריך להיות שהיית זמן ס' שנה, וזה יפלא לכאורה איך יכול לתפוס במחשבתו ברגע א' מה שצריך לומר בדיבור זמן ס' שנה, עם היות כי המחשבה היא כללית לגבי הדיבור היינו שמה שצריך לדבר בשעה יחשוב במחשבתו בזמן רבע או חצי שעה אבל לא בהפלגת הערך כ\"כ מס' שנה לרגע אחת כו', אבל הענין משום שאופן השגתו הוא בחי' ראיית עצמיו' החכמה לא כמו שמתלבשת ע\"י אותיות ולכן כשיצטרך להלביש חכמה זו באותיו' יצטרך גם מרגע א' של סקירת עצמיו' החכמה לחשוב ולדבר ס' שנה כו'. והנה ע\"ד ואופן השגה וסקירה זו הוא שיהי' גילוי טעמי מצות לע\"ל שזהו ענין שנאמ' עליו כעת עין לא ראתה כו' לפי שכעת מקבלים באמצעות המחשבה כו' וזה שילמד להם משיח כמ\"ש בו הנה ישכיל כו' כנ\"ל, והיינו בחי' גילוי טעמי מצות כמו שהן דהיינו פנימי' חכמתו וטוב טעמו ית' שיש לו ברצון של אותו המצוה, ולכן יצטרך להיות ע\"י בקיעת הנהר הנ\"ל דהיינו שלא להיו' אותיות המחשבה מסתירים אלא שיתגלה עצמיות העדן כמו שהוא בעצמותו כו'. וז\"ש רז\"ל על נהר פרת הוא דמעיקרא, פי' כי הנה מ\"ש והנהר הרביעי הוא פרת היינו בחי' מל' דאצי' אלא שמ\"מ הוא דמעיקרא כלומר אותו הנהר עצמו שיוצא מעדן כי שרש הדיבור בהמחשבה וכמ\"ש שם<sup data-n=\"1950\">34</sup> הגדולה לאה ושם הקטנה רחל פי' שם ה' קטנה רחל ושם ה' גדולה לאה שהן ב' ההין דשם הוי' בינה ומל' ואותו נהר הלז הוא שיבקע לע\"ל כמובן מכל הנ\"ל וד\"ל.\n<b>והנה</b> מ\"ש לע\"ל והכהו לז' נחלים ובקי\"ס הי' לי\"ב גזרים כו' הענין<sup data-n=\"1951\">*</sup>.",[["1947","31","<b>עין לא ראתה</b>: ישעי' סד, ג. ברכות לד, ב."],["1948","32","<b>העדן שהיא החכמה</b>: פרדס שעה\"כ מערכת עדן."],["1949","33","<b>בפע\"ח</b>: שער קשעהמ\"ט פ\"א. וראה לעיל בהמ\"מ לנוסח הראשון."],["1950","34","<b>שם הגדולה לאה</b>: ויצא כט, טז. וראה ע\"ח שער יעקב ולאה (של\"ז) פ\"ד. סה\"מ תקס\"ה ח\"ב ע' תתקלב."],["1951","*","ע\"כ נרשם בגוכתי\"ק."]]],[2101920339,"<h3>מה יפו פעמיך</h3>\n<b>מה</b><sup data-n=\"1952\">1</sup> יפו<sup data-n=\"1953\">2</sup> פעמיך בנעלים כו', הנה הפסוק<sup data-n=\"1954\">3</sup> הזה נאמר על כנ\"י בשעה שהיו עולים לרגל כמ\"ש שלש<sup data-n=\"1955\">4</sup> פעמים בשנה יראה כו' את פני ה' אלקיך, ועתה משחרב בהמ\"ק תפלה<sup data-n=\"1956\">5</sup> במקום קרבן שבחי' יראה את פני ה' אלקיך הוא עתה בתפלה, רק שאז הי' השראת השכינה למטה במקום גשמי במקדש כמ\"ש ועשו<sup data-n=\"1957\">6</sup> לי מקדש ושכנתי כו', לזה הי' אז בהתחלקות ג'<sup data-n=\"1958\">7</sup> זמנים פסח שבועות סוכות, נגד ג' אבות אברהם יצחק יעקב, ועתה בתפלה השראה זו היא בבחי' הרוחניות הוא בלי התחלקות, כי התפלה כלול מג' בחי' אברהם יצחק יעקב, כי תפלות אבות תיקנום, כי יש פסוקים בתפלה מבחי' אברהם בחי' אהבה, ויש בחי' יראה, ויש מבחי' יעקב מדת הרחמנות כמו אתה<sup data-n=\"1959\">8</sup> ה' לא תכלא רחמיך כו'.\n<b>והנה</b> כתי' כה<sup data-n=\"1960\">9</sup> אמר ה' ליעקב אשר פדה את אברהם, כי הנה עיקר בקשת הרחמים בשתי ברכות שלפני ק\"ש הוא על ניצוץ אלקות שאין לנו אהוי\"ר מחמת העדר ההתבוננות, כי בחי' בינה הוא המוליד אהוי\"ר, לזה אנו מבקשים",[["1952","1","<b>מה יפו</b>: מאמר זה נדפס כאן מכת\"י מניח שרשם המאמר בסמיכות לזמן שמיעתו מכ\"ק אדה\"ז (כת\"י 1113 מז, א), ובסוף המאמר נרשם בגוכי\"ק אדמו\"ר הצ\"צ: תורת אדמו\"ר בשקלאב כתבה ר' זלמן רוזעש.\nוראה גם מאמר זה (מלבד הביאור הנדפס לקמן) בתוס' הגהות ואיזה שינויים בלקו\"ת שה\"ש מג, ב. ובאריכות הביאור מכ\"ק אדהאמ\"צ בס' מאמרי אדהאמ\"צ נ\"ך ע' שיא ואילך. ובשינויים והגהות וביאורים מאדמו\"ר הצ\"צ באוה\"ת שה\"ש ח\"ב ע' תקפד. ח\"ג ע' תתקצ. תתקצה. ובסה\"מ תרל\"ג ח\"א ע' ד ואילך (בתוך ד\"ה ר\"א יהיב פרוטה לעני). ובסה\"מ פר\"ת ע' קכט ואילך (בתוך ד\"ה צהר תעשה לתיבה). וראה גם דרוש אחר ד\"ה מה יפו פעמיך בסה\"מ תקס\"ג ח\"א ע' רמח. ומקבילו בדרמ\"צ קעה, ב. ובכ\"מ.\n[המאמר הנדפס כאן נמצא ג\"כ בכת\"י 1116 שבו מאמרים רבים משנת תקע\"ב. וכן בעוד כת\"י. ובכמה מופיע המאמר בכותרת: שבת פ' שמיני תקע\"ב שקלאב. ונמצא ג\"כ בכתבי-יד מאוחרים יותר עם תאריכים של אמירת המאמר גם ע\"י אדמו\"ר הצ\"צ: ”תורת אדמו\"ר מ\"מ על חתונה בן חייקעל הנגיד מהרדישץ פ' פקודי תקצ\"ד לפ\"ק\". ובמ\"א בכותרת: בע\"ה חוה\"מ סוכות תקצוי\"ו. וראה מאמר המקביל באוה\"ת על סידור (דרושים לחתונה) ע' רסג בכותרת: מה ששמענו מפכ\"ק אדמו\"ר בק' באייאו על חתונת בן מוהר\"ד בהרב ר\"ר אברהם באזמו\"ר נ\"ע י\"ב סיון שנת תקצ\"ו]."],["1953","2","<b>מה יפו פעמיך בנעלים</b>: שה\"ש ז, ב."],["1954","3","<b>הפסוק הזה נאמר על כנ\"י בשעה שהיו עולים לרגל</b>: סוכה מט, ב. חגיגה ג, א. שהש\"ר עה\"פ."],["1955","4","<b>שלש פעמים בשנה</b>: משפטים כג, יז. פ' ראה טז, טז. ועוד."],["1956","5","<b>תפלה במקום קרבן . . אבות תקנום</b>: ברכות כו, א-ב."],["1957","6","<b>ועשו לי מקדש</b>: תרומה כה, ח."],["1958","7","<b>ג' זמנים פסח שבועות סוכות נגד ג' אבות אברהם יצחק ויעקב</b>: זח\"ג רנז, ב. וראה בארוכה לקו\"ת פינחס עו, ב. שם דרושים לר\"ה נח, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תנ. סה\"מ תרל\"ג ח\"ב ע' תסד."],["1959","8","<b>אתה ה' לא תכלא רחמיך</b>: תפילת הודו. ע\"פ תהלים מ, יב."],["1960","9","<b>כה אמר ה' ליעקב אשר פדה את אברהם</b>: ע\"פ ישעי' כט, כב. שם: ”לבית יעקב\", אבל כן הובא בתניא פל\"ב ופמ\"ה ובכ\"מ — ראה ”הערות ותיקונים\" לתניא שם. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' פח. דברים ח\"א ע' שלב."]]]]});
